NAME = 'KLV: Klingon Language Version of the World English Bible'
BOOK = 'Isaiah'

CHAPTERS = {
    1: {
        1: "The leghtaHghach vo' Isaiah the puqloD vo' Amoz, nuq ghaH leghta' concerning Judah je Jerusalem, Daq the jajmey vo' Uzziah, Jotham, Ahaz, je Hezekiah, joHpu' vo' Judah.",
        2: "Qoy, chal, je 'Ij, tera'; vaD joH'a' ghajtaH jatlhpu': jIH ghaj je'moHta' je qempu' Dung puqpu', je chaH ghaj lotlhpu' Daq jIH.",
        3: "The Qa' SovtaH Daj ghajwI', je the SarghHom Daj master's SopDaq; 'ach Israel ta'be' Sov, wIj ghotpu yImev qel.",
        4: "toH yemqu'taH Hatlh, a ghotpu loaded tlhej He'taHghach, a tIr vo' evildoers, puqpu' 'Iv Da qal! chaH ghaj lonta' joH'a'. chaH ghaj muSqu' the le' wa' vo' Israel. chaH 'oH Hoppu' je DoH.",
        5: "qatlh should SoH taH beaten latlh, vetlh SoH Daw' latlh je latlh? The Hoch nach ghaH rop, je the Hoch tIq puj.",
        6: "vo' the bem vo' the qam 'ach Daq the nach pa' ghaH ghobe' QaQtaHghach Daq 'oH: QIDpu'ghachmey, welts, je poSmoH 'oy'mey. chaH ghajbe' taH SoQ, ghobe' bandaged, ghobe' soothed tlhej Hergh.",
        7: "lIj Hatlh ghaH moB. lIj vengmey 'oH meQpu' tlhej qul. novpu' Sop lIj puH Daq lIj Daq, je 'oH ghaH moB, as lujqu'pu' Sum novpu'.",
        8: "The puqbe' vo' Zion ghaH poS rur a shelter Daq a HIq wIj, rur a hut Daq a yotlh vo' melons, rur a qatpu' veng.",
        9: "Unless joH'a' vo' Armies ghajta' poS Daq maH a very mach chuv, maH would ghaj taH as Sodom; maH would ghaj taH rur Gomorrah.",
        10: "Qoy the mu' vo' joH'a', SoH DevwIpu' vo' Sodom! 'Ij Daq the chut vo' maj joH'a', SoH ghotpu vo' Gomorrah!",
        11: "“nuq 'oH the qevmey vo' lIj nobmey Daq jIH?,” jatlhtaH joH'a'. “jIH ghaj ghajta' yap vo' the meQqu'pu' nobmey vo' 'ermey, je the ror vo' Sopta' Ha'DIbaH. jIH yImev tIv Daq the 'Iw vo' Qa'mey, joq vo' 'erHommey, joq vo' male goats.",
        12: "ghorgh SoH ghoS Daq nargh qaSpa' jIH, 'Iv ghajtaH poQta' vam Daq lIj ghop, Daq gho' wIj bo'DIjmey?",
        13: "qem ghobe' latlh lI'be' nobmey. He' ghaH an qabqu'boghghach Daq jIH; chu' maSmey, Sabbaths, je convocations: jIH ta'laHbe' SIQ tlhej mIghtaHghach yejmey.",
        14: "wIj qa' muS lIj chu' maSmey je lIj wIv yupma'mey. chaH 'oH a burden Daq jIH. jIH 'oH Doy' vo' qeng chaH.",
        15: "ghorgh SoH ngeH vo' lIj ghopmey, jIH DichDaq So' wIj mInDu' vo' SoH. HIja', ghorgh SoH chenmoH law' qoy'taHghachmey, jIH DichDaq ghobe' Qoy. lIj ghopmey 'oH teblu'ta' vo' 'Iw.",
        16: "Seng tlhIH'egh, chenmoH SoH'egh Say. lan DoH the mIghtaHghach vo' lIj ta'mey vo' qaSpa' wIj mInDu'. mev Daq ta' mIghtaHghach.",
        17: "ghoj Daq ta' QaQ. nej ruv. QaH the Suvta'. noH the vav ghajbe'. tlhob vaD the Heghbe'nal.”",
        18: "“ghoS DaH, je chaw' maH meq tay',” jatlhtaH joH'a': “'a' lIj yemmey taH as Doq, chaH DIchDaq taH as chIS as chuchHommey. 'a' chaH taH Doq rur Doq, chaH DIchDaq taH as wool.",
        19: "chugh SoH 'oH willing je loblu'taH, SoH DIchDaq Sop the QaQ vo' the puH;",
        20: "'ach chugh SoH Qo' je lotlh, SoH DIchDaq taH Soppu' tlhej the 'etlh; vaD the nujDu' vo' joH'a' ghajtaH jatlhpu' 'oH.”",
        21: "chay' the voqmoH veng ghajtaH moj a naybe'wI'! ghaH ghaHta' teblu'ta' vo' ruv; QaQtaHghach yIntaH Daq Daj, 'ach DaH chotwI'pu'.",
        22: "lIj baS chIS ghajtaH moj Dochmey lI'be', lIj HIq DuD tlhej bIQ.",
        23: "lIj joHHom 'oH lotlhqu', je tlhejwI'pu' vo' HejwI'pu'. Hoch muSHa'taH nepHuchmey, je tlha'taH after popmey. chaH yImev noH the vav ghajbe', ghobe' ta'taH the cause vo' the Heghbe'nal ghoS Daq chaH.",
        24: "vaj the joH, joH'a' vo' Armies, the HoS wa' vo' Israel, jatlhtaH: “toH, jIH DichDaq tlhap relief vo' wIj jaghpu', je bortaS jIH'egh vo' wIj jaghpu';",
        25: "je jIH DichDaq tlhe' wIj ghop Daq SoH, thoroughly woD DoH lIj Dochmey lI'be', je DichDaq tlhap DoH Hoch lIj baS lI'be'.",
        26: "jIH DichDaq nobHa' lIj judges as Daq the wa'Dich, je lIj qeSwI'pu' as Daq the tagh. Afterward SoH DIchDaq taH ja' ‘The veng vo' QaQtaHghach, a voqmoH vengHom.'",
        27: "Zion DIchDaq taH toDta' tlhej ruv, je Daj choHtaH tlhej QaQtaHghach.",
        28: "'ach the QIH vo' yemwI'pu' je yemwI'pu' DIchDaq taH tay', je chaH 'Iv lon joH'a' DIchDaq taH Soppu'.",
        29: "vaD chaH DIchDaq taH tuH vo' the Sor'a'mey nuq SoH ghaj neH, je SoH DIchDaq taH mISmoHpu' vaD the wIjghachHommey vetlh SoH ghaj wIvpu'.",
        30: "vaD SoH DIchDaq taH as an Sor'a' 'Iv Sornav ngabtaH, je as a wIjghachHom vetlh ghajtaH ghobe' bIQ.",
        31: "The HoS DichDaq taH rur tinder, je Daj vum rur a qulHom. chaH DichDaq both meQ tay', je ghobe' wa' DichDaq meQbe'moH chaH.”",
    },
    2: {
        1: "vam ghaH nuq Isaiah the puqloD vo' Amoz leghta' concerning Judah je Jerusalem.",
        2: "'oH DIchDaq qaS Daq the latter jajmey, vetlh the HuD vo' joH'a' tuq DIchDaq taH established Daq the top vo' the Hudmey, je DIchDaq taH raised Dung the hills; je Hoch tuqpu' DIchDaq flow Daq 'oH.",
        3: "law' ghotpu' DIchDaq jaH je jatlh, “ghoS, let's jaH Dung Daq the HuD vo' joH'a', Daq the tuq vo' the joH'a' vo' Jacob; je ghaH DichDaq ghojmoH maH vo' Daj Hemey, je maH DichDaq yIt Daq Daj Hemey.” vaD pa' vo' Zion the chut DIchDaq jaH vo', je the mu' vo' joH'a' vo' Jerusalem.",
        4: "ghaH DichDaq noH joj the tuqpu', je DichDaq decide concerning law' ghotpu'; je chaH DIchDaq qIp chaj swords Daq plowshares, je chaj spears Daq pruning hooks. Hatlh DIchDaq ghobe' lift Dung 'etlh Daq Hatlh, ghobe' DIchDaq chaH ghoj veS vay' latlh.",
        5: "tuq vo' Jacob, ghoS, je chaw' maH yIt Daq the wov vo' joH'a'.",
        6: "vaD SoH ghaj lonta' lIj ghotpu, the tuq vo' Jacob, because chaH 'oH tebta' vo' the pemHov 'o', tlhej chaH 'Iv practice divination rur the Philistines, je chaH clasp ghopmey tlhej the puqpu' vo' foreigners.",
        7: "chaj puH ghaH teblu'ta' vo' baS chIS je SuD baS, ghobe' ghaH pa' vay' pItlh vo' chaj treasures. chaj puH je ghaH teblu'ta' vo' horses, ghobe' ghaH pa' vay' pItlh vo' chaj Dujmey.",
        8: "chaj puH je ghaH teblu'ta' vo' idols. chaH lalDan toy' the vum vo' chaj ghaj ghopmey, vetlh nuq chaj ghaj fingers ghaj chenmoHta'.",
        9: "loD ghaH qempu' low, je mankind ghaH humbled; vaj yImev forgive chaH.",
        10: "'el Daq the nagh, je So' Daq the dust, vo' qaSpa' the ghIjvIptaH vo' joH'a', je vo' the batlh vo' Daj majesty.",
        11: "The lofty looks vo' loD DichDaq taH qempu' low, the haughtiness vo' loDpu' DichDaq taH bowed bIng, je joH'a' mob DichDaq taH exalted Daq vetlh jaj.",
        12: "vaD pa' DichDaq taH a jaj vo' joH'a' vo' Armies vaD Hoch vetlh ghaH proud je haughty, je vaD Hoch vetlh ghaH qengta' Dung; je 'oH DIchDaq taH qempu' low:",
        13: "vaD Hoch the cedars vo' Lebanon, vetlh 'oH jen je qengta' Dung, vaD Hoch the Sor'a'mey vo' Bashan,",
        14: "vaD Hoch the jen Hudmey, vaD Hoch the hills vetlh 'oH qengta' Dung,",
        15: 'vaD Hoch lofty tower, vaD Hoch fortified reD,',
        16: "vaD Hoch the ships vo' Tarshish, je vaD Hoch bel imagery.",
        17: "The loftiness vo' loD DIchDaq taH bowed bIng, je the haughtiness vo' loDpu' DIchDaq taH qempu' low; je joH'a' mob DIchDaq taH exalted Daq vetlh jaj.",
        18: 'The idols DIchDaq utterly juS DoH.',
        19: "loDpu' DIchDaq jaH Daq the caves vo' the rocks, je Daq the holes vo' the tera', vo' qaSpa' the ghIjvIptaH vo' joH'a', je vo' the batlh vo' Daj majesty, ghorgh ghaH arises Daq shake the tera' mightily.",
        20: "Daq vetlh jaj, loDpu' DIchDaq chuH DoH chaj idols vo' baS chIS, je chaj idols vo' SuD baS, nuq ghaj taH chenmoHta' vaD themselves Daq lalDan toy', Daq the moles je Daq the bats;",
        21: "Daq jaH Daq the caverns vo' the rocks, je Daq the clefts vo' the ragged rocks, vo' qaSpa' the ghIjvIptaH vo' joH'a', je vo' the batlh vo' Daj majesty, ghorgh ghaH arises Daq shake the tera' mightily.",
        22: "Stop trusting Daq loD, 'Iv breath ghaH Daq Daj nostrils; vaD vo' nuq account ghaH ghaH?",
    },
    3: {
        1: "vaD, yIlegh, the joH, joH'a' vo' Armies, takes DoH vo' Jerusalem je vo' Judah supply je support, the Hoch supply vo' tIr Soj, je the Hoch supply vo' bIQ;",
        2: "the HoS loD, the loD vo' veS, the noH, the leghwI'pu', the diviner, the elder,",
        3: "the HoD vo' vaghmaH, the honorable loD, the counselor, the po' craftsman, je the clever enchanter.",
        4: "jIH DichDaq nob boys Daq taH chaj joHHom, je puqpu' DIchDaq rule Dung chaH.",
        5: "The ghotpu DichDaq taH Suvta', Hoch Sum another, je Hoch Sum Daj jIl. The puq DichDaq behave himself proudly Daq the qan loD, je the base Daq the honorable.",
        6: "Indeed a loD DIchDaq tlhap 'uch vo' Daj loDnI' Daq the tuq vo' Daj vav, ja'ta', “SoH ghaj Sut, SoH taH maj ruler, je chaw' vam ruin taH bIng lIj ghop.”",
        7: "Daq vetlh jaj ghaH DichDaq SaQ pa', ja'ta', jIH DichDaq ghobe' taH a healer; vaD Daq wIj tuq ghaH ghobe' tIr Soj ghobe' Sut. SoH DIchDaq ghobe' chenmoH jIH ruler vo' the ghotpu.",
        8: "vaD Jerusalem ghaH ruined, je Judah ghaH fallen; because chaj jat je chaj ta'mey 'oH Daq joH'a', Daq provoke the mInDu' vo' Daj batlh.",
        9: "The legh vo' chaj faces testify Daq chaH. chaH parade chaj yem rur Sodom. chaH yImev So' 'oH. Woe Daq chaj qa'! vaD chaH ghaj qempu' disaster upon themselves.",
        10: "ja' the QaQtaHghach “QaQ!” vaD chaH DIchDaq Sop the baQ vo' chaj deeds.",
        11: "Woe Daq the mIgh! Disaster ghaH upon chaH; vaD the deeds vo' Daj ghopmey DichDaq taH paid DoH Daq ghaH.",
        12: "As vaD wIj ghotpu, puqpu' 'oH chaj oppressors, je be'pu' rule Dung chaH. wIj ghotpu, chaH 'Iv Dev SoH cause SoH Daq err, je Qaw' the way vo' lIj Hemey.",
        13: "joH'a' stands Dung Daq contend, je stands Daq noH the ghotpu'.",
        14: "joH'a' DichDaq 'el Daq yoj tlhej the quppu' vo' Daj ghotpu, je chaj leaders: “'oH ghaH SoH 'Iv ghaj eaten Dung the HIq wIj. The non vo' the mIpHa' ghaH Daq lIj juHmey.",
        15: "nuq ta' SoH mean vetlh SoH crush wIj ghotpu, je grind the qab vo' the mIpHa'?” jatlhtaH the joH, joH'a' vo' Armies.",
        16: "Moreover joH'a' ja'ta', “Because the puqbe'pu' vo' Zion 'oH haughty, je yIt tlhej outstretched necks je flirting mInDu', walking Daq trip as chaH jaH, jingling ornaments Daq chaj qamDu';",
        17: "vaj the joH brings 'oy'mey Daq the crown vo' the nach vo' the be'pu' vo' Zion, je joH'a' DichDaq chenmoH chaj scalps jIb ghajbe'.”",
        18: "Daq vetlh jaj the joH DichDaq tlhap DoH the 'IhtaHghach vo' chaj anklets, the headbands, the crescent necklaces,",
        19: 'the earrings, the bracelets, the veils,',
        20: 'the headdresses, the ankle chains, the sashes, the perfume balmey, the charms,',
        21: 'the signet rings, the nose rings,',
        22: 'the fine robes, the capes, the cloaks, the purses,',
        23: 'the ghop mirrors, the fine linen garments, the tiaras, je the shawls.',
        24: "'oH DIchDaq qaS vetlh instead vo' sweet spices, pa' DIchDaq taH rottenness; instead vo' a belt, a rope; instead vo' QaQ cher jIb, jIb ghajbe'; instead vo' a robe, a girding vo' sackcloth; je branding instead vo' 'IhtaHghach.",
        25: "lIj loDpu' DIchDaq pum Sum the 'etlh, je lIj HoS Daq the veS.",
        26: "Daj lojmItmey DIchDaq lament je mourn; je ghaH DIchDaq taH moB je ba' Daq the yav.",
    },
    4: {
        1: "Soch be'pu' DIchDaq tlhap 'uch vo' wa' loD Daq vetlh jaj, ja'ta', “maH DichDaq Sop maj ghaj tIr Soj, je wear maj ghaj Sut: neH chaw' maH taH ja' Sum lIj pong. tlhap DoH maj reproach.”",
        2: "Daq vetlh jaj, joH'a' branch DichDaq taH 'IH je glorious, je the baQ vo' the puH DichDaq taH the 'IhtaHghach je batlh vo' the survivors vo' Israel.",
        3: "'oH DichDaq qaS, vetlh ghaH 'Iv ghaH poS Daq Zion, je ghaH 'Iv remains Daq Jerusalem, DIchDaq taH ja' le', 'ach Hoch 'Iv ghaH ghItlhta' among the yIntaH Daq Jerusalem;",
        4: "ghorgh the joH DIchDaq ghaj washed DoH the filth vo' the puqbe'pu' vo' Zion, je DIchDaq ghaj purged the 'Iw vo' Jerusalem vo' its midst, Sum the qa' vo' ruv, je Sum the qa' vo' burning.",
        5: "joH'a' DichDaq create Dung the Hoch juH vo' Mount Zion, je Dung Daj yejmey, a cloud je tlhIch Sum jaj, je the shining vo' a flaming qul Sum ram; vaD Dung Hoch the batlh DichDaq taH a canopy.",
        6: "pa' DichDaq taH a pavilion vaD a shade Daq the pem vo' the heat, je vaD a lulIgh je vaD a shelter vo' storm je vo' rain.",
    },
    5: {
        1: "chaw' jIH bom vaD wIj QaQ parmaqqay a bom vo' wIj parmaqqay about Daj HIq wIj. wIj parmaqqay ghajta' a HIq wIj Daq a very fruitful HuD.",
        2: "ghaH dug 'oH Dung, boSta' pa' its naghmey, planted 'oH tlhej the choicest vine, chenta' a tower Daq its midst, je je pe' pa' a winepress therein. ghaH nejta' vaD 'oH Daq yield grapes, 'ach 'oH yielded wild grapes.",
        3: "“DaH, nganpu' vo' Jerusalem je loDpu' vo' Judah, please noH joj jIH je wIj HIq wIj.",
        4: "nuq laH ghaj taH ta'pu' latlh Daq wIj HIq wIj, vetlh jIH ghaj ghobe' ta'pu' Daq 'oH? qatlh, ghorgh jIH nejta' vaD 'oH Daq yield grapes, ta'ta' 'oH yield wild grapes?",
        5: "DaH jIH DichDaq ja' SoH nuq jIH DichDaq ta' Daq wIj HIq wIj. jIH DichDaq tlhap DoH its hedge, je 'oH DichDaq taH eaten Dung. jIH DichDaq ghor bIng its reD vo' 'oH, je 'oH DichDaq taH trampled bIng.",
        6: "jIH DichDaq lay 'oH a wasteland. 'oH won't taH pruned ghobe' hoed, 'ach 'oH DichDaq grow briers je thorns. jIH DichDaq je ra'ta'ghach mu'mey the clouds vetlh chaH rain ghobe' rain Daq 'oH.”",
        7: "vaD the HIq wIj vo' joH'a' vo' Armies ghaH the tuq vo' Israel, je the loDpu' vo' Judah Daj bel plant: je ghaH nejta' vaD ruv, 'ach, yIlegh, oppression; vaD QaQtaHghach, 'ach, yIlegh, a SaQ vo' distress.",
        8: "Woe Daq chaH 'Iv join tuq Daq tuq, 'Iv lay yotlh Daq yotlh, until pa' ghaH ghobe' room, je SoH 'oH chenmoHta' Daq yIn mob Daq the midst vo' the puH!",
        9: "Daq wIj qoghDu', joH'a' vo' Armies jatlhtaH: “DIch law' juHmey DichDaq taH moB, 'ach Dun je 'IH, unoccupied.",
        10: "vaD wa'maH acres { Note: literally, wa'maH yokes, joq the amount vo' puH vetlh wa'maH yokes vo' chemvaH laH plow Daq wa' jaj, nuq ghaH about 10 acres joq 4 hectares. } vo' HIq wIj DIchDaq yield wa' bath, { Note: 1 bath ghaH about 22 litres joq 5.8 U. S. gallons } je a homer { Note: 1 homer ghaH about 220 litres joq 6 bushels } vo' tIr DIchDaq yield an ephah. { Note: 1 ephah ghaH about 22 litres joq 0.6 bushels joq about 2 pecks)— neH wa' tenth vo' nuq ghaHta' sown. }”",
        11: "Woe Daq chaH 'Iv Hu' Dung early Daq the po, vetlh chaH may tlha' HoS tlhutlh; 'Iv stay late Daq the ram, until HIq inflames chaH!",
        12: "The harp, lyre, tambourine, je flute, tlhej HIq, 'oH Daq chaj yupma'mey; 'ach chaH yImev respect the vum vo' joH'a', ghobe' ghaj chaH considered the operation vo' Daj ghopmey.",
        13: "vaj wIj ghotpu jaH Daq captivity vaD Hutlh vo' Sov. chaj honorable loDpu' 'oH famished, je chaj multitudes 'oH parched tlhej thirst.",
        14: "vaj Sheol { Note: Sheol ghaH the Daq vo' the Heghpu'. } ghajtaH enlarged its neH, je poSmaHpu' its nujDu' Hutlh juv; je chaj batlh, chaj qevmey, chaj pomp, je ghaH 'Iv rejoices among chaH, descend Daq 'oH.",
        15: "vaj loD ghaH qempu' low, mankind ghaH humbled, je the mInDu' vo' the arrogant ones 'oH humbled;",
        16: "'ach joH'a' vo' Armies ghaH exalted Daq ruv, je joH'a' the le' wa' ghaH sanctified Daq QaQtaHghach.",
        17: "vaj the 'erHommey DichDaq graze as Daq chaj tI yotlh, je novpu' DichDaq Sop the ruins vo' the rich.",
        18: "Woe Daq chaH 'Iv draw He'taHghach tlhej cords vo' falsehood, je mIghtaHghach as tlhej cart rope;",
        19: "'Iv jatlh, “chaw' ghaH chenmoH speed, chaw' ghaH hasten Daj vum, vetlh maH may legh 'oH; je chaw' the qeS vo' the le' wa' vo' Israel draw Sum je ghoS, vetlh maH may Sov 'oH!”",
        20: "Woe Daq chaH 'Iv ja' mIghtaHghach QaQ, je QaQ mIghtaHghach; 'Iv lan HurghtaHghach vaD wov, je wov vaD HurghtaHghach; 'Iv lan bitter vaD sweet, je sweet vaD bitter!",
        21: "Woe Daq chaH 'Iv 'oH val Daq chaj ghaj mInDu', je prudent Daq chaj ghaj leghpu'!",
        22: "Woe Daq chaH 'Iv 'oH HoS Daq tlhutlh HIq, je champions Daq mixing HoS tlhutlh;",
        23: "'Iv acquit the guilty vaD a bribe, 'ach deny ruv vaD the innocent!",
        24: "vaj as the jat vo' qul devours the stubble, je as the dry grass sinks bIng Daq the flame, vaj chaj root DIchDaq taH as rottenness, je chaj blossom DIchDaq jaH Dung as dust; because chaH ghaj rejected the chut vo' joH'a' vo' Armies, je muSqu' the mu' vo' the le' wa' vo' Israel.",
        25: "vaj joH'a' QeH burns Daq Daj ghotpu, je ghaH ghajtaH stretched pa' Daj ghop Daq chaH, je ghajtaH struck chaH. The Hudmey tremble, je chaj Heghpu' porghmey 'oH as Qo' Daq the midst vo' the streets. vaD Hoch vam, Daj QeH ghaH ghobe' tlhe'ta' DoH, 'ach Daj ghop ghaH vIHHa' stretched pa'.",
        26: "ghaH DichDaq lift Dung a banner Daq the tuqpu' vo' Hop, je ghaH DichDaq whistle vaD chaH vo' the pItlh vo' the tera'. yIlegh, chaH DichDaq ghoS speedily je swiftly.",
        27: "pagh DIchDaq taH Doy' ghobe' stumble among chaH; pagh DIchDaq slumber ghobe' Qong; ghobe' DIchDaq the belt vo' chaj waist taH untied, ghobe' the latchet vo' chaj shoes taH ghorta':",
        28: "'Iv arrows 'oH sharp, je Hoch chaj bows SIHta'bogh. chaj horses' hoofs DichDaq taH rur flint, je chaj wheels rur a whirlwind.",
        29: "chaj roaring DichDaq taH rur a lioness. chaH DichDaq roar rur Qup lions. HIja', chaH DIchDaq roar, je seize chaj prey je carry 'oH litHa', je pa' DichDaq taH ghobe' wa' Daq toD.",
        30: "chaH DichDaq roar Daq chaH Daq vetlh jaj rur the roaring vo' the biQ'a'. chugh wa' looks Daq the puH yIlegh, HurghtaHghach je distress. The wov ghaH darkened Daq its clouds.",
    },
    6: {
        1: "Daq the DIS vetlh joH Uzziah Heghta', jIH leghta' the joH sitting Daq a quS'a', jen je qengta' Dung; je Daj train tebta' the lalDan qach.",
        2: "Dung ghaH Qampu' the seraphim. Each wa' ghajta' jav telDu'. tlhej cha' ghaH covered Daj qab. tlhej cha' ghaH covered Daj qamDu'. tlhej cha' ghaH flew.",
        3: "wa' ja' Daq another, je ja'ta', “le', le', le', ghaH joH'a' vo' Armies! The Hoch tera' ghaH teblu'ta' vo' Daj batlh!”",
        4: "The foundations vo' the thresholds shook Daq the ghogh vo' ghaH 'Iv ja', je the tuq ghaHta' tebta' tlhej tlhIch.",
        5: "vaj jIH ja'ta', “Woe ghaH jIH! vaD jIH 'oH undone, because jIH 'oH a loD vo' Say'Ha' wuSDu', je jIH yIn Daq the midst vo' a ghotpu vo' Say'Ha' wuSDu': vaD wIj mInDu' ghaj leghpu' the joH, joH'a' vo' Armies!”",
        6: "vaj wa' vo' the seraphim flew Daq jIH, ghajtaH a yIn coal Daq Daj ghop, nuq ghaH ghajta' tlhappu' tlhej the tongs vo' litHa' the lalDanta' Daq.",
        7: "ghaH touched wIj nujDu' tlhej 'oH, je ja'ta', “yIlegh, vam ghajtaH touched lIj wuSDu'; je lIj He'taHghach ghaH tlhappu' DoH, je lIj yem forgiven.”",
        8: "jIH Qoyta' the joH ghogh, ja'ta', “'Iv DIchDaq jIH ngeH, je 'Iv DichDaq jaH vaD maH?” vaj jIH ja'ta', “naDev jIH 'oH. ngeH jIH!”",
        9: "ghaH ja'ta', “jaH, je ja' vam ghotpu, ‘SoH Qoy indeed, 'ach yImev understand; je SoH legh indeed, 'ach yImev perceive.'",
        10: "chenmoH the tIq vo' vam ghotpu ror. chenmoH chaj qoghDu' 'ugh, je shut chaj mInDu'; lest chaH legh tlhej chaj mInDu', je Qoy tlhej chaj qoghDu', je understand tlhej chaj tIq, je tlhe' again, je taH healed.”",
        11: "vaj jIH ja'ta', “joH, chay' tIq?” ghaH jangta', “Until vengmey 'oH waste Hutlh inhabitant, je juHmey Hutlh loD, je the puH becomes utterly waste,",
        12: "je joH'a' ghajtaH teqta' loDpu' Hop DoH, je the lonta' Daqmey 'oH law' Daq the midst vo' the puH.",
        13: "chugh pa' ghaH a tenth poS Daq 'oH, vetlh je DichDaq Daq tlhe' taH Soppu': as a terebinth, je as an Sor'a', 'Iv stock remains ghorgh chaH 'oH felled; vaj the le' tIr ghaH its stock.”",
    },
    7: {
        1: "'oH qaSta' Daq the jajmey vo' Ahaz the puqloD vo' Jotham, the puqloD vo' Uzziah, joH vo' Judah, vetlh Rezin the joH vo' Syria, je Pekah the puqloD vo' Remaliah, joH vo' Israel, mejta' Dung Daq Jerusalem Daq veS Daq 'oH, 'ach laH ghobe' prevail Daq 'oH.",
        2: "'oH ghaHta' ja'ta' the tuq vo' David, ja'ta', “Syria ghaH allied tlhej Ephraim.” Daj tIq trembled, je the tIq vo' Daj ghotpu, as the Sormey vo' the forest tremble tlhej the SuS.",
        3: "vaj joH'a' ja'ta' Daq Isaiah, “jaH pa' DaH Daq ghom Ahaz, SoH, je Shearjashub lIj puqloD, Daq the pItlh vo' the conduit vo' the upper pool, Daq the highway vo' the fuller's yotlh.",
        4: "ja' ghaH, ‘taH careful, je pol calm. yImev taH vIp, ghobe' chaw' lIj tIq taH puj because vo' Dochvammey cha' tails vo' tlhIch nob torches, vaD the fierce QeH vo' Rezin je Syria, je vo' the puqloD vo' Remaliah.",
        5: "Because Syria, Ephraim, je the puqloD vo' Remaliah, ghaj plotted mIghtaHghach Daq SoH, ja'ta',",
        6: "“Let's jaH Dung Daq Judah, je tear 'oH apart, je let's divide 'oH among ourselves, je cher Dung a joH Daq its midst, 'ach the puqloD vo' Tabeel.”",
        7: "vam ghaH nuq the joH joH'a' jatlhtaH: “'oH DIchDaq ghobe' Qam, ghobe' DIchDaq 'oH qaS.”",
        8: "vaD the nach vo' Syria ghaH Damascus, je the nach vo' Damascus ghaH Rezin; je within javmaH- vagh DISmey Ephraim DIchDaq taH ghorta' Daq pieces, vaj vetlh 'oH DIchDaq ghobe' taH a ghotpu;",
        9: "je the nach vo' Ephraim ghaH Samaria, je the nach vo' Samaria ghaH Remaliah's puqloD. chugh SoH DichDaq ghobe' Har, DIch SoH DIchDaq ghobe' taH established.'”",
        10: "joH'a' jatlhta' again Daq Ahaz, ja'ta',",
        11: "“tlhob a sign vo' joH'a' lIj joH'a'; tlhob 'oH either Daq the depth, joq Daq the height Dung.”",
        12: "'ach Ahaz ja'ta', “jIH DichDaq ghobe' tlhob, ghobe' DichDaq jIH tempt joH'a'.”",
        13: "ghaH ja'ta', “'Ij DaH, tuq vo' David: ghaH 'oH ghobe' yap vaD SoH Daq try the patience vo' loDpu', vetlh SoH DichDaq try the patience vo' wIj joH'a' je?",
        14: "vaj the joH himself DichDaq nob SoH a sign. yIlegh, the virgin DichDaq conceive, je SIQ a puqloD, je DIchDaq ja' Daj pong Immanuel. { Note: “Immanuel” means “joH'a' tlhej maH.” }",
        15: "ghaH DIchDaq Sop butter je honey ghorgh ghaH SovtaH Daq Qo' the mIghtaHghach, je choose the QaQ.",
        16: "vaD qaSpa' the puq SovtaH Daq Qo' the mIghtaHghach, je choose the QaQ, the puH 'Iv cha' joHpu' SoH abhor DIchDaq taH lonta'.",
        17: "joH'a' DichDaq qem Daq SoH, Daq lIj ghotpu, je Daq lIj vav tuq, jajmey vetlh ghaj ghobe' ghoS, vo' the jaj vetlh Ephraim departed vo' Judah; 'ach the joH vo' Assyria.",
        18: "'oH DichDaq qaS Daq vetlh jaj vetlh joH'a' DichDaq whistle vaD the puv vetlh ghaH Daq the uttermost part vo' the rivers vo' Egypt, je vaD the bee vetlh ghaH Daq the puH vo' Assyria.",
        19: "chaH DIchDaq ghoS, je DIchDaq Hoch leS Daq the moB valleys, Daq the clefts vo' the rocks, Daq Hoch thorn hedges, je Daq Hoch tI yotlh.",
        20: "Daq vetlh jaj the joH DichDaq shave tlhej a razor vetlh ghaH hired Daq the parts beyond the bIQtIQ, 'ach tlhej the joH vo' Assyria, the nach je the jIb vo' the qamDu'; je 'oH DIchDaq je consume the rol.",
        21: "'oH DIchDaq qaS Daq vetlh jaj vetlh a loD DIchDaq pol yIn a Qup cow, je cha' Suy';",
        22: "je 'oH DIchDaq qaS, vetlh because vo' the abundance vo' milk nuq chaH DIchDaq nob ghaH DIchDaq Sop butter: vaD Hoch DichDaq Sop butter je honey vetlh ghaH poS Daq the midst vo' the puH.",
        23: "'oH DichDaq qaS Daq vetlh jaj vetlh Hoch Daq nuqDaq pa' were a SaD vines Daq a SaD baS chIS shekels, DIchDaq taH vaD briers je thorns.",
        24: "ghotpu DichDaq jaH pa' tlhej arrows je tlhej bow, because Hoch the puH DichDaq taH briers je thorns.",
        25: "Hoch the hills vetlh were cultivated tlhej the hoe, SoH DIchDaq ghobe' ghoS pa' vaD taHvIp vo' briers je thorns; 'ach 'oH DIchDaq taH vaD the sending vo' vo' chemvaH, je vaD the treading vo' Suy'.”",
    },
    8: {
        1: "joH'a' ja'ta' Daq jIH, “tlhap a large tablet, je write Daq 'oH tlhej a man's pen, ‘vaD Maher Shalal Hash Baz; { Note: “Maher Shalal Hash Baz” means “quick Daq the plunder, swift Daq the non.” } '",
        2: "je jIH DichDaq tlhap vaD jIH'egh voqmoH witnesses Daq testify: Uriah the lalDan vumwI', je Zechariah the puqloD vo' Jeberechiah.”",
        3: "jIH mejta' Daq the prophetess, je ghaH conceived, je boghmoH a puqloD. vaj ja'ta' joH'a' Daq jIH, “ja' Daj pong ‘Maher Shalal Hash Baz.'",
        4: "vaD qaSpa' the puq SovtaH chay' Daq jatlh, ‘wIj vav,' je, ‘wIj SoS,' the riches vo' Damascus je the non vo' Samaria DichDaq taH qengta' DoH Sum the joH vo' Assyria.”",
        5: "joH'a' jatlhta' Daq jIH yet again, ja'ta',",
        6: "“Because vam ghotpu ghaj refused the bIQmey vo' Shiloah vetlh jaH softly, je yItIv Daq Rezin je Remaliah's puqloD;",
        7: "DaH vaj, yIlegh, the joH brings upon chaH the HoS flood bIQmey vo' the bIQtIQ: the joH vo' Assyria je Hoch Daj batlh. 'oH DichDaq ghoS Dung Dung Hoch its channels, je jaH Dung Hoch its banks.",
        8: "'oH DichDaq sweep onward Daq Judah. 'oH DichDaq overflow je juS vegh; 'oH DichDaq reach 'ach Daq the neck; je the stretching pa' vo' its telDu' DichDaq fill the breadth vo' lIj puH, Immanuel.",
        9: "chenmoH an uproar, SoH ghotpu', je taH ghorta' Daq pieces! 'Ij, Hoch SoH vo' Hop countries: dress vaD may', je taH shattered! Dress vaD may', je taH shattered!",
        10: "tlhap qeS tay', je 'oH DichDaq taH qempu' Daq pagh; jatlh the mu', je 'oH DichDaq ghobe' Qam: vaD joH'a' ghaH tlhej maH.”",
        11: "vaD joH'a' jatlhta' thus Daq jIH tlhej a HoS ghop, je instructed jIH ghobe' Daq yIt Daq the way vo' vam ghotpu, ja'ta',",
        12: "“yImev jatlh, ‘A conspiracy!' concerning Hoch about nuq vam ghotpu jatlh, ‘A conspiracy!' ghobe' taHvIp chaj threats, ghobe' taH terrorized.",
        13: "joH'a' vo' Armies ghaH 'Iv SoH must respect as le'. ghaH ghaH the wa' SoH must taHvIp. ghaH ghaH the wa' SoH must dread.",
        14: "ghaH DichDaq taH a Daq QaD, 'ach vaD both juHmey vo' Israel, ghaH DichDaq taH a trap je a tojta'ghach vaD the nganpu' vo' Jerusalem.",
        15: "law' DichDaq stumble Dung 'oH, pum, taH ghorta', taH snared, je taH captured.”",
        16: "Wrap Dung the testimony. Seal the chut among wIj ghojwI'pu'.",
        17: "jIH DichDaq loS vaD joH'a', 'Iv hides Daj qab vo' the tuq vo' Jacob, je jIH DichDaq legh vaD ghaH.",
        18: "yIlegh, jIH je the puqpu' 'Iv joH'a' ghajtaH nobpu' jIH 'oH vaD signs je vaD wonders Daq Israel vo' joH'a' vo' Armies, 'Iv yIntaH Daq Mount Zion.",
        19: "ghorgh chaH ja' SoH, “Consult tlhej chaH 'Iv ghaj familiar spirits je tlhej the wizards, 'Iv chirp je 'Iv mutter:” shouldn't a ghotpu consult tlhej chaj joH'a'? Should chaH consult the Heghpu' Daq behalf vo' the yIntaH?",
        20: "tlhe' Daq the chut je Daq the testimony! chugh chaH yImev jatlh according Daq vam mu', DIch pa' ghaH ghobe' po vaD chaH.",
        21: "chaH DichDaq juS vegh 'oH, 'oy' distressed je hungry; je 'oH DichDaq qaS vetlh ghorgh chaH 'oH hungry, chaH DichDaq worry, je mu'qaD Sum chaj joH je Sum chaj joH'a'. chaH DichDaq tlhe' chaj faces upward,",
        22: "je legh Daq the tera', je legh distress, HurghtaHghach, je the gloom vo' anguish. chaH DichDaq taH driven Daq thick HurghtaHghach.",
    },
    9: {
        1: "'ach pa' DIchDaq taH ghobe' latlh gloom vaD Daj 'Iv ghaHta' Daq anguish. Daq the former poH, ghaH qempu' Daq contempt the puH vo' Zebulun je the puH vo' Naphtali; 'ach Daq the latter poH ghaH ghajtaH chenmoHta' 'oH glorious, Sum the way vo' the biQ'a', beyond the Jordan, Galilee vo' the tuqpu'.",
        2: "The ghotpu 'Iv yItta' Daq HurghtaHghach ghaj leghpu' a Dun wov. chaH 'Iv yInta' Daq the puH vo' the QIb vo' Hegh, Daq chaH the wov ghajtaH shined.",
        3: "SoH ghaj multiplied the Hatlh. SoH ghaj increased chaj Quch. chaH yItIv qaSpa' SoH according Daq the Quch Daq harvest, as loDpu' yItIv ghorgh chaH divide the non.",
        4: "vaD the yoke vo' Daj burden, je the naQ vo' Daj shoulder, the DevwI' naQ vo' Daj oppressor, SoH ghaj ghorta' as Daq the jaj vo' Midian.",
        5: "vaD Hoch the armor vo' the armed loD Daq the noisy may', je the garments rolled Daq 'Iw, DichDaq taH vaD burning, fuel vaD the qul.",
        6: "vaD Daq maH a puq ghaH bogh. Daq maH a puqloD ghaH nobpu'; je the government DichDaq taH Daq Daj shoulders. Daj pong DichDaq taH ja' Wonderful, Counselor, HoS joH'a', Everlasting vav, joHHom vo' roj.",
        7: "vo' the increase vo' Daj government je vo' roj pa' DIchDaq taH ghobe' pItlh, Daq the quS'a' vo' David, je Daq Daj kingdom, Daq establish 'oH, je Daq uphold 'oH tlhej ruv je tlhej QaQtaHghach vo' vetlh poH Daq, 'ach reH. The zeal vo' joH'a' vo' Armies DichDaq perform vam.",
        8: "The joH ngeHta' a mu' Daq Jacob, je 'oH falls Daq Israel.",
        9: "Hoch the ghotpu DichDaq Sov, including Ephraim je the nganpu' vo' Samaria, 'Iv jatlh Daq pride je Daq arrogance vo' tIq,",
        10: "“The bricks ghaj fallen, 'ach maH DichDaq chen tlhej pe' nagh. The sycamore fig Sormey ghaj taH pe' bIng, 'ach maH DichDaq lan cedars Daq chaj Daq.”",
        11: "vaj joH'a' DichDaq cher Dung Daq jen Daq ghaH the jaghpu' vo' Rezin, je DichDaq stir Dung Daj jaghpu',",
        12: "The Syrians Daq front, je the Philistines behind; je chaH DichDaq Sop Israel tlhej poSmoH nujDu'. vaD Hoch vam, Daj QeH ghaH ghobe' tlhe'ta' DoH, 'ach Daj ghop ghaH stretched pa' vIHHa'.",
        13: "Yet the ghotpu ghaj ghobe' tlhe'ta' Daq ghaH 'Iv struck chaH, ghobe' ghaj chaH nejta' joH'a' vo' Armies.",
        14: "vaj joH'a' DichDaq pe' litHa' vo' Israel nach je tail, palm branch je reed, Daq wa' jaj.",
        15: "The elder je the honorable loD ghaH the nach, je the leghwI'pu' 'Iv teaches lies ghaH the tail.",
        16: "vaD chaH 'Iv Dev vam ghotpu Dev chaH astray; je chaH 'Iv 'oH led Sum chaH 'oH Qaw'ta'.",
        17: "vaj the joH DichDaq ghobe' yItIv Dung chaj Qup loDpu', ghobe' DichDaq ghaH ghaj compassion Daq chaj vav ghajbe' je widows; vaD Hoch ghaH profane je an evildoer, je Hoch nujDu' speaks folly. vaD Hoch vam Daj QeH ghaH ghobe' tlhe'ta' DoH, 'ach Daj ghop ghaH stretched pa' vIHHa'.",
        18: "vaD mIghtaHghach burns rur a qul. 'oH devours the briers je thorns; HIja', 'oH kindles Daq the thickets vo' the forest, je chaH roll upward Daq a column vo' tlhIch.",
        19: "vegh the QeHpu' vo' joH'a' vo' Armies, the puH ghaH meQqu'pu' Dung; je the ghotpu 'oH the fuel vaD the qul. ghobe' wa' spares Daj loDnI'.",
        20: "wa' DichDaq Sop Daq the nIH ghop, je taH hungry; je ghaH DichDaq Sop Daq the poS ghop, je chaH DichDaq ghobe' taH satisfied. Hoch DichDaq Sop the ghab vo' Daj ghaj arm:",
        21: "Manasseh, Ephraim; je Ephraim, Manasseh; je chaH tay' DIchDaq taH Daq Judah. vaD Hoch vam Daj QeH ghaH ghobe' tlhe'ta' DoH, 'ach Daj ghop ghaH stretched pa' vIHHa'.",
    },
    10: {
        1: "Woe Daq chaH 'Iv decree unrighteous decrees, je Daq the writers 'Iv write oppressive decrees;",
        2: "Daq deprive the needy vo' ruv, je Daq rob the mIpHa' among wIj ghotpu vo' chaj rights, vetlh widows may taH chaj non, je vetlh chaH may chenmoH the vav ghajbe' chaj prey!",
        3: "nuq DichDaq SoH ta' Daq the jaj vo' visitation, je Daq the desolation nuq DichDaq ghoS vo' afar? Daq 'Iv DichDaq SoH Haw' vaD QaH? nuqDaq DichDaq SoH mej lIj wealth?",
        4: "chaH DichDaq neH bow bIng bIng the prisoners, je DichDaq pum bIng the Heghta'. vaD Hoch vam Daj QeH ghaH ghobe' tlhe'ta' DoH, 'ach Daj ghop ghaH stretched pa' vIHHa'.",
        5: "Alas Assyrian, the DevwI' naQ vo' wIj QeH, the naQ Daq 'Iv ghop ghaH wIj indignation!",
        6: "jIH DichDaq ngeH ghaH Daq a profane Hatlh, je Daq the ghotpu 'Iv QeH jIH DichDaq jIH nob ghaH a ra'ta'ghach mu'mey Daq tlhap the non je Daq tlhap the prey, je Daq yIt chaH bIng rur the mire vo' the streets.",
        7: "However ghaH ta'be' mean vaj, ghobe' ta'taH Daj tIq think vaj; 'ach 'oH ghaH Daq Daj tIq Daq Qaw', je Daq pe' litHa' ghobe' a few tuqpu'.",
        8: "vaD ghaH jatlhtaH, “Aren't Hoch vo' wIj joHHom joHpu'?",
        9: "'oHbe' Calno rur Carchemish? 'oHbe' Hamath rur Arpad? 'oHbe' Samaria rur Damascus?”",
        10: "As wIj ghop ghajtaH tu'ta' the kingdoms vo' the idols, 'Iv engraved images exceeded chaH vo' Jerusalem je vo' Samaria;",
        11: "DIchDaq jIH ghobe', as jIH ghaj ta'pu' Daq Samaria je Daj idols, vaj ta' Daq Jerusalem je Daj idols?",
        12: "vaj 'oH DichDaq qaS vetlh, ghorgh the joH ghajtaH performed Daj Hoch vum Daq Mount Zion je Daq Jerusalem, jIH DichDaq punish the baQ vo' the willful proud tIq vo' the joH vo' Assyria, je the insolence vo' Daj haughty looks.",
        13: "vaD ghaH ghajtaH ja'ta', “Sum the HoS vo' wIj ghop jIH ghaj ta'pu' 'oH, je Sum wIj valtaHghach; vaD jIH ghaj yajtaHghach: je jIH ghaj teqta' the veHmey vo' the ghotpu', je ghaj robbed chaj treasures. rur a valiant loD jIH ghaj qempu' bIng chaj DevwIpu'.",
        14: "wIj ghop ghajtaH tu'ta' the riches vo' the ghotpu' rur a nest, je rur wa' gathers eggs vetlh 'oH abandoned, ghaj jIH boSta' Hoch the tera'. pa' ghaHta' ghobe' wa' 'Iv vIHta' chaj wing, joq vetlh poSmaHpu' chaj nujDu', joq chirped.”",
        15: "Should an axe brag Daq ghaH 'Iv chops tlhej 'oH? Should a leghta' exalt itself Dung ghaH 'Iv saws tlhej 'oH? As chugh a DevwI' naQ should lift chaH 'Iv lift 'oH Dung, joq as chugh a naQ should lift Dung someone 'Iv ghaH ghobe' wood.",
        16: "vaj the joH, joH'a' vo' Armies, DichDaq ngeH among Daj ror ones leanness; je bIng Daj batlh a burning DichDaq taH kindled rur the burning vo' qul.",
        17: "The wov vo' Israel DichDaq taH vaD a qul, je Daj le' wa' vaD a flame; je 'oH DichDaq meQ je Sop Daj thorns je Daj briers Daq wa' jaj.",
        18: "ghaH DichDaq consume the batlh vo' Daj forest, je vo' Daj fruitful yotlh, both qa' je porgh. 'oH DichDaq taH as ghorgh a standard qengwI' faints.",
        19: "The chuv vo' the Sormey vo' Daj forest DIchDaq taH few, vaj vetlh a puq laH write chaj mI'.",
        20: "'oH DichDaq ghoS Daq juS Daq vetlh jaj vetlh the chuv vo' Israel, je chaH 'Iv ghaj escaped vo' the tuq vo' Jacob DichDaq ghobe' latlh again lean Daq ghaH 'Iv struck chaH, 'ach DIchDaq lean Daq joH'a', the le' wa' vo' Israel, Daq vIt.",
        21: "A chuv DichDaq chegh, 'ach the chuv vo' Jacob, Daq the HoS joH'a'.",
        22: "vaD 'a' lIj ghotpu, Israel, 'oH rur the sand vo' the biQ'a', neH a chuv vo' chaH DichDaq chegh. A QIH ghaH determined, overflowing tlhej QaQtaHghach.",
        23: "vaD the joH, joH'a' vo' Armies, DichDaq chenmoH a teblu'ta' pItlh, je vetlh determined, Daq the midst vo' Hoch the tera'.",
        24: "vaj the joH, joH'a' vo' Armies, jatlhtaH “wIj ghotpu 'Iv yIn Daq Zion, yImev taH vIp vo' the Assyrian, 'a' ghaH mup SoH tlhej the DevwI' naQ, je lift Dung Daj naQ Daq SoH, as Egypt ta'ta'.",
        25: 'vaD yet a very mach qaStaHvIS, je the indignation Daq SoH DichDaq taH accomplished, je wIj QeH DichDaq taH directed Daq Daj QIH.”',
        26: "joH'a' vo' Armies DichDaq stir Dung a scourge Daq ghaH, as Daq the HoHqu' vo' Midian Daq the nagh vo' Oreb. Daj DevwI' naQ DichDaq taH Dung the biQ'a', je ghaH DichDaq lift 'oH Dung rur ghaH ta'ta' Daq Egypt.",
        27: "'oH DichDaq qaS Daq vetlh jaj, vetlh Daj burden DichDaq mej vo' litHa' lIj shoulder, je Daj yoke vo' litHa' lIj neck, je the yoke DIchDaq taH Qaw'ta' because vo' the anointing Hergh.",
        28: "ghaH ghajtaH ghoS Daq Aiath. ghaH ghajtaH juSta' vegh Migron. Daq Michmash ghaH stores Daj tep.",
        29: "chaH ghaj ghoSta' Dung the juS. chaH ghaj tlhappu' Dung chaj lodging Daq Geba. Ramah trembles. Gibeah vo' Saul ghajtaH Haw'ta'.",
        30: "SaQ QoymoHlaHbogh tlhej lIj ghogh, puqbe' vo' Gallim! 'Ij, Laishah! SoH mIpHa' Anathoth!",
        31: "Madmenah ghaH a fugitive. The nganpu' vo' Gebim Haw' vaD safety.",
        32: "vam very jaj ghaH DichDaq halt Daq Nob. ghaH shakes Daj ghop Daq the HuD vo' the puqbe' vo' Zion, the HuD vo' Jerusalem.",
        33: "yIlegh, the joH, joH'a' vo' Armies, DichDaq lop the boughs tlhej ghIjvIptaH. The tall DichDaq taH pe' bIng, je the lofty DichDaq taH qempu' low.",
        34: "ghaH DichDaq pe' bIng the thickets vo' the forest tlhej iron, je Lebanon DichDaq pum Sum the HoS wa'.",
    },
    11: {
        1: "A shoot DichDaq ghoS pa' vo' the stock vo' Jesse, je a branch pa' vo' Daj roots DichDaq SIQ baQ.",
        2: "The qa' vo' joH'a' DichDaq leS Daq ghaH: the qa' vo' valtaHghach je yajtaHghach, the qa' vo' qeS je might, the qa' vo' Sov je vo' the taHvIp vo' joH'a'.",
        3: "Daj tIv DichDaq taH Daq the taHvIp vo' joH'a'. ghaH DichDaq ghobe' noH Sum the leghpu' vo' Daj mInDu', ghobe' decide Sum the hearing vo' Daj qoghDu';",
        4: "'ach tlhej QaQtaHghach ghaH DichDaq noH the mIpHa', je decide tlhej equity vaD the humble vo' the tera'. ghaH DichDaq mup the tera' tlhej the DevwI' naQ vo' Daj nujDu'; je tlhej the breath vo' Daj wuSDu' ghaH DichDaq HoH the mIgh.",
        5: "QaQtaHghach DichDaq taH the belt vo' Daj waist, je voqtaHghach the belt vo' Daj waist.",
        6: "The wolf DichDaq yIn tlhej the lamb, je the leopard DichDaq Qot bIng tlhej the Qup goat; The calf, the Qup HaDI'baH, je the fattened calf tay'; je a mach puq DichDaq Dev chaH.",
        7: "The cow je the SIQ DichDaq graze. chaj Qup ones DichDaq Qot bIng tay'. The HaDI'baH DichDaq Sop straw rur the Qa'.",
        8: "The nursing puq DichDaq play Sum a cobra's hole, je the weaned puq DichDaq lan Daj ghop Daq the viper's den.",
        9: "chaH DichDaq ghobe' hurt ghobe' Qaw' Daq Hoch wIj le' HuD; vaD the tera' DichDaq taH teblu'ta' vo' the Sov vo' joH'a', as the bIQmey So' the biQ'a'.",
        10: "'oH DichDaq qaS Daq vetlh jaj vetlh the tuqpu' DichDaq nej the root vo' Jesse, 'Iv stands as a banner vo' the ghotpu'; je Daj resting Daq DichDaq taH glorious.",
        11: "'oH DichDaq qaS Daq vetlh jaj vetlh the joH DichDaq cher Daj ghop again the cha'DIch poH Daq recover the chuv vetlh ghaH poS vo' Daj ghotpu vo' Assyria, vo' Egypt, vo' Pathros, vo' Cush, vo' Elam, vo' Shinar, vo' Hamath, je vo' the islands vo' the biQ'a'.",
        12: "ghaH DichDaq cher Dung a banner vaD the tuqpu', je DichDaq assemble the outcasts vo' Israel, je tay'moH tay' the dispersed vo' Judah vo' the loS corners vo' the tera'.",
        13: "The envy je vo' Ephraim DichDaq mej, je chaH 'Iv persecute Judah DichDaq taH pe' litHa'. Ephraim won't envy Judah, je Judah won't persecute Ephraim.",
        14: "chaH DichDaq puv bIng Daq the shoulders vo' the Philistines Daq the pemHov 'et. tay' chaH DichDaq plunder the puqpu' vo' the pemHov 'o'. chaH DichDaq extend chaj HoS Dung Edom je Moab, je the puqpu' vo' Ammon DichDaq obey chaH.",
        15: "joH'a' DichDaq utterly Qaw' the jat vo' the Egyptian biQ'a'; je tlhej Daj scorching SuS ghaH DichDaq wave Daj ghop Dung the bIQtIQ, je DichDaq split 'oH Daq Soch streams, je cause loDpu' Daq march Dung Daq sandals.",
        16: "pa' DichDaq taH a highway vaD the chuv vetlh ghaH poS vo' Daj ghotpu vo' Assyria, rur pa' ghaHta' vaD Israel Daq the jaj vetlh ghaH ghoSta' Dung pa' vo' the puH vo' Egypt.",
    },
    12: {
        1: "Daq vetlh jaj SoH DichDaq jatlh, “jIH DichDaq nob tlho' Daq SoH, joH'a'; vaD 'a' SoH were angry tlhej jIH, lIj QeH ghajtaH tlhe'ta' DoH je SoH belmoH jIH.",
        2: "yIlegh, joH'a' ghaH wIj toDtaHghach. jIH DichDaq voq, je DichDaq ghobe' taH vIp; vaD joH'a', joH'a', ghaH wIj HoS je bom; je ghaH ghajtaH moj wIj toDtaHghach.”",
        3: "vaj tlhej Quch SoH DichDaq draw bIQ pa' vo' the wells vo' toDtaHghach.",
        4: "Daq vetlh jaj SoH DichDaq jatlh, “nob tlho' Daq joH'a'! ja' Daq Daj pong. Declare Daj ta'mey among the ghotpu'. Proclaim vetlh Daj pong ghaH exalted!",
        5: "bom Daq joH'a', vaD ghaH ghajtaH ta'pu' excellent Dochmey! chaw' vam taH Sovta' Daq Hoch the tera'!",
        6: "SaQ QoymoHlaHbogh je jach, SoH inhabitant vo' Zion; vaD the le' wa' vo' Israel ghaH Dun Daq the midst vo' SoH!”",
    },
    13: {
        1: "The burden vo' Babylon, nuq Isaiah the puqloD vo' Amoz leghta':",
        2: "cher Dung a banner Daq the bare HuD! Lift Dung lIj ghogh Daq chaH! Wave lIj ghop, vetlh chaH may jaH Daq the lojmItmey vo' the nobles.",
        3: "jIH ghaj ra'ta' wIj consecrated ones; HIja', jIH ghaj ja' wIj HoS loDpu' vaD wIj QeH, 'ach wIj proudly exulting ones.",
        4: "The noise vo' a qevmey ghaH Daq the Hudmey, as vo' a Dun ghotpu; the noise vo' an uproar vo' the kingdoms vo' the tuqpu' boSta' tay'! joH'a' vo' Armies ghaH mustering the army vaD the may'.",
        5: "chaH ghoS vo' a Hop Hatlh, vo' the uttermost part vo' chal, 'ach joH'a', je the weapons vo' Daj indignation, Daq Qaw' the Hoch puH.",
        6: "Wail; vaD the jaj vo' joH'a' ghaH Daq ghop! 'oH DichDaq ghoS as QIH vo' the HoSghaj.",
        7: "vaj Hoch ghopmey DichDaq taH feeble, je everyone's tIq DichDaq melt.",
        8: "chaH DichDaq taH dismayed. Pangs je QoSqu'ghachmey DichDaq seize chaH. chaH DichDaq taH Daq pain rur a be' Daq labor. chaH DichDaq legh Daq amazement wa' Daq another. chaj faces DichDaq taH faces vo' flame.",
        9: "yIlegh, the jaj vo' joH'a' choltaH, cruel, tlhej QeHpu' je fierce QeH; Daq chenmoH the puH a desolation, je Daq Qaw' its yemwI'pu' pa' vo' 'oH.",
        10: "vaD the stars vo' the sky je its constellations DichDaq ghobe' nob chaj wov. The pemHov DichDaq taH darkened Daq its ghoS vo', je the maS DichDaq ghobe' cause its wov Daq shine.",
        11: "jIH DichDaq punish the qo' vaD chaj mIghtaHghach, je the mIgh vaD chaj He'taHghach. jIH DichDaq cause the arrogance vo' the proud Daq mev, je DichDaq humble the haughtiness vo' the terrible.",
        12: "jIH DichDaq chenmoH ghotpu latlh rare than fine SuD baS, 'ach a person than the pure SuD baS vo' Ophir.",
        13: "vaj jIH DichDaq chenmoH the chal tremble, je the tera' DichDaq taH shaken pa' vo' its Daq Daq the QeHpu' vo' joH'a' vo' Armies, je Daq the jaj vo' Daj fierce QeH.",
        14: "'oH DichDaq qaS vetlh rur a hunted gazelle, je rur Suy' vetlh ghobe' wa' gathers, chaH DichDaq each tlhe' Daq chaj ghaj ghotpu, je DichDaq each Haw' Daq chaj ghaj puH.",
        15: "Hoch 'Iv ghaH tu'ta' DichDaq taH thrust vegh. Hoch 'Iv ghaH captured DichDaq pum Sum the 'etlh.",
        16: "chaj infants je DichDaq taH dashed Daq pieces qaSpa' chaj mInDu'. chaj juHmey DichDaq taH ransacked, je chaj be'nalpu' raped.",
        17: "yIlegh, jIH DichDaq stir Dung the Medes Daq chaH, 'Iv DichDaq ghobe' value baS chIS, je as vaD SuD baS, chaH DichDaq ghobe' tIv Daq 'oH.",
        18: "chaj bows DichDaq woD the Qup loDpu' Daq pieces; je chaH DIchDaq ghaj ghobe' pity Daq the baQ vo' the womb. chaj mInDu' DichDaq ghobe' spare puqpu'.",
        19: "Babylon, the batlh vo' kingdoms, the 'IhtaHghach vo' the Chaldeans' pride, DichDaq taH rur ghorgh joH'a' overthrew Sodom je Gomorrah.",
        20: "'oH DichDaq never taH inhabited, ghobe' DichDaq 'oH taH yInta' Daq vo' generation Daq generation. The Arabian DichDaq ghobe' pitch a juHHom pa', ghobe' DichDaq shepherds chenmoH chaj flocks Qot bIng pa'.",
        21: "'ach wild Ha'DIbaH vo' the desert DichDaq Qot pa', je chaj juHmey DichDaq taH teblu'ta' vo' jackals. Ostriches DichDaq yIn pa', je wild goats DichDaq frolic pa'.",
        22: "Wolves DichDaq SaQ Daq chaj castles, je jackals Daq the bel palaces. Daj poH ghaH Sum Daq ghoS, je Daj jajmey DichDaq ghobe' taH prolonged.",
    },
    14: {
        1: "vaD joH'a' DichDaq ghaj compassion Daq Jacob, je DichDaq yet choose Israel, je cher chaH Daq chaj ghaj puH. The foreigner DichDaq join himself tlhej chaH, je chaH DichDaq unite tlhej the tuq vo' Jacob.",
        2: "The ghotpu' DichDaq tlhap chaH, je qem chaH Daq chaj Daq. The tuq vo' Israel DichDaq ghaj chaH Daq joH'a' puH vaD toy'wI'pu' je vaD handmaids. chaH DichDaq tlhap as captives chaH 'Iv captives chaH were; je chaH DIchDaq rule Dung chaj oppressors.",
        3: "'oH DichDaq qaS Daq the jaj vetlh joH'a' DichDaq nob SoH leS vo' lIj QoSqu', vo' lIj Seng, je vo' the hard toy'taHghach Daq nuq SoH were chenmoHta' Daq toy',",
        4: "vetlh SoH DichDaq tlhap Dung vam parable Daq the joH vo' Babylon, je jatlh, “chay' the oppressor ghajtaH mevta'! The golden veng ghajtaH mevta'!”",
        5: "joH'a' ghajtaH ghorta' the naQ vo' the mIgh, the scepter vo' the DevwIpu',",
        6: "'Iv struck the ghotpu' Daq QeHpu' tlhej a continual stroke, 'Iv ruled the tuqpu' Daq QeH, tlhej a persecution vetlh pagh restrained.",
        7: "The Hoch tera' ghaH Daq leS, je ghaH quiet. chaH ghor pa' bom.",
        8: "HIja', the fir Sormey yItIv tlhej SoH, tlhej the cedars vo' Lebanon, ja'ta', “Since SoH 'oH humbled, ghobe' lumberjack ghajtaH ghoS Dung Daq maH.”",
        9: "Sheol { Note: Sheol ghaH the Daq vo' the Heghpu'. } vo' bIng ghajtaH vIHta' vaD SoH Daq ghom SoH Daq lIj choltaH. 'oH stirs Dung the Heghpu' vaD SoH, 'ach Hoch the DevwIpu' vo' the tera'. 'oH ghajtaH raised Dung vo' chaj thrones Hoch the joHpu' vo' the tuqpu'.",
        10: "chaH Hoch DichDaq jang je tlhob SoH, “ghaj SoH je moj as weak as maH 'oH? ghaj SoH moj rur maH?”",
        11: "lIj pomp ghaH qempu' bIng Daq Sheol { Note: Sheol ghaH the Daq vo' the Heghpu'. }, tlhej the wab vo' lIj stringed instruments. Maggots 'oH ngeH pa' bIng SoH, je worms So' SoH.",
        12: "chay' SoH ghaj fallen vo' chal, po Hov, puqloD vo' the dawn! chay' SoH 'oH pe' bIng Daq the yav, 'Iv laid the tuqpu' low!",
        13: "SoH ja'ta' Daq lIj tIq, “jIH DichDaq ascend Daq chal! jIH DichDaq exalt wIj quS'a' Dung the stars vo' joH'a'! jIH DichDaq ba' Daq the HuD vo' yej, Daq the Hop pemHov nIH!",
        14: "jIH DichDaq ascend Dung the heights vo' the clouds! jIH DichDaq chenmoH jIH'egh rur the HochHom jen!”",
        15: "Yet SoH DIchDaq taH qempu' bIng Daq Sheol { Note: Sheol ghaH the Daq vo' the Heghpu'. }, Daq the depths vo' the pit.",
        16: "chaH 'Iv legh SoH DichDaq stare Daq SoH. chaH DichDaq ponder SoH, ja'ta', “ghaH vam the loD 'Iv chenmoHta' the tera' Daq tremble, 'Iv shook kingdoms;",
        17: "'Iv chenmoHta' the qo' rur a ngem, je overthrew its vengmey; 'Iv ta'be' release Daj prisoners Daq chaj home?”",
        18: "Hoch the joHpu' vo' the tuqpu', Qong Daq batlh, Hoch Daq Daj ghaj tuq.",
        19: "'ach SoH 'oH chuH DoH vo' lIj tomb rur an abominable branch, clothed tlhej the Heghta', 'Iv 'oH thrust vegh tlhej the 'etlh, 'Iv jaH bIng Daq the naghmey vo' the pit; rur a Heghpu' porgh trodden bIng qam.",
        20: "SoH DichDaq ghobe' join chaH Daq burial, because SoH ghaj Qaw'ta' lIj puH. SoH ghaj HoHta' lIj ghotpu. The tIr vo' evildoers DichDaq ghobe' taH named reH.",
        21: "ghuH vaD HoHqu' vo' Daj puqpu' because vo' the He'taHghach vo' chaj vavpu', vetlh chaH ghobe' Hu' Dung je ghaj the tera', je fill the surface vo' the qo' tlhej vengmey.",
        22: "“jIH DichDaq Hu' Dung Daq chaH,” jatlhtaH joH'a' vo' Armies, “je pe' litHa' vo' Babylon pong je chuv, je puqloD je puqloD's son,” jatlhtaH joH'a'.",
        23: "“jIH DichDaq je chenmoH 'oH a possession vaD the porcupine, je pools vo' bIQ. jIH DichDaq sweep 'oH tlhej the broom vo' QIH,” jatlhtaH joH'a' vo' Armies.",
        24: "joH'a' vo' Armies ghajtaH sworn, ja'ta', “DIch, as jIH ghaj thought, vaj DIchDaq 'oH qaS; je as jIH ghaj purposed, vaj DIchDaq 'oH Qam:",
        25: 'vetlh jIH DichDaq ghor the Assyrian Daq wIj puH, je yIt ghaH bIng qam Daq wIj Hudmey. vaj Daj yoke DichDaq mej chaH, je Daj burden mej chaj shoulders.',
        26: "vam ghaH the plan vetlh ghaH determined vaD the Hoch tera'. vam ghaH the ghop vetlh ghaH stretched pa' Dung Hoch the tuqpu'.",
        27: "vaD joH'a' vo' Armies ghajtaH planned, je 'Iv laH stop 'oH? Daj ghop ghaH stretched pa', je 'Iv laH tlhe' 'oH DoH?”",
        28: "vam burden ghaHta' Daq the DIS vetlh joH Ahaz Heghta'.",
        29: "yImev yItIv, toH Philistia, Hoch vo' SoH, because the DevwI' naQ vetlh struck SoH ghaH ghorta'; vaD pa' vo' the serpent's root an tar ghajbogh lung DichDaq emerge, je Daj baQ DichDaq taH a fiery flying lung.",
        30: "The firstborn vo' the mIpHa' DichDaq Sop, je the needy DichDaq Qot bIng Daq safety; je jIH DichDaq HoH lIj root tlhej famine, je lIj chuv DichDaq taH HoHta'.",
        31: "Howl, lojmIt! SaQ, veng! SoH 'oH melted DoH, Philistia, Hoch vo' SoH; vaD tlhIch choltaH pa' vo' the pemHov nIH, je pa' ghaH ghobe' straggler Daq Daj ranks.",
        32: "nuq DichDaq chaH jang the Duypu' vo' the Hatlh? vetlh joH'a' ghajtaH founded Zion, je Daq Daj the afflicted vo' Daj ghotpu DichDaq tlhap lulIgh.",
    },
    15: {
        1: "The burden vo' Moab: vaD Daq a ram, Ar vo' Moab ghaH laid waste, je qempu' Daq pagh; vaD Daq a ram Kir vo' Moab ghaH laid waste, je qempu' Daq pagh.",
        2: "chaH ghaj ghoSta' Dung Daq Bayith, je Daq Dibon, Daq the jen Daqmey, Daq weep. Moab wails Dung Nebo je Dung Medeba. jIb ghajbe' ghaH Daq Hoch vo' chaj nachDu'. Hoch rol ghaH pe' litHa'.",
        3: 'Daq chaj streets, chaH dress themselves Daq sackcloth. Daq chaj streets je Daq chaj housetops, Hoch wails, weeping abundantly.',
        4: "Heshbon cries pa' tlhej Elealeh. chaj ghogh ghaH Qoyta' 'ach Daq Jahaz. vaj the armed loDpu' vo' Moab SaQ QoymoHlaHbogh. chaj qa'pu' tremble within chaH.",
        5: "wIj tIq cries pa' vaD Moab! Daj nobles Haw' Daq Zoar, Daq Eglath Shelishiyah; vaD chaH jaH Dung Sum the ascent vo' Luhith tlhej weeping; vaD Daq the way vo' Horonaim, chaH raise Dung a SaQ vo' QIH.",
        6: "vaD the bIQmey vo' Nimrim DichDaq taH moB; vaD the grass ghajtaH withered DoH, the tender grass fails, pa' ghaH ghobe' SuD Doch.",
        7: "vaj chaH DichDaq carry DoH the abundance chaH ghaj gotten, je vetlh nuq chaH ghaj stored Dung, Dung the brook vo' the willows.",
        8: "vaD the SaQ ghajtaH ghoSta' around the veHmey vo' Moab; its wailing Daq Eglaim, je its wailing Daq Beer Elim.",
        9: "vaD the bIQmey vo' Dimon 'oH teblu'ta' vo' 'Iw; vaD jIH DichDaq qem yet latlh Daq Dimon, a HaDI'baH Daq chaH vo' Moab 'Iv escape, je Daq the chuv vo' the puH.",
    },
    16: {
        1: "ngeH the 'erHommey vaD the ruler vo' the puH vo' Selah Daq the ngem, Daq the HuD vo' the puqbe' vo' Zion.",
        2: "vaD 'oH DichDaq taH vetlh as wandering toQmey, as a scattered nest, vaj DichDaq the puqbe'pu' vo' Moab taH Daq the fords vo' the Arnon.",
        3: "nob qeS! Execute ruv! chenmoH lIj shade rur the ram Daq the midst vo' the DungluQ! So' the outcasts! yImev magh the fugitive!",
        4: "chaw' wIj outcasts yIn tlhej SoH! As vaD Moab, taH a hiding Daq vaD ghaH vo' the qab vo' the destroyer. vaD the extortioner ghaH qempu' Daq pagh. QIH ceases. The oppressors 'oH Soppu' pa' vo' the puH.",
        5: "A quS'a' DichDaq taH established Daq muSHa'taH pung. wa' DichDaq ba' Daq 'oH Daq vIt, Daq the juHHom vo' David, judging, seeking ruv, je swift Daq ta' QaQtaHghach.",
        6: "maH ghaj Qoyta' vo' the pride vo' Moab, vetlh ghaH ghaH very proud; 'ach vo' Daj arrogance, Daj pride, je Daj QeHpu'. Daj boastings 'oH pagh.",
        7: "vaj Moab DichDaq wail vaD Moab. Hoch DichDaq wail. SoH DichDaq mourn vaD the raisin cakes vo' Kir Hareseth, utterly mup.",
        8: "vaD the fields vo' Heshbon languish tlhej the vine vo' Sibmah. The lords vo' the tuqpu' ghaj ghorta' bIng its choice branches, nuq reached 'ach Daq Jazer, nuq wandered Daq the ngem. Its shoots were ngeH abroad. chaH juSta' Dung the biQ'a'.",
        9: "vaj jIH DichDaq weep tlhej the weeping vo' Jazer vaD the vine vo' Sibmah. jIH DichDaq bIQ SoH tlhej wIj tears, Heshbon, je Elealeh: vaD Daq lIj summer fruits je Daq lIj harvest the may' jach ghajtaH fallen.",
        10: "Quchqu'taHghach ghaH tlhappu' DoH, je Quch pa' vo' the fruitful yotlh; je Daq the vineyards pa' DichDaq taH ghobe' bomtaH, ghobe' joyful noise. Nobody DichDaq yIt pa' HIq Daq the presses. jIH ghaj chenmoHta' the jachtaH stop.",
        11: 'vaj wIj tIq wabmey rur a harp vaD Moab, je wIj inward parts vaD Kir Heres.',
        12: "'oH DichDaq qaS vetlh ghorgh Moab presents himself, ghorgh ghaH wearies himself Daq the jen Daq, je choltaH Daq Daj Daq QaD Daq tlhob, vetlh ghaH DichDaq ghobe' prevail.",
        13: "vam ghaH the mu' vetlh joH'a' jatlhta' concerning Moab Daq poH past.",
        14: "'ach DaH joH'a' ghajtaH jatlhpu', ja'ta', “Within wej DISmey, as a worker bagh Sum contract would count chaH, the batlh vo' Moab DIchDaq taH qempu' Daq contempt, tlhej Hoch Daj Dun qevmey; je the chuv DichDaq taH very mach je feeble.”",
    },
    17: {
        1: "The burden vo' Damascus: “yIlegh, Damascus ghaH tlhappu' DoH vo' taH a veng, je 'oH DichDaq taH a ruinous heap.",
        2: "The vengmey vo' Aroer 'oH lonta'. chaH DichDaq taH vaD flocks, nuq DIchDaq Qot bIng, je pagh DIchDaq chenmoH chaH vIp.",
        3: "The yoDjuH'a' DIchDaq mev vo' Ephraim, je the kingdom vo' Damascus, je the chuv vo' Syria. chaH DichDaq taH as the batlh vo' the puqpu' vo' Israel,” jatlhtaH joH'a' vo' Armies.",
        4: "“'oH DichDaq qaS Daq vetlh jaj vetlh the batlh vo' Jacob DichDaq taH chenmoHta' thin, je the fatness vo' Daj ghab DichDaq moj lean.",
        5: "'oH DichDaq taH rur ghorgh the harvester gathers the wheat, je Daj arm reaps the grain. HIja', 'oH DichDaq taH rur ghorgh wa' gleans grain Daq the ngech vo' Rephaim.",
        6: "Yet gleanings DichDaq taH poS pa', rur the shaking vo' an olive Sor, cha' joq wej olives Daq the top vo' the uppermost bough, loS joq vagh Daq the outermost branches vo' a fruitful Sor,” jatlhtaH joH'a', the joH'a' vo' Israel.",
        7: "Daq vetlh jaj, ghotpu DichDaq legh Daq chaj Maker, je chaj mInDu' DichDaq ghaj respect vaD the le' wa' vo' Israel.",
        8: "chaH DichDaq ghobe' legh Daq the altars, the vum vo' chaj ghopmey; ghobe' DIchDaq chaH respect vetlh nuq chaj fingers ghaj chenmoHta', either the Asherim, joq the He' altars.",
        9: "Daq vetlh jaj, chaj HoS vengmey DichDaq taH rur the lonta' Daqmey Daq the woods je Daq the HuD top, nuq were lonta' vo' qaSpa' the puqpu' vo' Israel; je 'oH DichDaq taH a desolation.",
        10: "vaD SoH ghaj forgotten the joH'a' vo' lIj toDtaHghach, je ghaj ghobe' remembered the nagh vo' lIj HoS. vaj SoH plant bel plants, je cher pa' foreign seedlings.",
        11: "Daq the jaj vo' lIj planting, SoH hedge 'oH Daq. Daq the po, SoH chenmoH lIj tIr blossom, 'ach the harvest flees DoH Daq the jaj vo' grief je vo' desperate QoSqu'.",
        12: "toH, the uproar vo' law' ghotpu', 'Iv roar rur the roaring vo' the seas; je the rushing vo' tuqpu', vetlh rush rur the rushing vo' HoS bIQmey!",
        13: "The tuqpu' DichDaq rush rur the rushing vo' law' bIQmey: 'ach ghaH DichDaq rebuke chaH, je chaH DichDaq Haw' Hop litHa', je DichDaq taH chased rur the yub vo' the Hudmey qaSpa' the SuS, je rur the whirling dust qaSpa' the storm.",
        14: "Daq evening, yIlegh, ghIjvIptaH! qaSpa' the po, chaH 'oH ghobe' latlh. vam ghaH the portion vo' chaH 'Iv plunder maH, je the lot vo' chaH 'Iv rob maH.",
    },
    18: {
        1: "toH, the puH vo' the rustling vo' telDu', nuq ghaH beyond the rivers vo' Ethiopia;",
        2: "vetlh sends ambassadors Sum the biQ'a', 'ach Daq Dujmey vo' papyrus Daq the bIQmey, ja'ta', “jaH, SoH swift Duypu', Daq a Hatlh tall je smooth, Daq a ghotpu awesome vo' chaj tagh onward, a Hatlh vetlh juvtaH pa' je treads bIng, 'Iv puH the rivers divide!”",
        3: "Hoch SoH nganpu' vo' the qo', je SoH dwellers Daq the tera', ghorgh a banner ghaH qengta' Dung Daq the Hudmey, legh! ghorgh the trumpet ghaH blown, 'Ij!",
        4: "vaD joH'a' ja'ta' Daq jIH, “jIH DichDaq taH vIHHa', je jIH DichDaq legh Daq wIj dwelling Daq, rur clear heat Daq sunshine, rur a cloud vo' dew Daq the heat vo' harvest.”",
        5: "vaD qaSpa' the harvest, ghorgh the blossom ghaH Dung, je the flower becomes a ripening grape, ghaH DichDaq pe' litHa' the sprigs tlhej pruning hooks, je ghaH DichDaq pe' bIng je tlhap DoH the spreading branches.",
        6: "chaH DichDaq taH poS tay' vaD the ravenous toQmey vo' the Hudmey, je vaD the Ha'DIbaH vo' the tera'. The ravenous toQmey DichDaq summer Daq chaH, je Hoch the Ha'DIbaH vo' the tera' DichDaq winter Daq chaH.",
        7: "Daq vetlh poH, a present DichDaq taH qempu' Daq joH'a' vo' Armies vo' a ghotpu tall je smooth, 'ach vo' a ghotpu awesome vo' chaj tagh onward, a Hatlh vetlh juvtaH pa' je treads bIng, 'Iv puH the rivers divide, Daq the Daq vo' the pong vo' joH'a' vo' Armies, Mount Zion.",
    },
    19: {
        1: "The burden vo' Egypt: “yIlegh, joH'a' rides Daq a swift cloud, je choltaH Daq Egypt. The idols vo' Egypt DichDaq tremble Daq Daj Daq; je the tIq vo' Egypt DichDaq melt Daq its midst.",
        2: "jIH DichDaq stir Dung the Egyptians Daq the Egyptians, je chaH DichDaq Suv Hoch Daq Daj loDnI', je Hoch Daq Daj jIl; veng Daq veng, je kingdom Daq kingdom.",
        3: "The qa' vo' Egypt DichDaq fail Daq its midst. jIH DichDaq Qaw' its qeS. chaH DichDaq nej the idols, the charmers, chaH 'Iv ghaj familiar spirits, je the wizards.",
        4: "jIH DichDaq nob Dung the Egyptians Daq the ghop vo' a cruel joH. A fierce joH DichDaq rule Dung chaH,” jatlhtaH the joH, joH'a' vo' Armies.",
        5: "The bIQmey DichDaq fail vo' the biQ'a', je the bIQtIQ DichDaq taH wasted je moj dry.",
        6: "The rivers DichDaq moj foul. The streams vo' Egypt DichDaq taH diminished je dried Dung. The reeds je flags DichDaq wither DoH.",
        7: "The meadows Sum the Nile, Sum the brink vo' the Nile, je Hoch the sown fields vo' the Nile, DichDaq moj dry, taH driven DoH, je taH ghobe' latlh.",
        8: "The fishermen DichDaq lament, je Hoch chaH 'Iv fish Daq the Nile DichDaq mourn, je chaH 'Iv ngeH nets Daq the bIQmey DichDaq languish.",
        9: "Moreover chaH 'Iv vum Daq combed flax, je chaH 'Iv weave chIS cloth, DichDaq taH mISmoHpu'.",
        10: "The pillars DichDaq taH ghorta' Daq pieces. Hoch chaH 'Iv vum vaD hire DichDaq taH grieved Daq qa'.",
        11: "The joHHom vo' Zoan 'oH utterly foolish. The qeS vo' the wisest qeSwI'pu' vo' Pharaoh ghajtaH moj stupid. chay' ta' SoH jatlh Daq Pharaoh, “jIH 'oH the puqloD vo' the val, the puqloD vo' ancient joHpu'?”",
        12: "nuqDaq vaj 'oH lIj val loDpu'? chaw' chaH ja' SoH DaH; je chaw' chaH Sov nuq joH'a' vo' Armies ghajtaH purposed concerning Egypt.",
        13: "The joHHom vo' Zoan ghaj moj fools. The joHHom vo' Memphis 'oH deceived. chaH ghaj caused Egypt Daq jaH astray, 'Iv 'oH the cornerstone vo' Daj tuqpu'.",
        14: "joH'a' ghajtaH DuD a qa' vo' perverseness Daq the midst vo' Daj; je chaH ghaj caused Egypt Daq jaH astray Daq Hoch vo' its vum, rur a drunken loD staggers Daq Daj vomit.",
        15: "ghobe' DIchDaq pa' taH vaD Egypt vay' vum, nuq nach joq tail, palm branch joq rush, may ta'.",
        16: "Daq vetlh jaj the Egyptians DichDaq taH rur be'pu'. chaH DichDaq tremble je taHvIp because vo' the shaking vo' the ghop vo' joH'a' vo' Armies, nuq ghaH shakes Dung chaH.",
        17: "The puH vo' Judah DichDaq moj a ghIjvIptaH Daq Egypt. Hoch Daq 'Iv mention ghaH chenmoHta' vo' 'oH DichDaq taH vIp, because vo' the plans vo' joH'a' vo' Armies, nuq ghaH determines Daq 'oH.",
        18: "Daq vetlh jaj, pa' DichDaq taH vagh vengmey Daq the puH vo' Egypt vetlh jatlh the language vo' Canaan, je swear Daq joH'a' vo' Armies. wa' DichDaq taH ja' “The veng vo' QIH.”",
        19: "Daq vetlh jaj, pa' DichDaq taH an lalDanta' Daq Daq joH'a' Daq the midst vo' the puH vo' Egypt, je a pillar Daq joH'a' Daq its veH.",
        20: "'oH DichDaq taH vaD a sign je vaD a witness Daq joH'a' vo' Armies Daq the puH vo' Egypt; vaD chaH DichDaq SaQ Daq joH'a' because vo' oppressors, je ghaH DichDaq ngeH chaH a toDwI' je a defender, je ghaH DichDaq toD chaH.",
        21: "joH'a' DichDaq taH Sovta' Daq Egypt, je the Egyptians DichDaq Sov joH'a' Daq vetlh jaj. HIja', chaH DichDaq lalDan toy' tlhej sacrifice je cha'nob, je DichDaq vow a vow Daq joH'a', je DichDaq perform 'oH.",
        22: "joH'a' DichDaq mup Egypt, striking je healing. chaH DichDaq chegh Daq joH'a', je ghaH DichDaq taH entreated Sum chaH, je DichDaq heal chaH.",
        23: "Daq vetlh jaj pa' DichDaq taH a highway pa' vo' Egypt Daq Assyria, je the Assyrian DIchDaq ghoS Daq Egypt, je the Egyptian Daq Assyria; je the Egyptians DichDaq lalDan toy' tlhej the Assyrians.",
        24: "Daq vetlh jaj, Israel DichDaq taH the wejDIch tlhej Egypt je tlhej Assyria, a blessing Daq the midst vo' the tera';",
        25: "because joH'a' vo' Armies ghajtaH ghurtaH chaH, ja'ta', “ghurtaH taH Egypt wIj ghotpu, Assyria the vum vo' wIj ghopmey, je Israel wIj inheritance.”",
    },
    20: {
        1: "Daq the DIS vetlh Tartan ghoSta' Daq Ashdod, ghorgh Sargon the joH vo' Assyria ngeHta' ghaH, je ghaH Suvta' Daq Ashdod je tlhapta' 'oH;",
        2: "Daq vetlh poH joH'a' jatlhta' Sum Isaiah the puqloD vo' Amoz, ja'ta', “jaH, je loosen the sackcloth vo' litHa' lIj waist, je tlhap lIj shoes vo' litHa' lIj qamDu'.” ghaH ta'ta' vaj, walking naked je barefoot.",
        3: "joH'a' ja'ta', “As wIj toy'wI' Isaiah ghajtaH yItta' naked je barefoot wej DISmey vaD a sign je a wonder concerning Egypt je concerning Ethiopia,",
        4: "vaj the joH vo' Assyria DichDaq Dev DoH the captives vo' Egypt je the exiles vo' Ethiopia, Qup je qan, naked je barefoot, je tlhej buttocks uncovered, Daq the tuH vo' Egypt.",
        5: "chaH DichDaq taH dismayed je mISmoHpu', because vo' Ethiopia chaj expectation, je vo' Egypt chaj batlh.",
        6: "The nganpu' vo' vam coast puH DichDaq jatlh Daq vetlh jaj, ‘yIlegh, vam ghaH maj expectation, nuqDaq maH Haw'ta' vaD QaH Daq taH toDta' vo' the joH vo' Assyria. je maH, chay' DichDaq maH escape?'”",
    },
    21: {
        1: "The burden vo' the ngem vo' the biQ'a'. As whirlwinds Daq the pemHov poS sweep vegh, 'oH choltaH vo' the ngem, vo' an awesome puH.",
        2: "A grievous leghtaHghach ghaH declared Daq jIH. The treacherous loD deals treacherously, je the destroyer destroys. jaH Dung, Elam; attack! jIH ghaj stopped Hoch vo' Media's sighing.",
        3: "vaj wIj thighs 'oH tebta' tlhej anguish. Pains ghaj tlhappu' 'uch Daq jIH, rur the pains vo' a be' Daq labor. jIH 'oH Daq vaj 'ar pain vetlh jIH ta'laHbe' Qoy. jIH vaj 'oH dismayed vetlh jIH ta'laHbe' legh.",
        4: "wIj tIq flutters. Horror ghajtaH frightened jIH. The twilight vetlh jIH neH ghajtaH taH tlhe'ta' Daq trembling vaD jIH.",
        5: "chaH ghuH the SopDaq. chaH cher the watch. chaH Sop. chaH tlhutlh. Hu' Dung, SoH joHHom, Hergh the yoD!",
        6: "vaD the joH ja'ta' Daq jIH, “jaH, cher a watchman. chaw' ghaH declare nuq ghaH sees.",
        7: "ghorgh ghaH sees a troop, horsemen Daq pairs, a troop vo' donkeys, a troop vo' camels, ghaH DIchDaq 'Ij diligently tlhej Dun attentiveness.”",
        8: "ghaH SaQta' rur a HaDI'baH: “joH, jIH Qam continually Daq the watchtower Daq the pem, je Hoch ram jIH stay Daq wIj post.",
        9: "yIlegh, naDev choltaH a troop vo' loDpu', horsemen Daq pairs.” ghaH jangta', “Fallen, fallen ghaH Babylon; je Hoch the engraved images vo' Daj Qunpu' 'oH ghorta' Daq the yav.",
        10: "SoH 'oH wIj threshing, je the grain vo' wIj floor!” vetlh nuq jIH ghaj Qoyta' vo' joH'a' vo' Armies, the joH'a' vo' Israel, jIH ghaj declared Daq SoH.",
        11: "The burden vo' Dumah. wa' calls Daq jIH pa' vo' Seir, “Watchman, nuq vo' the ram? Watchman, nuq vo' the ram?”",
        12: "The watchman ja'ta', “The po choltaH, je je the ram. chugh SoH DichDaq inquire, inquire. ghoS DoH again.”",
        13: "The burden Daq Arabia. Daq the forest Daq Arabia SoH DichDaq juH, SoH caravans vo' Dedanites.",
        14: "chaH qempu' bIQ Daq ghaH 'Iv ghaHta' thirsty. The nganpu' vo' the puH vo' Tema met the fugitives tlhej chaj tIr Soj.",
        15: "vaD chaH Haw'ta' DoH vo' the swords, vo' the drawn 'etlh, vo' the SIHta'bogh bow, je vo' the heat vo' may'.",
        16: "vaD the joH ja'ta' Daq jIH, “Within a DIS, as a worker bagh Sum contract would count 'oH, Hoch the batlh vo' Kedar DichDaq fail,",
        17: "je the residue vo' the mI' vo' the archers, the HoS loDpu' vo' the puqpu' vo' Kedar, DichDaq taH few; vaD joH'a', the joH'a' vo' Israel, ghajtaH jatlhpu' 'oH.”",
    },
    22: {
        1: "The burden vo' the ngech vo' leghtaHghach. nuq roptaH SoH DaH, vetlh SoH ghaj Hoch ghoSta' Dung Daq the housetops?",
        2: "SoH vetlh 'oH teblu'ta' vo' jachtaH, a tumultuous veng, a joyous vengHom; lIj Heghta' 'oH ghobe' Heghta' tlhej the 'etlh, ghobe' 'oH chaH Heghpu' Daq may'.",
        3: "Hoch lIj DevwIpu' Haw'ta' DoH tay'. chaH were bagh Sum the archers. Hoch 'Iv were tu'ta' Sum SoH were bagh tay'. chaH Haw'ta' Hop DoH.",
        4: "vaj jIH ja'ta', “legh DoH vo' jIH. jIH DichDaq weep bitterly. yImev labor Daq belmoH jIH vaD the QIH vo' the puqbe' vo' wIj ghotpu.",
        5: "vaD 'oH ghaH a jaj vo' confusion, je vo' treading bIng, je vo' perplexity, vo' the joH, joH'a' vo' Armies, Daq the ngech vo' leghtaHghach; a breaking bIng vo' the walls, je a crying Daq the Hudmey.”",
        6: "Elam qengta' Daj quiver, tlhej Dujmey vo' loDpu' je horsemen; je Kir uncovered the yoD.",
        7: "'oH qaSta' vetlh lIj choicest valleys were teblu'ta' vo' Dujmey, je the horsemen cher themselves Daq array Daq the lojmIt.",
        8: "ghaH tlhapta' DoH the covering vo' Judah; je SoH nejta' Daq vetlh jaj Daq the armor Daq the tuq vo' the forest.",
        9: "SoH leghta' the breaches vo' the veng vo' David, vetlh chaH were law'; je SoH boSta' tay' the bIQmey vo' the lower pool.",
        10: "SoH toghta' the juHmey vo' Jerusalem, je SoH broke bIng the juHmey Daq fortify the reD.",
        11: "SoH je chenmoHta' a reservoir joj the cha' walls vaD the bIQ vo' the qan pool. 'ach SoH ta'be' legh Daq ghaH 'Iv ghajta' ta'pu' vam, ghobe' ta'ta' SoH ghaj respect vaD ghaH 'Iv purposed 'oH tIq ben.",
        12: "Daq vetlh jaj, the joH, joH'a' vo' Armies, ja' Daq weeping, je Daq mourning, je Daq jIb ghajbe', je Daq dressing Daq sackcloth:",
        13: "je yIlegh, Quch je Quchqu'taHghach, killing cattle je killing Suy', eating ghab je drinking HIq: “chaw' maH Sop je tlhutlh, vaD wa'leS maH DichDaq Hegh.”",
        14: "joH'a' vo' Armies 'angta' himself Daq wIj qoghDu', “DIch vam He'taHghach DichDaq ghobe' taH forgiven SoH until SoH Hegh,” jatlhtaH the joH, joH'a' vo' Armies.",
        15: "Thus jatlhtaH the joH, joH'a' vo' Armies, “jaH, tlhap SoH'egh Daq vam treasurer, 'ach Daq Shebna, 'Iv ghaH Dung the tuq, je jatlh,",
        16: "‘nuq 'oH SoH doing naDev? 'Iv ghajtaH SoH naDev, vetlh SoH ghaj dug pa' a tomb naDev?' Cutting himself pa' a tomb Daq jen, chiseling a juH vaD himself Daq the nagh!”",
        17: "yIlegh, joH'a' DichDaq overcome SoH je hurl SoH DoH violently. HIja', ghaH DichDaq grasp SoH firmly.",
        18: "ghaH DichDaq DIch SuS SoH around je around, je throw SoH rur a moQ Daq a large Hatlh. pa' SoH DichDaq Hegh, je pa' the Dujmey vo' lIj batlh DichDaq taH, SoH tuH vo' lIj joH tuq.",
        19: "jIH DichDaq thrust SoH vo' lIj office. SoH DichDaq taH pulled bIng vo' lIj station.",
        20: "'oH DichDaq qaS Daq vetlh jaj vetlh jIH DichDaq ja' wIj toy'wI' Eliakim the puqloD vo' Hilkiah,",
        21: "je jIH DichDaq clothe ghaH tlhej lIj robe, je strengthen ghaH tlhej lIj belt. jIH DichDaq commit lIj government Daq Daj ghop; je ghaH DichDaq taH a vav Daq the nganpu' vo' Jerusalem, je Daq the tuq vo' Judah.",
        22: "jIH DichDaq lay the key vo' the tuq vo' David Daq Daj shoulder. ghaH DichDaq poSmoH, je ghobe' wa' DichDaq shut. ghaH DichDaq shut, je ghobe' wa' DichDaq poSmoH.",
        23: "jIH DichDaq fasten ghaH rur a nail Daq a sure Daq. ghaH DichDaq taH vaD a quS'a' vo' batlh Daq Daj vav tuq.",
        24: "chaH DichDaq hang Daq ghaH Hoch the batlh vo' Daj vav tuq, the offspring je the issue, Hoch mach vessel, vo' the cups 'ach Daq Hoch the pitchers.",
        25: "“Daq vetlh jaj,” jatlhtaH joH'a' vo' Armies, “the nail vetlh ghaHta' fastened Daq a sure Daq DichDaq nob way. 'oH DichDaq taH pe' bIng, je pum. The burden vetlh ghaHta' Daq 'oH DichDaq taH pe' litHa', vaD joH'a' ghajtaH jatlhpu' 'oH.”",
    },
    23: {
        1: "The burden vo' Tyre. Howl, SoH ships vo' Tarshish! vaD 'oH ghaH laid waste, vaj vetlh pa' ghaH ghobe' tuq, ghobe' entering Daq. vo' the puH vo' Kittim 'oH ghaH 'angta' Daq chaH.",
        2: "taH vIHHa', SoH nganpu' vo' the coast, SoH 'Iv the merchants vo' Sidon, vetlh juS Dung the biQ'a', ghaj replenished.",
        3: "Daq Dun bIQmey, the tIr vo' the Shihor, the harvest vo' the Nile, ghaHta' Daj revenue. ghaH ghaHta' the market vo' tuqpu'.",
        4: "taH tuH, Sidon; vaD the biQ'a' ghajtaH jatlhpu', the stronghold vo' the biQ'a', ja'ta', “jIH ghaj ghobe' travailed, ghobe' qempu' vo', ghobe' ghaj jIH je'moHta' Qup loDpu', ghobe' qempu' Dung virgins.”",
        5: "ghorgh the report choltaH Daq Egypt, chaH DichDaq taH Daq anguish Daq the report vo' Tyre.",
        6: "juS Dung Daq Tarshish! Wail, SoH nganpu' vo' the coast!",
        7: "ghaH vam lIj joyous veng, 'Iv antiquity ghaH vo' ancient jajmey, 'Iv qamDu' qengta' Daj Hop DoH Daq travel?",
        8: "'Iv ghajtaH planned vam Daq Tyre, the giver vo' crowns, 'Iv merchants 'oH joHHom, 'Iv traffickers 'oH the honorable vo' the tera'?",
        9: "joH'a' vo' Armies ghajtaH planned 'oH, Daq stain the pride vo' Hoch batlh, Daq qem Daq contempt Hoch the honorable vo' the tera'.",
        10: "juS vegh lIj puH rur the Nile, puqbe' vo' Tarshish. pa' ghaH ghobe' restraint vay' latlh.",
        11: "ghaH ghajtaH stretched pa' Daj ghop Dung the biQ'a'. ghaH ghajtaH shaken the kingdoms. joH'a' ghajtaH ordered the QIH vo' Canaan's strongholds.",
        12: "ghaH ja'ta', “SoH DIchDaq yItIv ghobe' latlh, SoH Suvta' virgin puqbe' vo' Sidon. Hu', juS Dung Daq Kittim. 'ach pa' SoH DichDaq ghaj ghobe' leS.”",
        13: "yIlegh, the puH vo' the Chaldeans. vam ghotpu ghaHta' ghobe'. The Assyrians founded 'oH vaD chaH 'Iv yIn Daq the ngem. chaH cher Dung chaj towers. chaH overthrew its palaces. chaH chenmoHta' 'oH a ruin.",
        14: "Howl, SoH ships vo' Tarshish, vaD lIj stronghold ghaH laid waste!",
        15: "'oH DichDaq ghoS Daq juS Daq vetlh jaj vetlh Tyre DichDaq taH forgotten seventy DISmey, according Daq the jajmey vo' wa' joH. After the pItlh vo' seventy DISmey 'oH DichDaq taH Daq Tyre rur Daq the bom vo' the naybe'wI'.",
        16: "tlhap a harp; jaH about the veng, SoH naybe'wI' vetlh ghajtaH taH forgotten. chenmoH sweet melody. bom law' bommey, vetlh SoH may taH remembered.",
        17: "'oH DichDaq qaS after the pItlh vo' seventy DISmey vetlh joH'a' DichDaq visit Tyre, je ghaH DIchDaq chegh Daq Daj wages, je DichDaq play the naybe'wI' tlhej Hoch the kingdoms vo' the qo' Daq the surface vo' the tera'.",
        18: "Daj merchandise je Daj wages DichDaq taH holiness Daq joH'a'. 'oH DichDaq ghobe' taH treasured ghobe' laid Dung; vaD Daj merchandise DichDaq taH vaD chaH 'Iv yIn qaSpa' joH'a', Daq Sop sufficiently, je vaD durable Sut.",
    },
    24: {
        1: "yIlegh, joH'a' chen the tera' empty, chen 'oH waste, turns 'oH upside bIng, je scatters its nganpu'.",
        2: "'oH DichDaq taH as tlhej the ghotpu, vaj tlhej the lalDan vumwI'; as tlhej the toy'wI', vaj tlhej Daj pIn; as tlhej the maid, vaj tlhej Daj mistress; as tlhej the buyer, vaj tlhej the seller; as tlhej the creditor, vaj tlhej the debtor; as tlhej the taker vo' interest, vaj tlhej the giver vo' interest.",
        3: "The tera' DichDaq taH utterly emptied je utterly laid waste; vaD joH'a' ghajtaH jatlhpu' vam mu'.",
        4: "The tera' mourns je ngabtaH DoH. The qo' languishes je ngabtaH DoH. The lofty ghotpu vo' the tera' languish.",
        5: "The tera' je ghaH polluted bIng its nganpu', because chaH ghaj transgressed the laws, violated the chutmey, je ghorta' the everlasting lay'.",
        6: "vaj the mu'qaD ghajtaH Soppu' the tera', je chaH 'Iv yIn therein 'oH tu'ta' guilty. vaj the nganpu' vo' the tera' 'oH meQpu', je few loDpu' poS.",
        7: "The chu' HIq mourns. The vine languishes. Hoch the yItIv-hearted sigh.",
        8: "The mirth vo' tambourines ceases. The wab vo' chaH 'Iv yItIv ends. The Quch vo' the harp ceases.",
        9: "chaH DichDaq ghobe' tlhutlh HIq tlhej a bom. HoS tlhutlh DichDaq taH bitter Daq chaH 'Iv tlhutlh 'oH.",
        10: "The confused veng ghaH ghorta' bIng. Hoch tuq ghaH shut Dung, vetlh ghobe' loD may ghoS Daq.",
        11: "pa' ghaH a crying Daq the streets because vo' the HIq. Hoch Quch ghaH darkened. The mirth vo' the puH ghaH ghoSta'.",
        12: 'The veng ghaH poS Daq desolation, je the lojmIt ghaH struck tlhej QIH.',
        13: "vaD 'oH DichDaq taH vaj Daq the midst vo' the tera' among the ghotpu', as the shaking vo' an olive Sor, as the gleanings ghorgh the vintage ghaH ta'pu'.",
        14: "Dochvammey DIchDaq lift Dung chaj ghogh. chaH DichDaq jach vaD the majesty vo' joH'a'. chaH SaQ QoymoHlaHbogh vo' the biQ'a'.",
        15: "vaj glorify joH'a' Daq the pemHov 'o', 'ach the pong vo' joH'a', the joH'a' vo' Israel, Daq the islands vo' the biQ'a'!",
        16: "vo' the uttermost part vo' the tera' ghaj maH Qoyta' bommey. batlh Daq the QaQtaHghach! 'ach jIH ja'ta', “jIH pine DoH! jIH pine DoH! woe ghaH jIH!” The treacherous ghaj dealt treacherously. HIja', the treacherous ghaj dealt very treacherously.",
        17: "taHvIp, the pit, je the tojta'ghach, 'oH Daq SoH 'Iv inhabitant the tera'.",
        18: "'oH DichDaq qaS vetlh ghaH 'Iv flees vo' the noise vo' the taHvIp DichDaq pum Daq the pit; je ghaH 'Iv choltaH Dung pa' vo' the midst vo' the pit DichDaq taH tlhappu' Daq the tojta'ghach; vaD the windows Daq jen 'oH poSmaHpu', je the foundations vo' the tera' tremble.",
        19: "The tera' ghaH utterly ghorta'. The tera' ghaH torn apart. The tera' ghaH shaken violently.",
        20: "The tera' DichDaq stagger rur a drunken loD, je DichDaq sway DoH je vo' rur a hammock. Its disobedience DichDaq taH 'ugh Daq 'oH, je 'oH DichDaq pum je ghobe' Hu' again.",
        21: "'oH DIchDaq qaS Daq vetlh jaj vetlh joH'a' DichDaq punish the army vo' the jen ones Daq jen, je the joHpu' vo' the tera' Daq the tera'.",
        22: "chaH DIchDaq taH boSta' tay', as prisoners 'oH boSta' Daq the pit, je DIchDaq taH shut Dung Daq the prison; je after law' jajmey DIchDaq chaH taH visited.",
        23: "vaj the maS DIchDaq taH mISmoHpu', je the pemHov tuH; vaD joH'a' vo' Armies DichDaq che' Daq Mount Zion, je Daq Jerusalem; je qaSpa' Daj quppu' DichDaq taH batlh.",
    },
    25: {
        1: "joH'a', SoH 'oH wIj joH'a'. jIH DichDaq exalt SoH! jIH DichDaq naD lIj pong, vaD SoH ghaj ta'pu' wonderful Dochmey, Dochmey planned tIq ben, Daq complete voqtaHghach je vIt.",
        2: "vaD SoH ghaj chenmoHta' a veng Daq a heap, a fortified veng Daq a ruin, a palace vo' novpu' Daq taH ghobe' veng. 'oH DichDaq never taH chenta'.",
        3: "vaj a HoS ghotpu DichDaq glorify SoH. A veng vo' awesome tuqpu' DichDaq taHvIp SoH.",
        4: "vaD SoH ghaj taH a stronghold Daq the mIpHa', a stronghold Daq the needy Daq Daj distress, a lulIgh vo' the storm, a shade vo' the heat, ghorgh the blast vo' the dreaded ones ghaH rur a storm Daq the reD.",
        5: "As the heat Daq a dry Daq DichDaq SoH qem bIng the noise vo' novpu'; as the heat Sum the shade vo' a cloud, the bom vo' the dreaded ones DichDaq taH qempu' low.",
        6: "Daq vam HuD, joH'a' vo' Armies DichDaq chenmoH Hoch ghotpu' a 'uQ'a' vo' ror Dochmey, a 'uQ'a' vo' choice wines, vo' ror Dochmey teblu'ta' vo' marrow, vo' QaQ refined choice wines.",
        7: "ghaH DichDaq Qaw' Daq vam HuD the surface vo' the covering vetlh covers Hoch ghotpu', je the veil vetlh ghaH ngeH Dung Hoch tuqpu'.",
        8: "ghaH ghajtaH swallowed Dung Hegh reH! The joH joH'a' DichDaq wipe DoH tears vo' litHa' Hoch faces. ghaH DichDaq tlhap the reproach vo' Daj ghotpu DoH vo' litHa' Hoch the tera', vaD joH'a' ghajtaH jatlhpu' 'oH.",
        9: "'oH DIchDaq taH ja'ta' Daq vetlh jaj, “yIlegh, vam ghaH maj joH'a'! maH ghaj waited vaD ghaH, je ghaH DichDaq toD maH! vam ghaH joH'a'! maH ghaj waited vaD ghaH. maH DichDaq taH Quchqu' je yItIv Daq Daj toDtaHghach!”",
        10: "vaD Daq vam HuD the ghop vo' joH'a' DichDaq leS. Moab DichDaq taH trodden bIng Daq Daj Daq, 'ach rur straw ghaH trodden bIng Daq the bIQ vo' the dunghill.",
        11: "ghaH DichDaq ngeH pa' Daj ghopmey Daq its midst, rur wa' 'Iv swims spreads pa' ghopmey Daq swim, 'ach Daj pride DichDaq taH humbled tay' tlhej the craft vo' Daj ghopmey.",
        12: "ghaH ghajtaH qempu' the jen yoDjuH'a' vo' lIj walls bIng, laid low, je qempu' Daq the yav, 'ach Daq the dust.",
    },
    26: {
        1: "Daq vetlh jaj, vam bom DichDaq taH sung Daq the puH vo' Judah: “maH ghaj a HoS veng. joH'a' appoints toDtaHghach vaD walls je bulwarks.",
        2: "poSmoH the lojmItmey, vetlh the QaQtaHghach Hatlh may 'el: the wa' nuq keeps HartaHghach.",
        3: "SoH DichDaq pol whoever's yab ghaH steadfast Daq perfect roj, because ghaH trusts Daq SoH.",
        4: "voq Daq joH'a' reH; vaD Daq joH'a', joH'a', ghaH an everlasting nagh.",
        5: "vaD ghaH ghajtaH qempu' bIng chaH 'Iv yIn Daq jen, the lofty veng. ghaH lays 'oH low. ghaH lays 'oH low 'ach Daq the yav. ghaH brings 'oH 'ach Daq the dust.",
        6: "The qam DIchDaq yIt 'oH bIng; 'ach the qamDu' vo' the mIpHa', je the steps vo' the needy.”",
        7: "The way vo' the just ghaH uprightness. SoH 'Iv 'oH upright chenmoH the path vo' the QaQtaHghach level.",
        8: "HIja', Daq the way vo' lIj judgments, joH'a', ghaj maH waited vaD SoH. lIj pong je lIj renown 'oH the neH vo' maj qa'.",
        9: "tlhej wIj qa' ghaj jIH neH SoH Daq the ram. HIja', tlhej wIj qa' within jIH DichDaq jIH nej SoH earnestly; vaD ghorgh lIj judgments 'oH Daq the tera', the nganpu' vo' the qo' ghoj QaQtaHghach.",
        10: "chaw' favor taH shown Daq the mIgh, yet ghaH DichDaq ghobe' ghoj QaQtaHghach. Daq the puH vo' uprightness ghaH DichDaq Da wrongfully, je DichDaq ghobe' legh joH'a' majesty.",
        11: "joH'a', lIj ghop ghaH qengta' Dung, yet chaH yImev legh; 'ach chaH DichDaq legh lIj zeal vaD the ghotpu, je taH disappointed. HIja', qul DichDaq consume lIj jaghpu'.",
        12: "joH'a', SoH DichDaq ordain roj vaD maH, vaD SoH ghaj je worked Hoch maj vum vaD maH.",
        13: "joH'a' maj joH'a', latlh lords je SoH ghaj ghajta' dominion Dung maH, 'ach Sum SoH neH DichDaq maH chenmoH mention vo' lIj pong.",
        14: "The Heghpu' DIchDaq ghobe' yIn. The deceased DIchDaq ghobe' Hu'. vaj ghaj SoH visited je Qaw'ta' chaH, je caused Hoch memory vo' chaH Daq chIlqu'.",
        15: "SoH ghaj increased the Hatlh, toH joH'a'. SoH ghaj increased the Hatlh! SoH 'oH glorified! SoH ghaj enlarged Hoch the veHmey vo' the puH.",
        16: "joH'a', Daq Seng chaH ghaj visited SoH. chaH poured pa' a tlhobtaHghach ghorgh lIj chastening ghaHta' Daq chaH.",
        17: "rur as a be' tlhej puq, 'Iv draws Sum the poH vo' Daj delivery, ghaH Daq pain je cries pa' Daq Daj pangs; vaj maH ghaj taH qaSpa' SoH, joH'a'.",
        18: "maH ghaj taH tlhej puq. maH ghaj taH Daq pain. maH nobta' birth, 'oH seems, neH Daq SuS. maH ghaj ghobe' worked vay' deliverance Daq the tera'; ghobe' ghaj the nganpu' vo' the qo' fallen.",
        19: "lIj Heghpu' DIchDaq yIn. wIj Heghpu' porghmey DIchDaq Hu'. Awake je bom, SoH 'Iv yIn Daq the dust; vaD lIj dew ghaH rur the dew vo' herbs, je the tera' DichDaq chuH vo' the Heghpu'.",
        20: "ghoS, wIj ghotpu, 'el Daq lIj chambers, je shut lIj doors behind SoH. So' SoH'egh vaD a mach moment, until the indignation ghaH past.",
        21: "vaD, yIlegh, joH'a' choltaH vo' pa' vo' Daj Daq Daq punish the nganpu' vo' the tera' vaD chaj He'taHghach. The tera' je DichDaq disclose Daj 'Iw, je DichDaq ghobe' longer So' Daj Heghta'.",
    },
    27: {
        1: "Daq vetlh jaj, joH'a' tlhej Daj hard je Dun je HoS 'etlh DichDaq punish leviathan, the fleeing lung, je leviathan the twisted lung; je ghaH DichDaq HoH the dragon vetlh ghaH Daq the biQ'a'.",
        2: 'Daq vetlh jaj, bom Daq Daj, “A bel HIq wIj!',
        3: "jIH, joH'a', 'oH its keeper. jIH DichDaq bIQ 'oH Hoch moment. Lest anyone damage 'oH, jIH DichDaq pol 'oH ram je jaj.",
        4: "QeHpu' ghaH ghobe' Daq jIH, 'ach chugh jIH should tu' briers je thorns, jIH would ta' may'! jIH would march Daq chaH je jIH would meQ chaH tay'.",
        5: "joq else chaw' ghaH tlhap 'uch vo' wIj HoS, vetlh ghaH may chenmoH roj tlhej jIH. chaw' ghaH chenmoH roj tlhej jIH.”",
        6: "Daq jajmey Daq ghoS, Jacob DichDaq tlhap root. Israel DichDaq blossom je bud. chaH DichDaq fill the surface vo' the qo' tlhej baQ.",
        7: "ghajtaH ghaH struck chaH as ghaH struck chaH 'Iv struck chaH? joq 'oH chaH HoHta' rur chaH 'Iv HoHta' chaH were HoHta'?",
        8: "Daq juv, ghorgh SoH ngeH chaH DoH, SoH contend tlhej chaH. ghaH ghajtaH teqta' chaH tlhej Daj rough blast Daq the jaj vo' the pemHov 'o' SuS.",
        9: "vaj, Sum vam the He'taHghach vo' Jacob DichDaq taH forgiven, je vam ghaH Hoch the baQ vo' taking DoH Daj yem: vetlh ghaH chen Hoch the naghmey vo' the lalDanta' Daq as chalk naghmey vetlh 'oH beaten Daq pieces, vaj vetlh the Asherim je the He' altars DIchDaq Hu' ghobe' latlh.",
        10: "vaD the fortified veng ghaH solitary, a juH deserted je lonta', rur the ngem. The calf DichDaq feed pa', je pa' ghaH DichDaq Qot bIng, je consume its branches.",
        11: "ghorgh its boughs 'oH withered, chaH DichDaq taH ghorta' litHa'. The be'pu' DichDaq ghoS je cher chaH Daq qul, vaD chaH 'oH a ghotpu vo' ghobe' yajtaHghach. vaj ghaH 'Iv chenmoHta' chaH DichDaq ghobe' ghaj compassion Daq chaH, je ghaH 'Iv formed chaH DichDaq cha' chaH ghobe' favor.",
        12: "'oH DichDaq qaS Daq vetlh jaj, vetlh joH'a' DichDaq thresh vo' the flowing stream vo' the Euphrates Daq the brook vo' Egypt; je SoH DichDaq taH boSta' wa' Sum wa', puqpu' vo' Israel.",
        13: "'oH DichDaq qaS Daq vetlh jaj vetlh a Dun trumpet DichDaq taH blown; je chaH 'Iv were ready Daq chIlqu' Daq the puH vo' Assyria, je chaH 'Iv were outcasts Daq the puH vo' Egypt, DIchDaq ghoS; je chaH DichDaq lalDan toy' joH'a' Daq the le' HuD Daq Jerusalem.",
    },
    28: {
        1: "Woe Daq the crown vo' pride vo' the drunkards vo' Ephraim, je Daq the fading flower vo' Daj glorious 'IhtaHghach, nuq ghaH Daq the nach vo' the fertile ngech vo' chaH 'Iv 'oH overcome tlhej HIq!",
        2: "yIlegh, the joH ghajtaH a HoS je HoS wa'. rur a storm vo' hail, a destroying storm, je rur a storm vo' HoS bIQmey overflowing, ghaH DichDaq chuH chaH bIng Daq the tera' tlhej Daj ghop.",
        3: "The crown vo' pride vo' the drunkards vo' Ephraim DichDaq taH trodden bIng qam.",
        4: "The fading flower vo' Daj glorious 'IhtaHghach, nuq ghaH Daq the nach vo' the fertile ngech, DIchDaq taH rur the wa'Dich-ripe fig qaSpa' the summer; nuq someone picks je eats as soon as ghaH sees 'oH.",
        5: "Daq vetlh jaj, joH'a' vo' Armies DichDaq moj a crown vo' batlh, je a diadem vo' 'IhtaHghach, Daq the residue vo' Daj ghotpu;",
        6: "je a qa' vo' ruv Daq ghaH 'Iv sits Daq yoj, je HoS Daq chaH 'Iv tlhe' DoH the may' Daq the lojmIt.",
        7: "chaH je reel tlhej HIq, je stagger tlhej HoS tlhutlh. The lalDan vumwI' je the leghwI'pu' reel tlhej HoS tlhutlh. chaH 'oH swallowed Dung Sum HIq. chaH stagger tlhej HoS tlhutlh. chaH err Daq leghtaHghach. chaH stumble Daq yoj.",
        8: "vaD Hoch tables 'oH completely teblu'ta' vo' filthy vomit je filthiness.",
        9: "'Iv DichDaq ghaH ghojmoH Sov? Daq 'Iv DichDaq ghaH explain the message? chaH 'Iv 'oH weaned vo' the milk, je drawn vo' the breasts?",
        10: "vaD 'oH ghaH precept Daq precept, precept Daq precept; tlhegh Daq tlhegh, tlhegh Daq tlhegh; naDev a mach, pa' a mach.",
        11: "'ach ghaH DichDaq jatlh Daq vam Hatlh tlhej stammering wuSDu' je Daq another language;",
        12: "Daq 'Iv ghaH ja'ta', “vam ghaH the resting Daq. nob leS Daq Doy';” je “vam ghaH the refreshing;” yet chaH would ghobe' Qoy.",
        13: "vaj the mu' vo' joH'a' DichDaq taH Daq chaH precept Daq precept, precept Daq precept; tlhegh Daq tlhegh, tlhegh Daq tlhegh; naDev a mach, pa' a mach; vetlh chaH may jaH, pum DoH, taH ghorta', taH snared, je taH tlhappu'.",
        14: "vaj Qoy the mu' vo' joH'a', SoH scoffers, vetlh rule vam ghotpu Daq Jerusalem:",
        15: "“Because SoH ghaj ja'ta', ‘maH ghaj chenmoHta' a lay' tlhej Hegh, je tlhej Sheol { Note: Sheol ghaH the Daq vo' the Heghpu'. } 'oH maH Daq Qochbe'ghach. ghorgh the overflowing scourge passes vegh, 'oH won't ghoS Daq maH; vaD maH ghaj chenmoHta' lies maj lulIgh, je maH ghaj hidden ourselves bIng falsehood.'”",
        16: "vaj thus jatlhtaH the joH joH'a', “yIlegh, jIH lay Daq Zion vaD a foundation a nagh, a tried nagh, a precious cornerstone vo' a sure foundation. ghaH 'Iv HartaH DIchDaq ghobe' vang hastily.",
        17: "jIH DichDaq chenmoH ruv the measuring tlhegh, je QaQtaHghach the plumb tlhegh. The hail DichDaq sweep DoH the lulIgh vo' lies, je the bIQmey DichDaq overflow the hiding Daq.",
        18: "lIj lay' tlhej Hegh DIchDaq taH annulled, je lIj Qochbe'ghach tlhej Sheol { Note: Sheol ghaH the Daq vo' the Heghpu'. } DIchDaq ghobe' Qam. ghorgh the overflowing scourge passes vegh, vaj SoH DichDaq taH trampled bIng Sum 'oH.",
        19: "As often as 'oH passes vegh, 'oH DichDaq seize SoH; vaD po Sum po 'oH DichDaq juS vegh, Sum jaj je Sum ram; je 'oH DichDaq taH pagh 'ach ghIjvIptaH Daq understand the message.”",
        20: "vaD the bed ghaH too short Daq stretch pa' Daq, je the blanket ghaH too narrow Daq wrap oneself Daq.",
        21: "vaD joH'a' DichDaq Hu' Dung as Daq Mount Perazim. ghaH DichDaq taH angry as Daq the ngech vo' Gibeon; vetlh ghaH may ta' Daj vum, Daj unusual vum, je qem Daq juS Daj vang, Daj extraordinary vang.",
        22: "DaH vaj yImev taH scoffers, lest lIj bonds taH chenmoHta' HoS; vaD jIH ghaj Qoyta' a decree vo' QIH vo' the joH, joH'a' vo' Armies, Daq the Hoch tera'.",
        23: "nob qogh, je Qoy wIj ghogh! 'Ij, je Qoy wIj speech!",
        24: "ta'taH ghaH 'Iv plows Daq sow plow continually? ta'taH ghaH pol turning the soil je breaking the clods?",
        25: "ghorgh ghaH ghajtaH leveled its surface, ta'be' ghaH plant the dill, je scatter the cumin tIr, je lan Daq the wheat Daq rows, the barley Daq the wIv Daq, je the spelt Daq its Daq?",
        26: "vaD Daj joH'a' instructs ghaH Daq nIH yoj, je teaches ghaH.",
        27: "vaD the dill 'oH ghobe' threshed tlhej a sharp instrument, ghobe' ghaH a cart wheel tlhe'ta' Dung the cumin; 'ach the dill ghaH beaten pa' tlhej a stick, je the cumin tlhej a DevwI' naQ.",
        28: "tIr Soj flour must taH yav; vaj ghaH DichDaq ghobe' always taH threshing 'oH. Although ghaH drives the wheel vo' Daj threshing cart Dung 'oH, Daj horses yImev grind 'oH.",
        29: "vam je choltaH vo' vo' joH'a' vo' Armies, 'Iv ghaH wonderful Daq qeS, je excellent Daq valtaHghach.",
    },
    29: {
        1: "Woe Daq Ariel! Ariel, the veng nuqDaq David Dabta'! chel DIS Daq DIS; chaw' the yupma'mey ghoS around;",
        2: "vaj jIH DichDaq distress Ariel, je pa' DichDaq taH mourning je lamentation. ghaH DIchDaq taH Daq jIH as an lalDanta' Daq hearth { Note: joq, Ariel }.",
        3: 'jIH DichDaq Dab Daq SoH Hoch around SoH, je DichDaq lay siege Daq SoH tlhej posted troops. jIH DichDaq raise siege vum Daq SoH.',
        4: "SoH DichDaq taH qempu' bIng, je DichDaq jatlh pa' vo' the yav. lIj speech DichDaq mumble pa' vo' the dust. lIj ghogh DichDaq taH as vo' wa' 'Iv ghajtaH a familiar qa', pa' vo' the yav, je lIj speech DichDaq whisper pa' vo' the dust.",
        5: "'ach the qevmey vo' lIj foes DichDaq taH rur fine dust, je the qevmey vo' the ruthless ones rur yub vetlh blows DoH. HIja', 'oH DichDaq taH Daq an instant, suddenly.",
        6: "ghaH DichDaq taH visited Sum joH'a' vo' Armies tlhej thunder, tlhej earthquake, tlhej Dun noise, tlhej whirlwind je storm, je tlhej the flame vo' a devouring qul.",
        7: "The qevmey vo' Hoch the tuqpu' vetlh Suv Daq Ariel, 'ach Hoch 'Iv Suv Daq Daj je Daj stronghold, je 'Iv distress Daj, DichDaq taH rur a dream, a leghtaHghach vo' the ram.",
        8: "'oH DichDaq taH rur ghorgh a hungry loD dreams, je yIlegh, ghaH eats; 'ach ghaH awakes, je Daj hunger 'oHbe' satisfied; joq rur ghorgh a thirsty loD dreams, je yIlegh, ghaH drinks; 'ach ghaH awakes, je yIlegh, ghaH ghaH puj, je ghaH ghaH vIHHa' thirsty. The qevmey vo' Hoch the tuqpu' vetlh Suv Daq Mount Zion DichDaq taH rur vetlh.",
        9: "Pause je wonder! Blind tlhIH'egh je taH blind! chaH 'oH drunken, 'ach ghobe' tlhej HIq; chaH stagger, 'ach ghobe' tlhej HoS tlhutlh.",
        10: "vaD joH'a' ghajtaH poured pa' Daq SoH a qa' vo' deep Qong, je ghajtaH SoQ lIj mInDu', the leghwI'pu'; je ghaH ghajtaH covered lIj nachDu', the seers.",
        11: "Hoch leghtaHghach ghajtaH moj Daq SoH rur the mu'mey vo' a paq vetlh ghaH sealed, nuq loDpu' toD Daq wa' 'Iv ghaH educated, ja'ta', “Read vam, please;” je ghaH jatlhtaH, “jIH ta'laHbe', vaD 'oH ghaH sealed:”",
        12: "je the paq ghaH toDta' Daq wa' 'Iv ghaH ghobe' educated, ja'ta', “Read vam, please;” je ghaH jatlhtaH, “jIH ta'laHbe' read.”",
        13: "The joH ja'ta', “Because vam ghotpu draws Sum tlhej chaj nujDu' je tlhej chaj wuSDu' Daq quv jIH, 'ach chaH ghaj teqta' chaj tIq Hop vo' jIH, je chaj taHvIp vo' jIH ghaH a ra'ta'ghach mu' vo' loDpu' nuq ghajtaH taH taught;",
        14: "vaj, yIlegh, jIH DichDaq proceed Daq ta' a marvelous vum among vam ghotpu, 'ach a marvelous vum je a wonder; je the valtaHghach vo' chaj val loDpu' DichDaq chIlqu', je the yajtaHghach vo' chaj prudent loDpu' DichDaq taH hidden.”",
        15: "Woe Daq chaH 'Iv deeply So' chaj qeS vo' joH'a', je 'Iv vum 'oH Daq the dark, je 'Iv jatlh, “'Iv sees maH?” je “'Iv SovtaH maH?”",
        16: "SoH tlhe' Dochmey upside bIng! Should the potter taH thought Daq taH rur clay; vetlh the Doch chenmoHta' should jatlh about ghaH 'Iv chenmoHta' 'oH, “ghaH ta'be' chenmoH jIH;” joq the Doch formed jatlh vo' ghaH 'Iv formed 'oH, “ghaH ghajtaH ghobe' yajtaHghach?”",
        17: "'oHbe' 'oH yet a very mach qaStaHvIS, je Lebanon DichDaq taH tlhe'ta' Daq a fruitful yotlh, je the fruitful yotlh DichDaq taH regarded as a forest?",
        18: "Daq vetlh jaj, the deaf DichDaq Qoy the mu'mey vo' the paq, je the mInDu' vo' the blind DichDaq legh pa' vo' obscurity je pa' vo' HurghtaHghach.",
        19: "The humble je DichDaq increase chaj Quch Daq joH'a', je the mIpHa' among loDpu' DichDaq yItIv Daq the le' wa' vo' Israel.",
        21: "vaD the ruthless ghaH qempu' Daq pagh, je the scoffer ceases, je Hoch chaH 'Iv 'oH alert Daq ta' mIghtaHghach 'oH pe' litHa'— 'Iv cause a person Daq taH indicted Sum a mu', je lay a tojta'ghach vaD the arbiter Daq the lojmIt, je 'Iv deprive the innocent vo' ruv tlhej false testimony.",
        22: "vaj thus jatlhtaH joH'a', 'Iv toDta' Abraham, concerning the tuq vo' Jacob: “Jacob DIchDaq ghobe' longer taH tuH, ghobe' DIchDaq Daj qab grow pale.",
        23: "'ach ghorgh ghaH sees Daj puqpu', the vum vo' wIj ghopmey, Daq the midst vo' ghaH, chaH DichDaq sanctify wIj pong. HIja', chaH DichDaq sanctify the le' wa' vo' Jacob, je DichDaq Qam Daq awe vo' the joH'a' vo' Israel.",
        24: "chaH je 'Iv err Daq qa' DichDaq ghoS Daq yajtaHghach, je chaH 'Iv grumble DichDaq Hev instruction.”",
    },
    30: {
        1: "“Woe Daq the lotlhqu' puqpu',” jatlhtaH joH'a', “'Iv tlhap qeS, 'ach ghobe' vo' jIH; je 'Iv chenmoH an alliance, 'ach ghobe' tlhej wIj qa', vetlh chaH may chel yem Daq yem,",
        2: "'Iv cher pa' Daq jaH bIng Daq Egypt, je ghaj ghobe' tlhobta' wIj advice; Daq strengthen themselves Daq the HoS vo' Pharaoh, je Daq tlhap lulIgh Daq the QIb vo' Egypt!",
        3: "vaj the HoS vo' Pharaoh DichDaq taH lIj tuH, je the lulIgh Daq the QIb vo' Egypt lIj confusion.",
        4: "vaD chaj joHHom 'oH Daq Zoan, je chaj ambassadors ghaj ghoS Daq Hanes.",
        5: "chaH DIchDaq Hoch taH tuH because vo' a ghotpu vetlh ta'laHbe' profit chaH, vetlh 'oH ghobe' a QaH ghobe' profit, 'ach a tuH, je je a reproach.”",
        6: "The burden vo' the Ha'DIbaH vo' the pemHov poS. vegh the puH vo' Seng je anguish, vo' the lioness je the HaDI'baH, the viper je fiery flying lung, chaH carry chaj riches Daq the shoulders vo' Qup donkeys, je chaj treasures Daq the humps vo' camels, Daq an unprofitable ghotpu.",
        7: "vaD Egypt helps Daq lI'be', je Daq ghobe' purpose; vaj ghaj jIH ja' Daj Rahab 'Iv sits vIHHa'.",
        8: "DaH jaH, write 'oH qaSpa' chaH Daq a tablet, je inscribe 'oH Daq a paq, vetlh 'oH may taH vaD the poH Daq ghoS reH je ever.",
        9: "vaD 'oH ghaH a lotlhqu' ghotpu, lying puqpu', puqpu' 'Iv DichDaq ghobe' Qoy the chut vo' joH'a';",
        10: "'Iv ja' the seers, “yImev legh!” je Daq the leghwI'pu', “yImev prophesy Daq maH nIH Dochmey. ja' maH bel Dochmey. Prophesy deceits.",
        11: "tlhap pa' vo' the way. tlhe' aside vo' the path. Cause the le' wa' vo' Israel Daq mev vo' qaSpa' maH.”",
        12: "vaj thus jatlhtaH the le' wa' vo' Israel, “Because SoH despise vam mu', je voq Daq oppression je perverseness, je rely Daq 'oH;",
        13: "vaj vam He'taHghach DIchDaq taH Daq SoH rur a breach ready Daq pum, swelling pa' Daq a jen reD, 'Iv breaking choltaH suddenly Daq an instant.",
        14: "ghaH DichDaq ghor 'oH as a potter's vessel ghaH ghorta', breaking 'oH Daq pieces Hutlh sparing, vaj vetlh pa' won't taH tu'ta' among the ghorta' piece a piece QaQ yap Daq tlhap qul vo' the hearth, joq Daq dip Dung bIQ pa' vo' the cistern.”",
        15: "vaD thus ja'ta' the joH joH'a', the le' wa' vo' Israel, “SoH DichDaq taH toDpu' Daq returning je leS. lIj HoS DichDaq taH Daq quietness je Daq confidence.” SoH refused,",
        16: "'ach SoH ja'ta', “ghobe', vaD maH DichDaq Haw' Daq horses;” vaj SoH DichDaq Haw'; je, “maH DichDaq ride Daq the swift;” vaj chaH 'Iv pursue SoH DichDaq taH swift.",
        17: "wa' SaD DichDaq Haw' Daq the threat vo' wa'. Daq the threat vo' vagh, SoH DichDaq Haw' until SoH 'oH poS rur a beacon Daq the top vo' a HuD, je rur a banner Daq a HuD.",
        18: "vaj joH'a' DichDaq loS, vetlh ghaH may taH gracious Daq SoH; je vaj ghaH DichDaq taH exalted, vetlh ghaH may ghaj pung Daq SoH, vaD joH'a' ghaH a joH'a' vo' ruv. ghurtaH 'oH Hoch chaH 'Iv loS vaD ghaH.",
        19: "vaD the ghotpu DichDaq yIn Daq Zion Daq Jerusalem. SoH DichDaq weep ghobe' latlh. ghaH DichDaq DIch taH gracious Daq SoH Daq the ghogh vo' lIj SaQ. ghorgh ghaH hears SoH, ghaH DichDaq jang SoH.",
        20: "'a' the joH may nob SoH the tIr Soj vo' adversity je the bIQ vo' affliction, yet lIj teachers won't taH hidden anymore, 'ach lIj mInDu' DichDaq legh lIj teachers;",
        21: "je ghorgh SoH tlhe' Daq the nIH ghop, je ghorgh SoH tlhe' Daq the poS, lIj qoghDu' DichDaq Qoy a ghogh behind SoH, ja'ta', “vam ghaH the way. yIt Daq 'oH.”",
        22: "SoH DIchDaq defile the overlaying vo' lIj engraved images vo' baS chIS, je the plating vo' lIj molten images vo' SuD baS. SoH DIchDaq chuH chaH DoH as an Say'Ha' Doch. SoH DIchDaq ja' 'oH, “jaH DoH!”",
        23: "ghaH DichDaq nob the rain vaD lIj tIr, tlhej nuq SoH DichDaq sow the yav; je tIr Soj vo' the increase vo' the yav DichDaq taH rich je plentiful. Daq vetlh jaj, lIj livestock DichDaq feed Daq large tI yotlh.",
        24: 'The chemvaH likewise je the Qup donkeys vetlh till the yav DichDaq Sop savory provender, nuq ghajtaH taH winnowed tlhej the shovel je tlhej the fork.',
        25: "pa' DIchDaq taH brooks je streams vo' bIQ Daq Hoch lofty HuD je Daq Hoch jen HuD Daq the jaj vo' the Dun HoHqu', ghorgh the towers pum.",
        26: "Moreover the wov vo' the maS DichDaq taH rur the wov vo' the pemHov, je the wov vo' the pemHov DichDaq taH Soch poHmey brighter, rur the wov vo' Soch jajmey, Daq the jaj vetlh joH'a' binds Dung the fracture vo' Daj ghotpu, je heals the wound chaH were struck tlhej.",
        27: "yIlegh, the pong vo' joH'a' choltaH vo' Hop DoH, burning tlhej Daj QeH, je Daq thick rising tlhIch. Daj wuSDu' 'oH teblu'ta' vo' indignation, je Daj jat ghaH as a devouring qul.",
        28: "Daj breath ghaH as an overflowing stream vetlh reaches 'ach Daq the neck, Daq sift the tuqpu' tlhej the sieve vo' QIH; je a bridle vetlh Dev Daq ruin DichDaq taH Daq the jaws vo' the ghotpu'.",
        29: "SoH DichDaq ghaj a bom, as Daq the ram ghorgh a le' 'uQ'a' ghaH polta'; je Quchqu'taHghach vo' tIq, as ghorgh wa' goes tlhej a flute Daq ghoS Daq joH'a' HuD, Daq Israel's nagh.",
        30: "joH'a' DichDaq cause Daj glorious ghogh Daq taH Qoyta', je DichDaq cha' the descent vo' Daj arm, tlhej the indignation vo' Daj QeH, je the flame vo' a devouring qul, tlhej a blast, storm, je hailstones.",
        31: "vaD vegh the ghogh vo' joH'a' the Assyrian DichDaq taH dismayed. ghaH DichDaq mup ghaH tlhej Daj DevwI' naQ.",
        32: "Hoch stroke vo' the DevwI' naQ vo' punishment, nuq joH'a' DichDaq lay Daq ghaH, DichDaq taH tlhej the wab vo' tambourines je harps. ghaH DichDaq Suv tlhej chaH Daq battles, brandishing weapons.",
        33: "vaD Daj burning Daq ghajtaH tIq taH ready. HIja', vaD the joH 'oH ghaH chenmoHta' ready. ghaH ghajtaH chenmoHta' its pyre deep je large tlhej qul je 'ar wood. joH'a' breath, rur a stream vo' sulfur, kindles 'oH.",
    },
    31: {
        1: "Woe Daq chaH 'Iv jaH bIng Daq Egypt vaD QaH, je rely Daq horses, je voq Daq Dujmey because chaH 'oH law', je Daq horsemen because chaH 'oH very HoS, 'ach chaH yImev legh Daq the le' wa' vo' Israel, je chaH yImev nej joH'a'!",
        2: "Yet ghaH je ghaH val, je DichDaq qem disaster, je DichDaq ghobe' ja' DoH Daj mu'mey, 'ach DichDaq Hu' Daq the tuq vo' the evildoers, je Daq the QaH vo' chaH 'Iv vum He'taHghach.",
        3: "DaH the Egyptians 'oH loDpu', je ghobe' joH'a'; je chaj horses ghab, je ghobe' qa'. ghorgh joH'a' stretches pa' Daj ghop, both ghaH 'Iv helps DIchDaq stumble, je ghaH 'Iv ghaH helped DIchDaq pum, je chaH Hoch DIchDaq taH Soppu' tay'.",
        4: "vaD thus jatlhtaH joH'a' Daq jIH, “As the HaDI'baH je the Qup HaDI'baH growling Dung Daj prey, chugh a qevmey vo' shepherds ghaH ja' tay' Daq ghaH, DichDaq ghobe' taH dismayed Daq chaj ghogh, ghobe' abase himself vaD the noise vo' chaH, vaj joH'a' vo' Armies DichDaq ghoS bIng Daq Suv Daq Mount Zion je Daq its heights.",
        5: "As toQmey hovering, vaj joH'a' vo' Armies DichDaq protect Jerusalem. ghaH DichDaq protect je toD 'oH. ghaH DichDaq juS Dung je pol 'oH.”",
        6: "chegh Daq ghaH vo' 'Iv SoH ghaj deeply revolted, puqpu' vo' Israel.",
        7: "vaD Daq vetlh jaj Hoch DIchDaq chuH DoH Daj idols vo' baS chIS je Daj idols vo' SuD baS— yem nuq lIj ghaj ghopmey ghaj chenmoHta' vaD SoH.",
        8: "“The Assyrian DichDaq pum Sum the 'etlh, ghobe' vo' loD; je the 'etlh, ghobe' vo' mankind, DIchDaq Sop ghaH. ghaH DichDaq Haw' vo' the 'etlh, je Daj Qup loDpu' DichDaq moj subject Daq forced labor.",
        9: "Daj nagh DichDaq juS DoH Sum meq vo' ghIjvIptaH, je Daj joHHom DichDaq taH vIp vo' the banner,” jatlhtaH joH'a', 'Iv qul ghaH Daq Zion, je Daj furnace Daq Jerusalem.",
    },
    32: {
        1: "yIlegh, a joH DIchDaq che' Daq QaQtaHghach, je joHHom DIchDaq rule Daq ruv.",
        2: "A loD DIchDaq taH as a hiding Daq vo' the SuS, je a covert vo' the storm, as streams vo' bIQ Daq a dry Daq, as the shade vo' a large nagh Daq a Doy' puH.",
        3: "The mInDu' vo' chaH 'Iv legh DichDaq ghobe' taH dim, je the qoghDu' vo' chaH 'Iv Qoy DichDaq 'Ij.",
        4: "The tIq vo' the rash DichDaq understand Sov, je the jat vo' the stammerers DichDaq taH ready Daq jatlh plainly.",
        5: "The fool DichDaq ghobe' longer taH ja' noble, ghobe' the scoundrel taH highly respected.",
        6: "vaD the fool DichDaq jatlh folly, je Daj tIq DichDaq vum He'taHghach, Daq practice profanity, je Daq utter error Daq joH'a', Daq chenmoH empty the qa' vo' the hungry, je Daq cause the tlhutlh vo' the thirsty Daq fail.",
        7: "The Hemey vo' the scoundrel 'oH mIghtaHghach. ghaH devises mIgh devices Daq Qaw' the humble tlhej lying mu'mey, 'ach ghorgh the needy speaks nIH.",
        8: "'ach the noble devises noble Dochmey; je ghaH DichDaq continue Daq noble Dochmey.",
        9: "Hu' Dung, SoH be'pu' 'Iv 'oH Daq leSchu'! Qoy wIj ghogh! SoH careless puqbe'pu', nob qogh Daq wIj speech!",
        10: "vaD jajmey beyond a DIS SoH DichDaq taH troubled, SoH careless be'pu'; vaD the vintage DIchDaq fail. The harvest won't ghoS.",
        11: "Tremble, SoH be'pu' 'Iv 'oH Daq leSchu'! taH troubled, SoH careless ones! Strip tlhIH'egh, chenmoH tlhIH'egh naked, je lan sackcloth Daq lIj waist.",
        12: 'qIp lIj breasts vaD the bel fields, vaD the fruitful vine.',
        13: "Thorns je briars DichDaq ghoS Dung Daq wIj people's puH; HIja', Daq Hoch the juHmey vo' Quch Daq the joyous veng.",
        14: "vaD the palace DichDaq taH lonta'. The populous veng DichDaq taH deserted. The HuD je the watchtower DichDaq taH vaD dens reH, a tIv vaD wild donkeys, a tI yotlh vo' flocks;",
        15: "Until the qa' ghaH poured Daq maH vo' Daq jen, je the ngem becomes a fruitful yotlh, je the fruitful yotlh ghaH considered a forest.",
        16: 'vaj ruv DichDaq yIn Daq the ngem; je QaQtaHghach DichDaq remain Daq the fruitful yotlh.',
        17: "The vum vo' QaQtaHghach DichDaq taH roj; je the effect vo' QaQtaHghach, quietness je confidence reH.",
        18: 'wIj ghotpu DichDaq abide Daq a peaceful juH, Daq safe dwellings, je Daq quiet resting Daqmey.',
        19: "'a' hail flattens the forest, je the veng ghaH leveled completely.",
        20: "ghurtaH 'oH SoH 'Iv sow retlh Hoch bIQmey, 'Iv ngeH pa' the qamDu' vo' the Qa' je the SarghHom.",
    },
    33: {
        1: "Woe Daq SoH 'Iv Qaw', 'ach SoH weren't Qaw'ta'; je 'Iv magh, 'ach nobody maghta' SoH! ghorgh SoH ghaj finished destroying, SoH DichDaq taH Qaw'ta'; je ghorgh SoH ghaj chenmoHta' an pItlh vo' betrayal, SoH DichDaq taH maghta'.",
        2: "joH'a', taH gracious Daq maH. maH ghaj waited vaD SoH. taH maj HoS Hoch po, maj toDtaHghach je Daq the poH vo' Seng.",
        3: "Daq the noise vo' the thunder, the ghotpu' ghaj Haw'ta'. ghorgh SoH lift SoH'egh Dung, the tuqpu' 'oH scattered.",
        4: "lIj non DichDaq taH boSta' as the caterpillar gathers. loDpu' DichDaq leap Daq 'oH as locusts leap.",
        5: "joH'a' ghaH exalted, vaD ghaH yIntaH Daq jen. ghaH ghajtaH tebta' Zion tlhej ruv je QaQtaHghach.",
        6: "pa' DichDaq taH stability Daq lIj poHmey, abundance vo' toDtaHghach, valtaHghach, je Sov. The taHvIp vo' joH'a' ghaH lIj treasure.",
        7: "yIlegh, chaj valiant ones SaQ outside; the ambassadors vo' roj weep bitterly.",
        8: "The highways 'oH moB. The traveling loD ceases. The lay' ghaH ghorta'. ghaH ghajtaH muSqu' the vengmey. ghaH ta'be' respect loD.",
        9: "The puH mourns je languishes. Lebanon ghaH mISmoHpu' je withers DoH. Sharon ghaH rur a desert, je Bashan je Carmel 'oH stripped bare.",
        10: "“DaH jIH DichDaq Hu',” jatlhtaH joH'a'; “DaH jIH DichDaq lift jIH'egh Dung. DaH jIH DichDaq taH exalted.",
        11: "SoH DichDaq conceive yub. SoH DichDaq qem vo' stubble. lIj breath ghaH a qul vetlh DichDaq Sop SoH.",
        12: "The ghotpu' DichDaq taH rur the burning vo' lime, rur thorns vetlh 'oH pe' bIng je meQpu' Daq the qul.",
        13: "Qoy, SoH 'Iv 'oH Hop litHa', nuq jIH ghaj ta'pu'; je, SoH 'Iv 'oH Sum, acknowledge wIj might.”",
        14: "The yemwI'pu' Daq Zion 'oH vIp. Trembling ghajtaH seized the godless ones. 'Iv among maH laH yIn tlhej the devouring qul? 'Iv among maH laH yIn tlhej everlasting burning?",
        15: "ghaH 'Iv yIttaH righteously, je speaks blamelessly; ghaH 'Iv despises the gain vo' oppressions, 'Iv gestures tlhej Daj ghopmey, refusing Daq tlhap a bribe, 'Iv stops Daj qoghDu' vo' hearing vo' 'Iw, je shuts Daj mInDu' vo' leghtaH Daq mIghtaHghach—",
        16: "ghaH DichDaq yIn Daq jen. Daj Daq vo' defense DichDaq taH the yoDjuH'a' vo' rocks. Daj tIr Soj DichDaq taH supplied. Daj bIQmey DichDaq taH sure.",
        17: "lIj mInDu' DichDaq legh the joH Daq Daj 'IhtaHghach. chaH DichDaq legh a distant puH.",
        18: "lIj tIq DichDaq ja''eghqa' Daq the ghIjvIptaH. nuqDaq ghaH ghaH 'Iv counted? nuqDaq ghaH ghaH 'Iv weighed? nuqDaq ghaH ghaH 'Iv counted the towers?",
        19: "SoH DichDaq ghobe' longer legh the fierce ghotpu, a ghotpu vo' a deep speech vetlh SoH ta'laHbe' comprehend, tlhej a strange language vetlh SoH ta'laHbe' understand.",
        20: "legh Daq Zion, the veng vo' maj wIv festivals. lIj mInDu' DichDaq legh Jerusalem, a quiet juH, a juHHom vetlh won't taH teqta'. Its stakes DichDaq never taH plucked Dung, ghobe' DichDaq vay' vo' its cords taH ghorta'.",
        21: "'ach pa' joH'a' DichDaq taH tlhej maH Daq majesty, a Daq vo' broad rivers je streams, Daq nuq ghobe' galley tlhej oars DichDaq jaH, ghobe' DichDaq vay' gallant Duj juS Sum pa'.",
        22: "vaD joH'a' ghaH maj noH. joH'a' ghaH maj lawgiver. joH'a' ghaH maj joH. ghaH DichDaq toD maH.",
        23: "lIj rigging ghaH untied. chaH couldn't strengthen the qam vo' chaj mast. chaH couldn't ngeH the sail. vaj the prey vo' a Dun non ghaHta' divided. The lame tlhapta' the prey.",
        24: "The inhabitant won't jatlh, “jIH 'oH rop.” The ghotpu 'Iv yIn therein DichDaq taH forgiven chaj He'taHghach.",
    },
    34: {
        1: "ghoS Sum, SoH tuqpu', Daq Qoy! 'Ij, SoH ghotpu'. chaw' the tera' je Hoch 'oH contains Qoy; the qo', je everything vetlh choltaH vo' 'oH.",
        2: "vaD joH'a' ghaH enraged Daq Hoch the tuqpu', je angry tlhej Hoch chaj armies. ghaH ghajtaH utterly Qaw'ta' chaH. ghaH ghajtaH nobpu' chaH Dung vaD HoHqu'.",
        3: "chaj Heghta' DichDaq je taH chuH pa', je the stench vo' chaj Heghpu' porghmey DichDaq ghoS Dung; je the Hudmey DichDaq melt Daq chaj 'Iw.",
        4: "Hoch vo' the army vo' the sky DichDaq taH dissolved. The sky DichDaq taH rolled Dung rur a scroll, je Hoch its armies DichDaq fade DoH, as a Sornav ngabtaH vo' litHa' a vine joq a fig Sor.",
        5: "vaD wIj 'etlh ghajtaH drunk its fill Daq the sky. yIlegh, 'oH DichDaq ghoS bIng Daq Edom, je Daq the ghotpu vo' wIj mu'qaD, vaD yoj.",
        6: "joH'a' 'etlh ghaH tebta' tlhej 'Iw. 'oH ghaH covered tlhej ror, tlhej the 'Iw vo' 'erHommey je goats, tlhej the ror vo' the kidneys vo' 'ermey; vaD joH'a' ghajtaH a sacrifice Daq Bozrah, je a Dun HoHqu' Daq the puH vo' Edom.",
        7: "The wild chemvaH DichDaq ghoS bIng tlhej chaH, je the Qup Qa'mey tlhej the HoS Qa'mey; je chaj puH DichDaq taH drunken tlhej 'Iw, je chaj dust chenmoHta' greasy tlhej ror.",
        8: "vaD joH'a' ghajtaH a jaj vo' vengeance, a DIS vo' recompense vaD the cause vo' Zion.",
        9: "Its streams DichDaq taH tlhe'ta' Daq pitch, its dust Daq sulfur, je its puH DichDaq moj burning pitch.",
        10: "'oH won't taH quenched ram ghobe' jaj. Its tlhIch DichDaq jaH Dung reH. vo' generation Daq generation, 'oH DichDaq Qot waste. ghobe' wa' DichDaq juS vegh 'oH reH je ever.",
        11: "'ach the pelican je the porcupine DichDaq ghaj 'oH. The owl je the raven DichDaq yIn Daq 'oH. ghaH DichDaq stretch the tlhegh vo' confusion Dung 'oH, je the plumb tlhegh vo' emptiness.",
        12: "chaH DIchDaq ja' its nobles Daq the kingdom, 'ach pagh DIchDaq taH pa'; je Hoch its joHHom DIchDaq taH pagh.",
        13: "Thorns DichDaq ghoS Dung Daq its palaces, nettles je thistles Daq its fortresses; je 'oH DichDaq taH a juH vo' jackals, a bo'DIj vaD ostriches.",
        14: "The wild Ha'DIbaH vo' the desert DichDaq ghom tlhej the wolves, je the wild goat DichDaq SaQ Daq Daj fellow. HIja', the ram creature { Note: literally, lilith, nuq laH je taH a ram demon joq ram monster } DIchDaq settle pa', je DIchDaq tu' herself a Daq vo' leS.",
        15: "The puv DuQwI' snake DichDaq chenmoH Daj nest pa', je lay, hatch, je tay'moH bIng Daj shade. HIja', the kites DichDaq taH boSta' pa', Hoch wa' tlhej Daj mate.",
        16: "Search Daq the paq vo' joH'a', je read: ghobe' wa' vo' Dochvammey DichDaq taH missing. pagh DichDaq Hutlh Daj mate. vaD wIj nujDu' ghajtaH ra'ta', je Daj qa' ghajtaH boSta' chaH.",
        17: "ghaH ghajtaH chuH the lot vaD chaH, je Daj ghop ghajtaH divided 'oH Daq chaH tlhej a measuring tlhegh. chaH DIchDaq ghaj 'oH reH. vo' generation Daq generation chaH DichDaq yIn Daq 'oH.",
    },
    35: {
        1: "The ngem je the dry puH DichDaq taH Quchqu'. The desert DichDaq yItIv je blossom rur a rose.",
        2: "'oH DichDaq blossom abundantly, je yItIv 'ach tlhej Quch je bomtaH. Lebanon's batlh Lebanon DichDaq taH nobpu' Daq 'oH, the excellence vo' Carmel je Sharon. chaH DichDaq legh joH'a' batlh, the excellence vo' maj joH'a'.",
        3: 'Strengthen the weak ghopmey, je chenmoH firm the feeble knees.',
        4: "ja' chaH 'Iv ghaj a fearful tIq, “taH HoS. yImev taH vIp. yIlegh, lIj joH'a' DichDaq ghoS tlhej vengeance, joH'a' retribution. ghaH DichDaq ghoS je toD SoH.",
        5: "vaj the mInDu' vo' the blind DichDaq taH poSmaHpu', je the qoghDu' vo' the deaf DichDaq taH unstopped.",
        6: "vaj the lame loD DichDaq leap rur a deer, je the jat vo' the mute DichDaq bom; vaD bIQmey DichDaq ghor pa' Daq the ngem, je streams Daq the desert.",
        7: "The burning sand DichDaq moj a pool, je the thirsty yav springs vo' bIQ. Grass tlhej reeds je rushes DichDaq taH Daq the juH vo' jackals, nuqDaq chaH lay.",
        8: "A highway DichDaq taH pa', a road, je 'oH DichDaq taH ja' The le' Way. The Say'Ha' DIchDaq ghobe' juS Dung 'oH, 'ach 'oH DichDaq taH vaD chaH 'Iv yIt Daq the Way. mIgh fools DichDaq ghobe' jaH pa'.",
        9: "ghobe' HaDI'baH DichDaq taH pa', ghobe' DichDaq vay' ravenous animal jaH Dung Daq 'oH. chaH DichDaq ghobe' taH tu'ta' pa'; 'ach the toDta' DichDaq yIt pa'.",
        10: "The joH'a' ransomed ones DichDaq chegh, je ghoS tlhej bomtaH Daq Zion; je everlasting Quch DichDaq taH Daq chaj nachDu'. chaH DichDaq obtain Quchqu'taHghach je Quch, je QoSqu' je sighing DichDaq Haw' DoH.”",
    },
    36: {
        1: "DaH 'oH qaSta' Daq the fourteenth DIS vo' joH Hezekiah, vetlh Sennacherib joH vo' Assyria attacked Hoch vo' the fortified vengmey vo' Judah, je captured chaH.",
        2: "The joH vo' Assyria ngeHta' Rabshakeh vo' Lachish Daq Jerusalem Daq joH Hezekiah tlhej a large army. ghaH Qampu' Sum the aqueduct vo' the upper pool Daq the fuller's yotlh highway.",
        3: "vaj Eliakim the puqloD vo' Hilkiah, 'Iv ghaHta' Dung the household, je Shebna the scribe, je Joah, the puqloD vo' Asaph, the recorder ghoSta' pa' Daq ghaH.",
        4: "Rabshakeh ja'ta' Daq chaH, “DaH ja' Hezekiah, ‘Thus jatlhtaH the Dun joH, the joH vo' Assyria, “nuq confidence ghaH vam Daq nuq SoH voq?",
        5: "jIH jatlh vetlh lIj qeS je HoS vaD the veS 'oH neH lI'be' mu'mey. DaH Daq 'Iv ta' SoH voq, vetlh SoH ghaj lotlhpu' Daq jIH?",
        6: "yIlegh, SoH voq Daq the naQ vo' vam bruised reed, 'ach Daq Egypt, nuq chugh a loD leans Daq 'oH, 'oH DichDaq jaH Daq Daj ghop je pierce 'oH. vaj ghaH Pharaoh joH vo' Egypt Daq Hoch 'Iv voq Daq ghaH.",
        7: "'ach chugh SoH ja' jIH, ‘maH voq Daq joH'a' maj joH'a',' 'oHbe' vetlh ghaH 'Iv jen Daqmey je 'Iv altars Hezekiah ghajtaH tlhappu' DoH, je ghajtaH ja'ta' Daq Judah je Daq Jerusalem, ‘SoH DIchDaq lalDan toy' qaSpa' vam lalDanta' Daq?'”",
        8: "DaH vaj, please chenmoH a pledge Daq wIj pIn the joH vo' Assyria, je jIH DichDaq nob SoH cha' SaD horses, chugh SoH 'oH laH Daq lIj part Daq cher riders Daq chaH.",
        9: "chay' vaj laH SoH tlhe' DoH the qab vo' wa' HoD vo' the least vo' wIj master's toy'wI'pu', je lan lIj voq Daq Egypt vaD Dujmey je vaD horsemen?",
        10: "ghaj jIH ghoS Dung DaH Hutlh joH'a' Daq vam puH Daq Qaw' 'oH? joH'a' ja'ta' Daq jIH, “jaH Dung Daq vam puH, je Qaw' 'oH.”'”",
        11: "vaj Eliakim, Shebna je Joah ja'ta' Daq Rabshakeh, “Please jatlh Daq lIj toy'wI'pu' Daq Aramaic, vaD maH understand 'oH; je yImev jatlh Daq maH Daq the Jews' language Daq the hearing vo' the ghotpu 'Iv 'oH Daq the reD.”",
        12: "'ach Rabshakeh ja'ta', “ghajtaH wIj pIn ngeHta' jIH neH Daq lIj pIn je Daq SoH, Daq jatlh Dochvammey mu'mey, je ghobe' Daq the loDpu' 'Iv ba' Daq the reD, 'Iv DichDaq Sop chaj ghaj dung je tlhutlh chaj ghaj urine tlhej SoH?”",
        13: "vaj Rabshakeh Qampu', je ja' pa' tlhej a loud ghogh Daq the Jews' language, je ja'ta', “Qoy the mu'mey vo' the Dun joH, the joH vo' Assyria!",
        14: "Thus jatlhtaH the joH, ‘yImev chaw' Hezekiah deceive SoH; vaD ghaH DichDaq ghobe' taH laH Daq toD SoH.",
        15: "yImev chaw' Hezekiah chenmoH SoH voq Daq joH'a', ja'ta', “joH'a' DichDaq DIch toD maH. vam veng won't taH nobpu' Daq the ghop vo' the joH vo' Assyria.”'",
        16: "yImev 'Ij Daq Hezekiah, vaD thus jatlhtaH the joH vo' Assyria, ‘chenmoH lIj roj tlhej jIH, je ghoS pa' Daq jIH; je each vo' SoH Sop vo' Daj vine, je each wa' vo' Daj fig Sor, je each wa' vo' SoH tlhutlh the bIQmey vo' Daj ghaj cistern;",
        17: "until jIH ghoS je tlhap SoH DoH Daq a puH rur lIj ghaj puH, a puH vo' grain je chu' HIq, a puH vo' tIr Soj je vineyards.",
        18: "Beware lest Hezekiah persuade SoH, ja'ta', “joH'a' DichDaq toD maH.” ghaj vay' vo' the Qunpu' vo' the tuqpu' toDta' chaj puHmey vo' the ghop vo' the joH vo' Assyria?",
        19: "nuqDaq 'oH the Qunpu' vo' Hamath je Arpad? nuqDaq 'oH the Qunpu' vo' Sepharvaim? ghaj chaH toDta' Samaria vo' wIj ghop?",
        20: "'Iv 'oH chaH among Hoch the Qunpu' vo' Dochvammey countries vetlh ghaj toDta' chaj Hatlh pa' vo' wIj ghop, vetlh joH'a' should toD Jerusalem pa' vo' wIj ghop?'”",
        21: "'ach chaH remained tam, je ja'ta' pagh Daq reply, vaD the joH ra'ta'ghach mu' ghaHta', “yImev jang ghaH.”",
        22: "vaj Eliakim the puqloD vo' Hilkiah, 'Iv ghaHta' Dung the household, je Shebna the scribe, je Joah, the puqloD vo' Asaph, the recorder, ghoSta' Daq Hezekiah tlhej chaj clothes torn, je ja'ta' ghaH the mu'mey vo' Rabshakeh.",
    },
    37: {
        1: "'oH qaSta', ghorgh joH Hezekiah Qoyta' 'oH, vetlh ghaH tore Daj clothes, covered himself tlhej sackcloth, je mejta' Daq joH'a' tuq.",
        2: "ghaH ngeHta' Eliakim, 'Iv ghaHta' Dung the household, je Shebna the scribe, je the quppu' vo' the lalDan vumwI'pu', covered tlhej sackcloth, Daq Isaiah the leghwI'pu', the puqloD vo' Amoz.",
        3: "chaH ja'ta' Daq ghaH, “Thus jatlhtaH Hezekiah, ‘vam jaj ghaH a jaj vo' Seng, je vo' rebuke, je vo' rejection; vaD the puqpu' ghaj ghoS Daq the birth, je pa' ghaH ghobe' HoS Daq qem vo'.",
        4: "'oH may taH joH'a' lIj joH'a' DichDaq Qoy the mu'mey vo' Rabshakeh, 'Iv the joH vo' Assyria Daj pIn ghajtaH ngeHta' Daq defy the yIntaH joH'a', je DichDaq rebuke the mu'mey nuq joH'a' lIj joH'a' ghajtaH Qoyta'. vaj lift Dung lIj tlhobtaHghach vaD the chuv vetlh ghaH poS.'”",
        5: "vaj the toy'wI'pu' vo' joH Hezekiah ghoSta' Daq Isaiah.",
        6: "Isaiah ja'ta' Daq chaH, “ja' lIj pIn, ‘Thus jatlhtaH joH'a', “yImev taH vIp vo' the mu'mey vetlh SoH ghaj Qoyta', tlhej nuq the toy'wI'pu' vo' the joH vo' Assyria ghaj blasphemed jIH.",
        7: "yIlegh, jIH DichDaq lan a qa' Daq ghaH je ghaH DichDaq Qoy news, je DichDaq chegh Daq Daj ghaj puH. jIH DichDaq cause ghaH Daq pum Sum the 'etlh Daq Daj ghaj puH.”'”",
        8: "vaj Rabshakeh cheghta', je tu'ta' the joH vo' Assyria warring Daq Libnah, vaD ghaH ghajta' Qoyta' vetlh ghaH ghaHta' departed vo' Lachish.",
        9: "ghaH Qoyta' news concerning Tirhakah joH vo' Ethiopia, “ghaH ghajtaH ghoS pa' Daq Suv Daq SoH.” ghorgh ghaH Qoyta' 'oH, ghaH ngeHta' Duypu' Daq Hezekiah, ja'ta',",
        10: "“Thus SoH DIchDaq jatlh Daq Hezekiah joH vo' Judah, ja'ta', ‘yImev chaw' lIj joH'a' Daq 'Iv SoH voq deceive SoH, ja'ta', “Jerusalem won't taH nobpu' Daq the ghop vo' the joH vo' Assyria.”",
        11: "yIlegh, SoH ghaj Qoyta' nuq the joHpu' vo' Assyria ghaj ta'pu' Daq Hoch puHmey, Sum destroying chaH utterly. DIchDaq SoH taH toDta'?",
        12: "ghaj the Qunpu' vo' the tuqpu' toDta' chaH, nuq wIj vavpu' ghaj Qaw'ta', Gozan, Haran, Rezeph, je the puqpu' vo' Eden 'Iv were Daq Telassar?",
        13: "nuqDaq ghaH the joH vo' Hamath, je the joH vo' Arpad, je the joH vo' the veng vo' Sepharvaim, vo' Hena, je Ivvah?'”",
        14: "Hezekiah Hevta' the letter vo' the ghop vo' the Duypu' je read 'oH. vaj Hezekiah mejta' Dung Daq joH'a' tuq, je ngeH 'oH qaSpa' joH'a'.",
        15: "Hezekiah prayed Daq joH'a', ja'ta',",
        16: "“joH'a' vo' Armies, the joH'a' vo' Israel, 'Iv ghaH enthroned among the cherubim, SoH 'oH the joH'a', 'ach SoH mob, vo' Hoch the kingdoms vo' the tera'. SoH ghaj chenmoHta' chal je tera'.",
        17: "tlhe' lIj qogh, joH'a', je Qoy. poSmoH lIj mInDu', joH'a', je yIlegh. Qoy Hoch vo' the mu'mey vo' Sennacherib, 'Iv ghajtaH ngeHta' Daq defy the yIntaH joH'a'.",
        18: "Truly, joH'a', the joHpu' vo' Assyria ghaj Qaw'ta' Hoch the countries je chaj puH,",
        19: "je ghaj chuH chaj Qunpu' Daq the qul; vaD chaH were ghobe' Qunpu', 'ach the vum vo' men's ghopmey, wood je nagh; vaj chaH ghaj Qaw'ta' chaH.",
        20: "DaH vaj, joH'a' maj joH'a', toD maH vo' Daj ghop, vetlh Hoch the kingdoms vo' the tera' may Sov vetlh SoH 'oH joH'a', 'ach SoH neH.”",
        21: "vaj Isaiah the puqloD vo' Amoz ngeHta' Daq Hezekiah, ja'ta', “Thus jatlhtaH joH'a', the joH'a' vo' Israel, ‘Because SoH ghaj prayed Daq jIH Daq Sennacherib joH vo' Assyria,",
        22: "vam ghaH the mu' nuq joH'a' ghajtaH jatlhpu' concerning ghaH. The virgin puqbe' vo' Zion ghajtaH muSqu' SoH je ridiculed SoH. The puqbe' vo' Jerusalem ghajtaH shaken Daj nach Daq SoH.",
        23: "'Iv ghaj SoH defied je blasphemed? Daq 'Iv ghaj SoH exalted lIj ghogh je qengta' Dung lIj mInDu' Daq jen? Daq the le' wa' vo' Israel.",
        24: "Sum lIj toy'wI'pu', ghaj SoH defied the joH, je ghaj ja'ta', “tlhej the qevmey vo' wIj Dujmey jIH ghaj ghoS Dung Daq the height vo' the Hudmey, Daq the innermost parts vo' Lebanon. jIH DichDaq pe' bIng its tall cedars je its choice fir Sormey. jIH DichDaq 'el Daq its farthest height, the forest vo' its fruitful yotlh.",
        25: "jIH ghaj dug je drunk bIQ, je tlhej the bem vo' wIj qamDu' jIH DichDaq dry Dung Hoch the rivers vo' Egypt.”",
        26: "ghaj SoH ghobe' Qoyta' chay' jIH ghaj ta'pu' 'oH tIq ben, je formed 'oH Daq ancient poHmey? DaH jIH ghaj qempu' 'oH Daq juS, vetlh 'oH should taH yours Daq Qaw' fortified vengmey, turning chaH Daq ruinous heaps.",
        27: "vaj chaj nganpu' ghajta' mach HoS. chaH were dismayed je mISmoHpu'. chaH were rur the grass vo' the yotlh, je rur the SuD herb, rur the grass Daq the housetops, je rur a yotlh qaSpa' its crop ghajtaH grown.",
        28: "'ach jIH Sov lIj sitting bIng, lIj ghoS pa', lIj choltaH Daq, je lIj raging Daq jIH.",
        29: "Because vo' lIj raging Daq jIH, je because lIj arrogance ghajtaH ghoS Dung Daq wIj qoghDu', vaj DichDaq jIH lan wIj hook Daq lIj nose je wIj bridle Daq lIj wuSDu', je jIH DichDaq tlhe' SoH DoH Sum the way Sum nuq SoH ghoSta'.",
        30: "vam DIchDaq taH the sign Daq SoH. SoH DichDaq Sop vam DIS vetlh nuq grows vo' itself, je Daq the cha'DIch DIS vetlh nuq springs vo' the rap; je Daq the wejDIch DIS sow je reap je plant vineyards, je Sop chaj baQ.",
        31: "The chuv vetlh ghaH escaped vo' the tuq vo' Judah DichDaq again tlhap root downward, je SIQ baQ upward.",
        32: "vaD pa' vo' Jerusalem a chuv DichDaq jaH vo', je survivors DichDaq escape vo' Mount Zion. The zeal vo' joH'a' vo' Armies DichDaq perform vam.'",
        33: "vaj thus jatlhtaH joH'a' concerning the joH vo' Assyria, ‘ghaH DichDaq ghobe' ghoS Daq vam veng, ghobe' shoot an puv DuQwI' pa', ghobe' DichDaq ghaH ghoS qaSpa' 'oH tlhej yoD, ghobe' chuH Dung a mound Daq 'oH.",
        34: "Sum the way vetlh ghaH ghoSta', Sum the rap ghaH DIchDaq chegh, je ghaH DIchDaq ghobe' ghoS Daq vam veng,' jatlhtaH joH'a'.",
        35: "‘vaD jIH DichDaq defend vam veng Daq toD 'oH, vaD wIj ghaj chIch, je vaD wIj toy'wI' David's chIch.'”",
        36: "The Duy vo' joH'a' mejta' pa' je struck wa' vatlh je eighty- vagh SaD loDpu' Daq the raQ vo' the Assyrians. ghorgh loDpu' Hu' early Daq the po, yIlegh, Dochvammey were Hoch Heghpu' porghmey.",
        37: "vaj Sennacherib joH vo' Assyria departed, mejta' DoH, cheghta' Daq Nineveh, je stayed pa'.",
        38: "'oH qaSta', as ghaH ghaHta' worshipping Daq the tuq vo' Nisroch Daj joH'a', vetlh Adrammelech je Sharezer Daj puqloDpu' struck ghaH tlhej the 'etlh; je chaH escaped Daq the puH vo' Ararat. Esar Haddon Daj puqloD che'ta' Daq Daj Daq.",
    },
    38: {
        1: "Daq chaH jajmey ghaHta' Hezekiah rop je Sum Hegh. Isaiah the leghwI'pu', the puqloD vo' Amoz, ghoSta' Daq ghaH, je ja'ta' Daq ghaH, “Thus jatlhtaH joH'a', ‘cher lIj tuq Daq order, vaD SoH DichDaq Hegh, je ghobe' yIn.'”",
        2: "vaj Hezekiah tlhe'ta' Daj qab Daq the reD je prayed Daq joH'a',",
        3: "je ja'ta', “qaw DaH, joH'a', jIH beg SoH, chay' jIH ghaj yItta' qaSpa' SoH Daq vIt je tlhej a perfect tIq, je ghaj ta'pu' vetlh nuq ghaH QaQ Daq lIj leghpu'.” Hezekiah wept bitterly.",
        4: "vaj the mu' vo' joH'a' ghoSta' Daq Isaiah, ja'ta',",
        5: "“jaH, je ja' Hezekiah, ‘Thus jatlhtaH joH'a', the joH'a' vo' David lIj vav, “jIH ghaj Qoyta' lIj tlhobtaHghach. jIH ghaj leghpu' lIj tears. yIlegh, jIH DichDaq chel fifteen DISmey Daq lIj yIn.",
        6: "jIH DichDaq toD SoH je vam veng pa' vo' the ghop vo' the joH vo' Assyria, je jIH DichDaq defend vam veng.",
        7: "vam DIchDaq taH the sign Daq SoH vo' joH'a', vetlh joH'a' DichDaq ta' vam Doch vetlh ghaH ghajtaH jatlhpu'.",
        8: "yIlegh, jIH DichDaq cause the QIb Daq the sundial, nuq ghajtaH ghoSta' bIng Daq the sundial vo' Ahaz tlhej the pemHov, Daq chegh DoH wa'maH steps. vaj the pemHov cheghta' wa'maH steps Daq the sundial Daq nuq 'oH ghajta' ghoSta' bIng.”'”",
        9: "The writing vo' Hezekiah joH vo' Judah, ghorgh ghaH ghajta' taH rop, je ghajta' recovered vo' Daj sickness.",
        10: "jIH ja'ta', “Daq the middle vo' wIj yIn jIH jaH Daq the lojmItmey vo' Sheol { Note: Sheol ghaH the Daq vo' the Heghpu'. }. jIH 'oH deprived vo' the residue vo' wIj DISmey.”",
        11: "jIH ja'ta', “jIH won't legh joH'a', joH'a' Daq the puH vo' the yIntaH. jIH DichDaq legh loD ghobe' latlh tlhej the nganpu' vo' the qo'.",
        12: "wIj dwelling ghaH teqta', je ghaH qengta' DoH vo' jIH rur a shepherd's juHHom. jIH ghaj rolled Dung, rur a weaver, wIj yIn. ghaH DichDaq pe' jIH litHa' vo' the loom. vo' jaj 'ach Daq ram SoH DichDaq chenmoH an pItlh vo' jIH.",
        13: "jIH waited patiently until po. ghaH breaks Hoch wIj HomDu' rur a HaDI'baH. vo' jaj 'ach Daq ram SoH DichDaq chenmoH an pItlh vo' jIH.",
        14: "jIH chattered rur a swallow joq a crane. jIH moaned rur a dove. wIj mInDu' weaken leghtaH upward. joH, jIH 'oH Suvta'. taH wIj security.”",
        15: "nuq DichDaq jIH jatlh? ghaH ghajtaH both jatlhpu' Daq jIH, je himself ghajtaH ta'pu' 'oH. jIH DichDaq yIt yep Hoch wIj DISmey because vo' the anguish vo' wIj qa'.",
        16: "joH, loDpu' yIn Sum Dochvammey Dochmey; je wIj qa' finds yIn Daq Hoch vo' chaH: SoH nobHa' jIH, je cause jIH Daq yIn.",
        17: "yIlegh, vaD roj jIH ghajta' Dun anguish, 'ach SoH ghaj Daq muSHa' vaD wIj qa' toDta' 'oH vo' the pit vo' corruption; vaD SoH ghaj chuH Hoch wIj yemmey behind lIj DoH.",
        18: "vaD Sheol { Note: Sheol ghaH the Daq vo' the Heghpu'. } ta'laHbe' naD SoH. Hegh ta'laHbe' celebrate SoH. chaH 'Iv jaH bIng Daq the pit ta'laHbe' tul vaD lIj vIt.",
        19: "The yIntaH, the yIntaH, ghaH DIchDaq naD SoH, as jIH ta' vam jaj. The vav DIchDaq chenmoH Sovta' lIj vIt Daq the puqpu'.",
        20: "joH'a' DichDaq toD jIH. vaj maH DichDaq bom wIj bommey tlhej stringed instruments Hoch the jajmey vo' maj yIn Daq the tuq vo' joH'a'.",
        21: "DaH Isaiah ghajta' ja'ta', “chaw' chaH tlhap a cake vo' figs, je lay 'oH vaD a poultice Daq the boil, je ghaH DIchDaq recover.”",
        22: "Hezekiah je ghajta' ja'ta', “nuq ghaH the sign vetlh jIH DichDaq jaH Dung Daq the tuq vo' joH'a'?”",
    },
    39: {
        1: "Daq vetlh poH, Merodach Baladan the puqloD vo' Baladan, joH vo' Babylon, ngeHta' letters je a present Daq Hezekiah; vaD ghaH Qoyta' vetlh ghaH ghajta' taH rop, je ghajta' recovered.",
        2: "Hezekiah ghaHta' pleased tlhej chaH, je showed chaH the tuq vo' Daj precious Dochmey, the baS chIS, je the SuD baS, the spices, je the precious Hergh, je Hoch the tuq vo' Daj armor, je Hoch vetlh ghaHta' tu'ta' Daq Daj treasures. pa' ghaHta' pagh Daq Daj tuq, ghobe' Daq Hoch Daj dominion, vetlh Hezekiah ta'be' cha' chaH.",
        3: "vaj Isaiah the leghwI'pu' ghoSta' Daq joH Hezekiah, je tlhobta' ghaH, “nuq ta'ta' Dochvammey loDpu' jatlh? nuqDaq ta'ta' chaH ghoS vo' Daq SoH?” Hezekiah ja'ta', “chaH ghaj ghoS vo' a Hatlh Hop vo' jIH, 'ach vo' Babylon.”",
        4: "vaj ghaH tlhobta', “nuq ghaj chaH leghpu' Daq lIj tuq?” Hezekiah jangta', “chaH ghaj leghpu' Hoch vetlh ghaH Daq wIj tuq. pa' ghaH pagh among wIj treasures vetlh jIH ghaj ghobe' shown chaH.”",
        5: "vaj ja'ta' Isaiah Daq Hezekiah, “Qoy the mu' vo' joH'a' vo' Armies:",
        6: "‘yIlegh, the jajmey 'oH choltaH ghorgh Hoch vetlh ghaH Daq lIj tuq, je vetlh nuq lIj vavpu' ghaj stored Dung until vam jaj, DichDaq taH qengta' Daq Babylon. pagh DichDaq taH poS,' jatlhtaH joH'a'.",
        7: "‘chaH DichDaq tlhap DoH lIj puqloDpu' 'Iv DichDaq issue vo' SoH, 'Iv SoH DIchDaq vav, je chaH DichDaq taH eunuchs Daq the joH vo' Babylon's palace.'”",
        8: "vaj Hezekiah ja'ta' Daq Isaiah, “joH'a' mu' nuq SoH ghaj jatlhpu' ghaH QaQ.” ghaH ja'ta' moreover, “vaD pa' DichDaq taH roj je vIt Daq wIj jajmey.”",
    },
    40: {
        1: "“belmoH, belmoH wIj ghotpu,” jatlhtaH lIj joH'a'.",
        2: "“jatlh comfortably Daq Jerusalem; je ja' pa' Daq Daj vetlh Daj warfare ghaH accomplished, vetlh Daj He'taHghach ghaH pardoned, vetlh ghaH ghajtaH Hevta' vo' joH'a' ghop double vaD Hoch Daj yemmey.”",
        3: "The ghogh vo' wa' 'Iv calls pa', “ghuH the way vo' joH'a' Daq the ngem! chenmoH a level highway Daq the desert vaD maj joH'a'.",
        4: "Hoch ngech DIchDaq taH exalted, je Hoch HuD je HuD DIchDaq taH chenmoHta' low. The uneven DIchDaq taH chenmoHta' level, je the rough Daqmey a plain.",
        5: "The batlh vo' joH'a' DIchDaq taH 'angta', je Hoch ghab DIchDaq legh 'oH tay'; vaD the nujDu' vo' joH'a' ghajtaH jatlhpu' 'oH.”",
        6: "The ghogh vo' wa' ja'ta', “SaQ!” wa' ja'ta', “nuq DIchDaq jIH SaQ?” “Hoch ghab ghaH rur grass, je Hoch its batlh ghaH rur the flower vo' the yotlh.",
        7: "The grass withers, the flower ngabtaH, because joH'a' breath blows Daq 'oH. DIch the ghotpu 'oH rur grass.",
        8: "The grass withers, the flower ngabtaH; 'ach the mu' vo' maj joH'a' stands reH.”",
        9: "SoH 'Iv ja' QaQ news Daq Zion, jaH Dung Daq a jen HuD. SoH 'Iv ja' QaQ news Daq Jerusalem, lift Dung lIj ghogh tlhej HoS. Lift 'oH Dung. yImev taH vIp. jatlh Daq the vengmey vo' Judah, “yIlegh, lIj joH'a'!”",
        10: "yIlegh, the joH joH'a' DichDaq ghoS as a HoS wa', je Daj arm DichDaq rule vaD ghaH. yIlegh, Daj pop ghaH tlhej ghaH, je Daj recompense qaSpa' ghaH.",
        11: "ghaH DichDaq feed Daj flock rur a DevwI'. ghaH DichDaq tay'moH the 'erHommey Daq Daj arm, je carry chaH Daq Daj bosom. ghaH DichDaq gently Dev chaH 'Iv ghaj chaj Qup.",
        12: "'Iv ghajtaH juvta' the bIQmey Daq the hollow vo' Daj ghop, je marked litHa' the sky tlhej Daj span, je calculated the dust vo' the tera' Daq a juv, je weighed the Hudmey Daq scales, je the hills Daq a 'ughghach juvwI'?",
        13: "'Iv ghajtaH directed the qa' vo' joH'a', joq ghajtaH taught ghaH as Daj counselor?",
        14: "'Iv ta'ta' ghaH tlhap qeS tlhej, je 'Iv instructed ghaH, je taught ghaH Daq the path vo' ruv, je taught ghaH Sov, je showed ghaH the way vo' yajtaHghach?",
        15: "yIlegh, the tuqpu' 'oH rur a drop Daq a bucket, je 'oH regarded as a speck vo' dust Daq a 'ughghach juvwI'. yIlegh, ghaH lifts Dung the islands rur a very mach Doch.",
        16: "Lebanon ghaH ghobe' sufficient Daq meQ, ghobe' its Ha'DIbaH sufficient vaD a meQqu'pu' cha'nob.",
        17: "Hoch the tuqpu' 'oH rur pagh qaSpa' ghaH. chaH 'oH regarded Sum ghaH as less than pagh, je vanity.",
        18: "Daq 'Iv vaj DichDaq SoH liken joH'a'? joq nuq likeness DichDaq SoH compare Daq ghaH?",
        19: "A workman ghajtaH chuH an image, je the goldsmith overlays 'oH tlhej SuD baS, je casts baS chIS chains vaD 'oH.",
        20: "ghaH 'Iv ghaH too impoverished vaD such an cha'nob chooses a Sor vetlh DichDaq ghobe' rot. ghaH seeks a skillful workman Daq cher Dung an engraved image vaD ghaH vetlh DichDaq ghobe' taH vIHta'.",
        21: "ghajbe' SoH Sovta'? ghajbe' SoH Qoyta', yet? ghajbe' SoH taH ja'ta' vo' the tagh? ghajbe' SoH understood vo' the foundations vo' the tera'?",
        22: "'oH ghaH ghaH 'Iv sits Dung the circle vo' the tera', je its nganpu' 'oH rur grasshoppers; 'Iv stretches pa' the chal rur a curtain, je spreads chaH pa' rur a juHHom Daq yIn Daq;",
        23: "'Iv brings joHHom Daq pagh; 'Iv chen the judges vo' the tera' rur meaningless.",
        24: "chaH 'oH planted scarcely. chaH 'oH sown scarcely. chaj stock ghajtaH scarcely tlhappu' root Daq the yav. ghaH merely blows Daq chaH, je chaH wither, je the whirlwind takes chaH DoH as stubble.",
        25: "“Daq 'Iv vaj DichDaq SoH liken jIH? 'Iv ghaH wIj equal?” jatlhtaH the le' wa'.",
        26: "Lift Dung lIj mInDu' Daq jen, je legh 'Iv ghajtaH created Dochvammey, 'Iv brings pa' chaj army Sum mI'. ghaH calls chaH Hoch Sum pong. Sum the greatness vo' Daj might, je because ghaH ghaH HoS Daq HoS, ghobe' wa' ghaH lacking.",
        27: "qatlh ta' SoH jatlh, Jacob, je jatlh, Israel, “wIj way ghaH hidden vo' joH'a', je the ruv due jIH ghaH disregarded Sum wIj joH'a'?”",
        28: "ghajbe' SoH Sovta'? ghajbe' SoH Qoyta'? The everlasting joH'a', joH'a', The Creator vo' the ends vo' the tera', ta'be' puj. ghaH 'oHbe' Doy'. Daj yajtaHghach ghaH unsearchable.",
        29: "ghaH nob HoS Daq the weak. ghaH increases the HoS vo' ghaH 'Iv ghajtaH ghobe' might.",
        30: "'ach the youths puj je tlhap Doy', je the Qup loDpu' utterly pum;",
        31: "'ach chaH 'Iv loS vaD joH'a' DichDaq renew chaj HoS. chaH DichDaq mount Dung tlhej telDu' rur eagles. chaH DichDaq run, je ghobe' taH Doy'. chaH DichDaq yIt, je ghobe' puj.",
    },
    41: {
        1: "“pol tam qaSpa' jIH, islands, je chaw' the ghotpu' renew chaj HoS. chaw' chaH ghoS Sum, vaj chaw' chaH jatlh. Let's ghom tay' vaD yoj.",
        2: "'Iv ghajtaH raised Dung wa' vo' the pemHov 'o'? 'Iv ja' ghaH Daq Daj qam Daq QaQtaHghach? ghaH ghopmey Dung tuqpu' Daq ghaH, je chen ghaH rule Dung joHpu'. ghaH nob chaH rur the dust Daq Daj 'etlh, rur the driven stubble Daq Daj bow.",
        3: "ghaH pursues chaH, je passes Sum safely, 'ach Sum a way vetlh ghaH ghajta' ghobe' ghoSta' tlhej Daj qamDu'.",
        4: "'Iv ghajtaH worked je ta'pu' 'oH, ja'taH the DISmey vo' the tagh? jIH, joH'a', the wa'Dich, je tlhej the last, jIH 'oH ghaH.”",
        5: "The islands ghaj leghpu', je taHvIp. The ends vo' the tera' tremble. chaH approach, je ghoS.",
        6: "Hoch helps Daj jIl. chaH jatlh Daq chaj loDnI'pu', “taH HoS!”",
        7: "vaj the carpenter encourages the goldsmith. ghaH 'Iv smoothes tlhej the hammer encourages ghaH 'Iv strikes the anvil, ja'ta' vo' the soldering, “'oH ghaH QaQ;” je ghaH fastens 'oH tlhej nails, vetlh 'oH might ghobe' totter.",
        8: "“'ach SoH, Israel, wIj toy'wI', Jacob 'Iv jIH ghaj wIvpu', the tIr vo' Abraham wIj friend,",
        9: "SoH 'Iv jIH ghaj tlhappu' 'uch vo' vo' the ends vo' the tera', je ja' vo' its corners, je ja'ta' Daq SoH, ‘SoH 'oH wIj toy'wI', jIH ghaj wIvpu' SoH je ghobe' chuH SoH DoH;'",
        10: "yImev SoH taH vIp, vaD jIH 'oH tlhej SoH. yImev taH dismayed, vaD jIH 'oH lIj joH'a'. jIH DichDaq strengthen SoH. HIja', jIH DichDaq QaH SoH. HIja', jIH DichDaq uphold SoH tlhej the nIH ghop vo' wIj QaQtaHghach.",
        11: "yIlegh, Hoch chaH 'Iv 'oH incensed Daq SoH DichDaq taH disappointed je mISmoHpu'. chaH 'Iv strive tlhej SoH DichDaq taH rur pagh, je DIchDaq chIlqu'.",
        12: "SoH DichDaq nej chaH, je won't tu' chaH, 'ach chaH 'Iv contend tlhej SoH. chaH 'Iv veS Daq SoH DichDaq taH as pagh, as a non-existent Doch.",
        13: "vaD jIH, joH'a' lIj joH'a', DichDaq 'uch lIj nIH ghop, ja'ta' Daq SoH, ‘yImev taH vIp. jIH DichDaq QaH SoH.'",
        14: "yImev taH vIp, SoH worm Jacob, je SoH loDpu' vo' Israel. jIH DichDaq QaH SoH,” jatlhtaH joH'a', “je lIj Redeemer ghaH the le' wa' vo' Israel.",
        15: "yIlegh, jIH ghaj chenmoHta' SoH Daq a chu' sharp threshing instrument tlhej teeth. SoH DichDaq thresh the Hudmey, je qIp chaH mach, je DichDaq chenmoH the hills rur yub.",
        16: "SoH DichDaq winnow chaH, je the SuS DichDaq carry chaH DoH, je the whirlwind DichDaq scatter chaH. SoH DichDaq yItIv Daq joH'a'. SoH DichDaq batlh Daq the le' wa' vo' Israel.",
        17: "The mIpHa' je needy nej bIQ, je pa' ghaH pagh. chaj jat fails vaD thirst. jIH, joH'a', DichDaq jang chaH. jIH, the joH'a' vo' Israel, DichDaq ghobe' lon chaH.",
        18: "jIH DichDaq poSmoH rivers Daq the bare heights, je springs Daq the midst vo' the valleys. jIH DichDaq chenmoH the ngem a pool vo' bIQ, je the dry puH springs vo' bIQ.",
        19: "jIH DichDaq lan cedar, acacia, myrtle, je Hergh Sormey Daq the ngem. jIH DichDaq cher fir Sormey, pine, je box Sormey tay' Daq the desert;",
        20: "vetlh chaH may legh, Sov, qel, je understand tay', vetlh the ghop vo' joH'a' ghajtaH ta'pu' vam, je the le' wa' vo' Israel ghajtaH created 'oH.",
        21: "Produce lIj cause,” jatlhtaH joH'a'. “qem vo' lIj HoS reasons,” jatlhtaH the joH vo' Jacob.",
        22: "“chaw' chaH announce, je declare Daq maH nuq DIchDaq qaS. Declare the former Dochmey, nuq chaH 'oH, vetlh maH may qel chaH, je Sov the latter pItlh vo' chaH; joq cha' maH Dochmey Daq ghoS.",
        23: "Declare the Dochmey vetlh 'oH Daq ghoS hereafter, vetlh maH may Sov vetlh SoH 'oH Qunpu'. HIja', ta' QaQ, joq ta' mIghtaHghach, vetlh maH may taH dismayed, je legh 'oH tay'.",
        24: "yIlegh, SoH 'oH vo' pagh, je lIj vum ghaH vo' pagh. ghaH 'Iv chooses SoH ghaH an qabqu'boghghach.",
        25: "“jIH ghaj raised Dung wa' vo' the pemHov nIH, je ghaH ghajtaH ghoS; vo' the rising vo' the pemHov, wa' 'Iv calls Daq wIj pong; je ghaH DIchDaq ghoS Daq DevwIpu' as Daq mortar, je as the potter treads clay.",
        26: "'Iv ghajtaH declared 'oH vo' the tagh, vetlh maH may Sov? je qaSpa', vetlh maH may jatlh, ‘ghaH ghaH nIH?' DIch, pa' ghaH ghobe' wa' 'Iv declares. DIch, pa' ghaH ghobe' wa' 'Iv shows. DIch, pa' ghaH ghobe' wa' 'Iv hears lIj mu'mey.",
        27: "jIH 'oH the wa'Dich Daq jatlh Daq Zion, ‘yIlegh, legh Daq chaH;' je jIH DichDaq nob wa' 'Iv brings QaQ news Daq Jerusalem.",
        28: "ghorgh jIH legh, pa' ghaH ghobe' loD; 'ach among chaH pa' ghaH ghobe' counselor 'Iv, ghorgh jIH tlhob vo' chaH, laH jang a mu'.",
        29: "yIlegh, Hoch vo' chaH, chaj vum 'oH vanity je pagh. chaj molten images 'oH SuS je confusion.",
    },
    42: {
        1: "“yIlegh, wIj toy'wI', 'Iv jIH uphold; wIj wIvpu', Daq 'Iv wIj qa' delights— jIH ghaj lan wIj qa' Daq ghaH. ghaH DichDaq qem ruv Daq the tuqpu'.",
        2: "ghaH DichDaq ghobe' jach, ghobe' raise Daj ghogh, ghobe' cause 'oH Daq taH Qoyta' Daq the street.",
        3: "ghaH won't ghor a bruised reed. ghaH won't meQbe'moH a dimly burning wick. ghaH DichDaq faithfully qem ruv.",
        4: "ghaH DichDaq ghobe' fail ghobe' taH discouraged, until ghaH ghajtaH cher ruv Daq the tera', je the islands DichDaq loS vaD Daj chut.”",
        5: "Thus jatlhtaH joH'a' joH'a', ghaH 'Iv created the chal je stretched chaH pa', ghaH 'Iv ngeH pa' the tera' je vetlh nuq choltaH pa' vo' 'oH, ghaH 'Iv nob breath Daq its ghotpu je qa' Daq chaH 'Iv yIt Daq 'oH.",
        6: "“jIH, joH'a', ghaj ja' SoH Daq QaQtaHghach, je DichDaq 'uch lIj ghop, je DichDaq pol SoH, je chenmoH SoH a lay' vaD the ghotpu, as a wov vaD the tuqpu';",
        7: "Daq poSmoH the blind mInDu', Daq qem the prisoners pa' vo' the dungeon, je chaH 'Iv ba' Daq HurghtaHghach pa' vo' the prison.",
        8: "“jIH 'oH joH'a'. vetlh ghaH wIj pong. jIH DichDaq ghobe' nob wIj batlh Daq another, ghobe' wIj naD Daq engraved images.",
        9: "yIlegh, the former Dochmey ghaj qaSta', je jIH declare chu' Dochmey. jIH ja' SoH about chaH qaSpa' chaH ghoS Dung.”",
        10: "bom Daq joH'a' a chu' bom, je Daj naD vo' the pItlh vo' the tera', SoH 'Iv jaH bIng Daq the biQ'a', je Hoch vetlh ghaH therein, the islands je chaj nganpu'.",
        11: "chaw' the ngem je its vengmey raise chaj voices, tlhej the villages vetlh Kedar inhabits. chaw' the nganpu' vo' Sela bom. chaw' chaH jach vo' the top vo' the Hudmey!",
        12: "chaw' chaH nob batlh Daq joH'a', je declare Daj naD Daq the islands.",
        13: "joH'a' DichDaq jaH pa' rur a HoS loD. ghaH DichDaq stir Dung zeal rur a loD vo' veS. ghaH DichDaq raise a veS SaQ. HIja', ghaH DichDaq jach QoymoHlaHbogh. ghaH DichDaq triumph Dung Daj jaghpu'.",
        14: "“jIH ghaj taH tam a tIq poH. jIH ghaj taH quiet je restrained jIH'egh. DaH jIH DichDaq SaQ pa' rur a travailing be'. jIH DichDaq both gasp je pant.",
        15: "jIH DichDaq Qaw' Hudmey je hills, je dry Dung Hoch chaj herbs. jIH DichDaq chenmoH the rivers islands, je DichDaq dry Dung the pools.",
        16: "jIH DichDaq qem the blind Sum a way vetlh chaH yImev Sov. jIH DichDaq Dev chaH Daq Hemey vetlh chaH yImev Sov. jIH DichDaq chenmoH HurghtaHghach wov qaSpa' chaH, je crooked Daqmey straight. jIH DichDaq ta' Dochvammey Dochmey, je jIH DichDaq ghobe' lon chaH.",
        17: "“chaH 'Iv voq Daq engraved images, 'Iv ja' molten images, ‘SoH 'oH maj gods' DichDaq taH tlhe'ta' DoH. chaH DichDaq taH utterly disappointed.",
        18: '“Qoy, SoH deaf, je legh, SoH blind, vetlh SoH may legh.',
        19: "'Iv ghaH blind, 'ach wIj toy'wI'? joq 'Iv ghaH as deaf as wIj messenger 'Iv jIH ngeH? 'Iv ghaH as blind as ghaH 'Iv ghaH Daq roj, je as blind as joH'a' toy'wI'?",
        20: "SoH legh law' Dochmey, 'ach yImev observe. Daj qoghDu' 'oH poSmoH, 'ach ghaH ta'be' 'Ij.",
        21: "'oH pleased joH'a', vaD Daj righteousness' chIch, Daq magnify the chut, je chenmoH 'oH honorable.",
        22: "'ach vam ghaH a robbed je plundered ghotpu. Hoch vo' chaH 'oH snared Daq holes, je chaH 'oH hidden Daq prisons. chaH ghaj moj a prey, je ghobe' wa' delivers; je a non, je ghobe' wa' jatlhtaH, ‘nobHa' chaH!'",
        23: "'Iv ghaH pa' among SoH 'Iv DichDaq nob qogh Daq vam? 'Iv DichDaq 'Ij je Qoy vaD the poH Daq ghoS?",
        24: "'Iv nobta' Jacob as plunder, je Israel Daq the robbers? ta'be' joH'a', ghaH Daq 'Iv maH ghaj yempu'? vaD chaH would ghobe' yIt Daq Daj Hemey, je chaH disobeyed Daj chut.",
        25: "vaj ghaH poured the fierceness vo' Daj QeH Daq ghaH, je the HoS vo' may'; je 'oH cher ghaH Daq qul Hoch around, 'ach ghaH ta'be' Sov; je 'oH meQpu' ghaH, 'ach ghaH ta'be' tlhap 'oH Daq tIq.”",
    },
    43: {
        1: "'ach DaH thus jatlhtaH joH'a' 'Iv created SoH, Jacob, je ghaH 'Iv formed SoH, Israel: “yImev taH vIp, vaD jIH ghaj toDta' SoH. jIH ghaj ja' SoH Sum lIj pong. SoH 'oH mine.",
        2: "ghorgh SoH juS vegh the bIQmey, jIH DichDaq taH tlhej SoH; je vegh the rivers, chaH DichDaq ghobe' overflow SoH. ghorgh SoH yIt vegh the qul, SoH DichDaq ghobe' taH meQpu', je flame DichDaq ghobe' scorch SoH.",
        3: "vaD jIH 'oH joH'a' lIj joH'a', the le' wa' vo' Israel, lIj toDwI'. jIH ghaj nobpu' Egypt as lIj ransom, Ethiopia je Seba Daq lIj Daq.",
        4: "Since SoH ghaj taH precious je honored Daq wIj leghpu', je jIH ghaj loved SoH; vaj jIH DichDaq nob ghotpu Daq lIj Daq, je tuqpu' instead vo' lIj yIn.",
        5: "yImev taH vIp; vaD jIH 'oH tlhej SoH. jIH DichDaq qem lIj tIr vo' the pemHov 'o', je tay'moH SoH vo' the pemHov 'et.",
        6: "jIH DichDaq ja' the pemHov nIH, ‘nob chaH Dung!' je ja' the pemHov poS, ‘yImev 'uch chaH DoH! qem wIj puqloDpu' vo' Hop, je wIj puqbe'pu' vo' the ends vo' the tera'—",
        7: "Hoch 'Iv ghaH ja' Sum wIj pong, je 'Iv jIH ghaj created vaD wIj batlh, 'Iv jIH ghaj formed, HIja', 'Iv jIH ghaj chenmoHta'.'”",
        8: "qem pa' the blind ghotpu 'Iv ghaj mInDu', je the deaf 'Iv ghaj qoghDu'.",
        9: "chaw' Hoch the tuqpu' taH boSta' tay', je chaw' the ghotpu' taH assembled. 'Iv among chaH laH declare vam, je cha' maH former Dochmey? chaw' chaH qem chaj witnesses, vetlh chaH may taH justified; joq chaw' chaH Qoy, je jatlh, “vetlh ghaH true.”",
        10: "“SoH 'oH wIj witnesses,” jatlhtaH joH'a', “tlhej wIj toy'wI' 'Iv jIH ghaj wIvpu'; vetlh SoH may Sov je Har jIH, je understand vetlh jIH 'oH ghaH. qaSpa' jIH pa' ghaHta' ghobe' joH'a' formed, ghobe' DichDaq pa' taH after jIH.",
        11: "jIH jIH'egh 'oH joH'a'; je je jIH pa' ghaH ghobe' toDwI'.",
        12: "jIH ghaj declared, jIH ghaj toDpu', je jIH ghaj shown; je pa' ghaHta' ghobe' strange joH'a' among SoH. vaj SoH 'oH wIj witnesses,” jatlhtaH joH'a', “je jIH 'oH joH'a'.",
        13: "HIja', since the jaj ghaHta' jIH 'oH ghaH; je pa' ghaH ghobe' wa' 'Iv laH toD pa' vo' wIj ghop. jIH DichDaq vum, je 'Iv laH hinder 'oH?”",
        14: "Thus jatlhtaH joH'a', lIj Redeemer, the le' wa' vo' Israel: “vaD lIj chIch, jIH ghaj ngeHta' Daq Babylon, je jIH DichDaq qem Hoch vo' chaH bIng as fugitives, 'ach the Chaldeans, Daq the ships vo' chaj rejoicing.",
        15: "jIH 'oH joH'a', lIj le' wa', the Creator vo' Israel, lIj joH.”",
        16: "Thus jatlhtaH joH'a', 'Iv chen a way Daq the biQ'a', je a path Daq the HoS bIQmey;",
        17: "'Iv brings vo' the chariot je horse, the army je the HoS loD (chaH Qot bIng tay', chaH DIchDaq ghobe' Hu'; chaH 'oH extinct, chaH 'oH quenched rur a wick):",
        18: "“yImev qaw the former Dochmey, je yImev qel the Dochmey vo' qan.",
        19: "yIlegh, jIH DichDaq ta' a chu' Doch. 'oH springs vo' DaH. yImev SoH Sov 'oH? jIH DichDaq 'ach chenmoH a way Daq the ngem, je rivers Daq the desert.",
        20: "The Ha'DIbaH vo' the yotlh DIchDaq quv jIH, the jackals je the ostriches; because jIH nob bIQ Daq the ngem je rivers Daq the desert, Daq nob tlhutlh Daq wIj ghotpu, wIj wIvpu',",
        21: "the ghotpu nuq jIH formed vaD jIH'egh, vetlh chaH might cher vo' wIj naD.",
        22: "Yet SoH ghaj ghobe' ja' Daq jIH, Jacob; 'ach SoH ghaj taH Doy' vo' jIH, Israel.",
        23: "SoH ghaj ghobe' qempu' jIH vo' lIj Suy' vaD meQqu'pu' nobmey; ghobe' ghaj SoH honored jIH tlhej lIj nobmey. jIH ghaj ghobe' burdened SoH tlhej nobmey, ghobe' wearied SoH tlhej frankincense.",
        24: "SoH ghaj je'ta' jIH ghobe' sweet cane tlhej Huch, ghobe' ghaj SoH tebta' jIH tlhej the ror vo' lIj nobmey; 'ach SoH ghaj burdened jIH tlhej lIj yemmey. SoH ghaj wearied jIH tlhej lIj iniquities.",
        25: "jIH, 'ach jIH, 'oH ghaH 'Iv blots pa' lIj transgressions vaD wIj ghaj chIch; je jIH DichDaq ghobe' qaw lIj yemmey.",
        26: "lan jIH Daq remembrance. chaw' maH tlhob tay'. cher vo' lIj case, vetlh SoH may taH justified.",
        27: "lIj wa'Dich vav yempu', je lIj teachers ghaj transgressed Daq jIH.",
        28: "vaj jIH DichDaq profane the joHHom vo' the Daq QaD; je jIH DichDaq chenmoH Jacob a mu'qaD, je Israel an insult.”",
    },
    44: {
        1: "Yet 'Ij DaH, Jacob wIj toy'wI', je Israel, 'Iv jIH ghaj wIvpu'.",
        2: "vam ghaH nuq joH'a' 'Iv chenmoHta' SoH, je formed SoH vo' the womb, 'Iv DichDaq QaH SoH jatlhtaH: “yImev taH vIp, Jacob wIj toy'wI'; je SoH, Jeshurun, 'Iv jIH ghaj wIvpu'.",
        3: "vaD jIH DichDaq pour bIQ Daq ghaH 'Iv ghaH thirsty, je streams Daq the dry yav. jIH DichDaq pour wIj qa' Daq lIj tIr, je wIj blessing Daq lIj offspring:",
        4: 'je chaH DichDaq spring Dung among the grass, as willows Sum the watercourses.',
        5: "wa' DichDaq jatlh, ‘jIH 'oH joH'a';' je another DichDaq taH ja' Sum the pong vo' Jacob; je another DichDaq write tlhej Daj ghop ‘Daq joH'a',' je quv the pong vo' Israel.”",
        6: "vam ghaH nuq joH'a', the joH vo' Israel, je Daj Redeemer, joH'a' vo' Armies, jatlhtaH: “jIH 'oH the wa'Dich, je jIH 'oH the last; je je jIH pa' ghaH ghobe' joH'a'.",
        7: "'Iv ghaH rur jIH? 'Iv DichDaq ja', je DichDaq declare 'oH, je cher 'oH Daq order vaD jIH, since jIH established the ancient ghotpu? chaw' chaH declare the Dochmey vetlh 'oH choltaH, je vetlh DichDaq qaS.",
        8: "yImev taHvIp, ghobe' taH vIp. ghajbe' jIH declared 'oH Daq SoH tIq ben, je shown 'oH? SoH 'oH wIj witnesses. ghaH pa' a joH'a' je jIH? Indeed, pa' ghaH ghobe'. jIH yImev Sov vay' latlh nagh.”",
        9: "Hoch 'Iv chen an engraved image ghaH lI'be'. The Dochmey vetlh chaH tIv Daq DichDaq ghobe' profit. chaj ghaj witnesses yImev legh, ghobe' Sov, vetlh chaH may taH disappointed.",
        10: "'Iv ghajtaH fashioned a joH'a', joq molds an image vetlh ghaH profitable vaD pagh?",
        11: "yIlegh, Hoch Daj fellows DichDaq taH disappointed; je the workmen 'oH mere loDpu'. chaw' chaH Hoch taH boSta' tay'. chaw' chaH Qam Dung. chaH DichDaq taHvIp. chaH DichDaq taH lan Daq tuH tay'.",
        12: "The blacksmith takes an axe, vum Daq the coals, fashions 'oH tlhej hammers, je vum 'oH tlhej Daj HoS arm. ghaH ghaH hungry, je Daj HoS fails; ghaH drinks ghobe' bIQ, je ghaH puj.",
        13: "The carpenter stretches pa' a tlhegh. ghaH marks 'oH pa' tlhej a pencil. ghaH shapes 'oH tlhej planes. ghaH marks 'oH pa' tlhej compasses, je shapes 'oH rur the figure vo' a loD, tlhej the 'IhtaHghach vo' a loD, Daq reside Daq a tuq.",
        14: "ghaH cuts bIng cedars vaD himself, je takes the cypress je the Sor'a', je strengthens vaD himself wa' among the Sormey vo' the forest. ghaH plants a fir Sor, je the rain nourishes 'oH.",
        15: "vaj 'oH DichDaq taH vaD a loD Daq meQ; je ghaH takes 'op vo' 'oH, je warms himself. HIja', ghaH burns 'oH, je vuttaH tIr Soj. HIja', ghaH chen a joH'a', je worships 'oH; ghaH chen 'oH an engraved image, je falls bIng Daq 'oH.",
        16: "ghaH burns part vo' 'oH Daq the qul. tlhej part vo' 'oH, ghaH eats meat. ghaH roasts a roast, je ghaH satisfied. HIja', ghaH warms himself, je jatlhtaH, “toH! jIH 'oH warm. jIH ghaj leghpu' the qul.”",
        17: "The leS vo' 'oH ghaH chen Daq a joH'a', 'ach Daj engraved image. ghaH bows bIng Daq 'oH je worships, je prays Daq 'oH, je jatlhtaH, “toD jIH; vaD SoH 'oH wIj joH'a'!”",
        18: "chaH yImev Sov, ghobe' ta' chaH qel: vaD ghaH ghajtaH shut chaj mInDu', vetlh chaH ta'laHbe' legh; je chaj tIQDu', vetlh chaH ta'laHbe' understand.",
        19: "ghobe' wa' thinks, ghobe' ghaH pa' Sov ghobe' yajtaHghach Daq jatlh, “jIH ghaj meQpu' part vo' 'oH Daq the qul. HIja', jIH ghaj je vutta' tIr Soj Daq its coals. jIH ghaj roasted meat je eaten 'oH. DIchDaq jIH chenmoH the leS vo' 'oH Daq an qabqu'boghghach? DIchDaq jIH bow bIng Daq a Sor trunk?”",
        20: "ghaH feeds Daq ashes. A deceived tIq ghajtaH tlhe'ta' ghaH aside; je ghaH ta'laHbe' toD Daj qa', ghobe' jatlh, “'oHbe' pa' a Qot Daq wIj nIH ghop?”",
        21: "qaw Dochvammey Dochmey, Jacob je Israel; vaD SoH 'oH wIj toy'wI'. jIH ghaj formed SoH. SoH 'oH wIj toy'wI'. Israel, SoH DichDaq ghobe' taH forgotten Sum jIH.",
        22: "jIH ghaj blotted pa', as a thick cloud, lIj transgressions, je, as a cloud, lIj yemmey. chegh Daq jIH, vaD jIH ghaj toDta' SoH.",
        23: "bom, SoH chal, vaD joH'a' ghajtaH ta'pu' 'oH! jach, SoH lower parts vo' the tera'! ghor pa' Daq bomtaH, SoH Hudmey, toH forest, Hoch vo' lIj Sormey, vaD joH'a' ghajtaH toDta' Jacob, je DichDaq glorify himself Daq Israel.",
        24: "Thus jatlhtaH joH'a', lIj Redeemer, je ghaH 'Iv formed SoH vo' the womb: “jIH 'oH joH'a', 'Iv chen Hoch Dochmey; 'Iv mob stretches pa' the chal; 'Iv spreads pa' the tera' Sum jIH'egh;",
        25: "'Iv frustrates the signs vo' the liars, je chen diviners mad; 'Iv turns val loDpu' DoH, je chen chaj Sov foolish;",
        26: "'Iv confirms the mu' vo' Daj toy'wI', je performs the qeS vo' Daj Duypu'; 'Iv jatlhtaH vo' Jerusalem, ‘ghaH DichDaq taH inhabited;' je vo' the vengmey vo' Judah, ‘chaH DichDaq taH chenta',' je ‘jIH DichDaq raise Dung its waste Daqmey;'",
        27: "'Iv jatlhtaH Daq the deep, ‘taH dry,' je ‘jIH DichDaq dry Dung lIj rivers;'",
        28: "'Iv jatlhtaH vo' Cyrus, ‘ghaH ghaH wIj DevwI', je DIchDaq perform Hoch wIj pleasure,' 'ach ja'ta' vo' Jerusalem, ‘ghaH DichDaq taH chenta';' je vo' the lalDan qach, ‘lIj foundation DichDaq taH laid.'”",
    },
    45: {
        1: "Thus jatlhtaH joH'a' Daq Daj ngoHta', Daq Cyrus, 'Iv nIH ghop jIH ghaj held, Daq subdue tuqpu' qaSpa' ghaH, je strip joHpu' vo' chaj armor; Daq poSmoH the doors qaSpa' ghaH, je the lojmItmey DIchDaq ghobe' taH shut:",
        2: "“jIH DichDaq jaH qaSpa' SoH, je chenmoH the rough Daqmey smooth. jIH DichDaq ghor the doors vo' brass Daq pieces, je pe' apart the bars vo' iron.",
        3: "jIH DichDaq nob SoH the treasures vo' HurghtaHghach, je hidden riches vo' pegh Daqmey, vetlh SoH may Sov vetlh 'oH ghaH jIH, joH'a', 'Iv ja' SoH Sum lIj pong, 'ach the joH'a' vo' Israel.",
        4: "vaD Jacob wIj toy'wI' chIch, je Israel wIj wIvpu', jIH ghaj ja' SoH Sum lIj pong. jIH ghaj surnamed SoH, 'a' SoH ghaj ghobe' Sovta' jIH.",
        5: "jIH 'oH joH'a', je pa' ghaH pagh else. je jIH, pa' ghaH ghobe' joH'a'. jIH DichDaq strengthen { Note: joq, equip } SoH, 'a' SoH ghaj ghobe' Sovta' jIH;",
        6: "vetlh chaH may Sov vo' the rising vo' the pemHov, je vo' the pemHov 'et, vetlh pa' ghaH pagh je jIH. jIH 'oH joH'a', je pa' ghaH ghobe' wa' else.",
        7: "jIH form the wov, je create HurghtaHghach. jIH chenmoH roj, je create calamity. jIH 'oH joH'a', 'Iv ta'taH Hoch Dochvammey Dochmey.",
        8: "Distil, SoH chal, vo' Dung, je chaw' the chal pour bIng QaQtaHghach. chaw' the tera' poSmoH, vetlh 'oH may qem vo' toDtaHghach, je chaw' 'oH cause QaQtaHghach Daq spring Dung tlhej 'oH. jIH, joH'a', ghaj created 'oH.",
        9: "Woe Daq ghaH 'Iv strives tlhej Daj Maker— a clay pot among the clay pots vo' the tera'! DIchDaq the clay tlhob ghaH 'Iv fashions 'oH, ‘nuq 'oH SoH making?' joq lIj vum, ‘ghaH ghajtaH ghobe' ghopmey?'",
        10: "Woe Daq ghaH 'Iv jatlhtaH Daq a vav, ‘nuq ghaj SoH moj the vav vo'?' joq Daq a SoS, ‘Daq nuq ghaj SoH nobpu' birth?'”",
        11: "Thus jatlhtaH joH'a', the le' wa' vo' Israel, je Daj Maker: “SoH tlhob jIH about the Dochmey vetlh 'oH Daq ghoS, concerning wIj puqloDpu', je SoH ra'ta'ghach mu'mey jIH concerning the vum vo' wIj ghopmey!",
        12: "jIH ghaj chenmoHta' the tera', je created loD Daq 'oH. jIH, 'ach wIj ghopmey, ghaj stretched pa' the chal; je jIH ghaj ra'ta' Hoch chaj army.",
        13: "jIH ghaj raised ghaH Dung Daq QaQtaHghach, je jIH DichDaq chenmoH straight Hoch Daj Hemey. ghaH DIchDaq chen wIj veng, je ghaH DIchDaq chaw' wIj exiles jaH free, ghobe' vaD price ghobe' pop,” jatlhtaH joH'a' vo' Armies.",
        14: "Thus jatlhtaH joH'a': “The labor vo' Egypt, je the merchandise vo' Ethiopia, je the Sabeans, loDpu' vo' stature, DIchDaq ghoS Dung Daq SoH, je chaH DIchDaq taH yours. chaH DichDaq jaH after SoH. chaH DIchDaq ghoS Dung Daq chains; je chaH DichDaq bow bIng Daq SoH. chaH DichDaq chenmoH supplication Daq SoH: ‘DIch joH'a' ghaH Daq SoH; je pa' ghaH pagh else. pa' ghaH ghobe' latlh joH'a'.",
        15: "HochHom certainly SoH 'oH a joH'a' 'Iv hid SoH'egh, joH'a' vo' Israel, the toDwI'.'”",
        16: "chaH DichDaq taH disappointed, HIja', mISmoHpu', Hoch vo' chaH. chaH 'Iv 'oH makers vo' idols DichDaq jaH Daq confusion tay'.",
        17: "Israel DichDaq taH toDpu' Sum joH'a' tlhej an everlasting toDtaHghach. SoH DichDaq ghobe' taH disappointed ghobe' mISmoHpu' Daq ages everlasting.",
        18: "vaD thus jatlhtaH joH'a' 'Iv created the chal, the joH'a' 'Iv formed the tera' je chenmoHta' 'oH, 'Iv established 'oH je ta'be' create 'oH a waste, 'Iv formed 'oH Daq taH inhabited: “jIH 'oH joH'a'; je pa' ghaH ghobe' latlh.",
        19: "jIH ghaj ghobe' jatlhpu' Daq pegh, Daq a Daq vo' the puH vo' HurghtaHghach. jIH ta'be' jatlh Daq the tIr vo' Jacob, ‘nej jIH Daq lI'be'.' jIH, joH'a', jatlh QaQtaHghach. jIH declare Dochmey vetlh 'oH nIH.",
        20: "“Assemble tlhIH'egh je ghoS. Draw Sum tay', SoH 'Iv ghaj escaped vo' the tuqpu'. chaH ghaj ghobe' Sov 'Iv carry the wood vo' chaj engraved image, je tlhob Daq a joH'a' vetlh ta'laHbe' toD.",
        21: "Declare je present 'oH. HIja', chaw' chaH tlhap qeS tay'. 'Iv ghajtaH shown vam vo' ancient poH? 'Iv ghajtaH declared 'oH vo' qan? ghajbe' jIH, joH'a'? pa' ghaH ghobe' latlh joH'a' je jIH, a just joH'a' je a toDwI'; pa' ghaH ghobe' wa' je jIH.",
        22: "“legh Daq jIH, je taH toDpu', Hoch the ends vo' the tera'; vaD jIH 'oH joH'a', je pa' ghaH ghobe' latlh.",
        23: "Sum jIH'egh ghaj jIH sworn, the mu' ghajtaH ghoSta' vo' vo' wIj nujDu' Daq QaQtaHghach, je DichDaq ghobe' chegh, vetlh Daq jIH Hoch knee DIchDaq bow, Hoch jat DIchDaq swear.",
        24: "chaH DichDaq jatlh vo' jIH, ‘pa' ghaH QaQtaHghach je HoS neH Daq joH'a'.'” 'ach Daq ghaH DIchDaq loDpu' ghoS; je Hoch chaH 'Iv were incensed Daq ghaH DIchDaq taH disappointed.",
        25: "Daq joH'a' DIchDaq Hoch the tIr vo' Israel taH justified, je DIchDaq batlh.",
    },
    46: {
        1: "Bel bows bIng, Nebo stoops; chaj idols 'oH Daq the Ha'DIbaH, je Daq the livestock: the Dochmey vetlh SoH qengta' about 'oH chenmoHta' a load, a burden Daq the Doy' animal.",
        2: "chaH stoop, chaH bow bIng tay'; chaH laH ghobe' toD the burden, 'ach themselves 'oH ghoSta' Daq captivity.",
        3: "“'Ij Daq jIH, tuq vo' Jacob, je Hoch the chuv vo' the tuq vo' Israel, vetlh ghaj taH borne Sum jIH vo' chaj birth, vetlh ghaj taH qengta' vo' the womb;",
        4: "je 'ach Daq qan age jIH 'oH ghaH, je 'ach Daq gray jIb DichDaq jIH carry SoH. jIH ghaj chenmoHta', je jIH DichDaq SIQ; HIja', jIH DichDaq carry, je DichDaq toD.",
        5: "“Daq 'Iv DichDaq SoH liken jIH, je chenmoH jIH equal, je compare jIH, vetlh maH may taH rur?",
        6: "'op pour pa' SuD baS vo' the tep, je weigh baS chIS Daq the 'ughghach juvwI'. chaH hire a goldsmith, je ghaH chen 'oH a joH'a'. chaH pum bIng— HIja', chaH lalDan toy'.",
        7: "chaH SIQ 'oH Daq the shoulder, chaH carry 'oH, je cher 'oH Daq its Daq, je 'oH stands, vo' its Daq 'oH DIchDaq ghobe' vIH: HIja', wa' may SaQ Daq 'oH, yet 'oH laH ghobe' jang, ghobe' toD ghaH pa' vo' Daj Seng.",
        8: "“qaw vam, je cha' tlhIH'egh loDpu'; qem 'oH again Daq yab, SoH yemwI'pu'.",
        9: "qaw the former Dochmey vo' qan: vaD jIH 'oH joH'a', je pa' ghaH pagh else; jIH 'oH joH'a', je pa' ghaH pagh rur jIH;",
        10: "declaring the pItlh vo' the tagh, je vo' ancient poHmey Dochmey vetlh 'oH ghobe' yet ta'pu'; ja'ta', wIj qeS DIchDaq Qam, je jIH DichDaq ta' Hoch wIj pleasure;",
        11: "ja'taH a ravenous toQ vo' the pemHov 'o', the loD vo' wIj qeS vo' a Hop Hatlh; HIja', jIH ghaj jatlhpu', jIH DichDaq je qem 'oH Daq juS; jIH ghaj purposed, jIH DichDaq je ta' 'oH.",
        12: "'Ij Daq jIH, SoH stout-hearted, 'Iv 'oH Hop vo' QaQtaHghach:",
        13: "jIH qem Sum wIj QaQtaHghach, 'oH DIchDaq ghobe' taH Hop litHa', je wIj toDtaHghach DIchDaq ghobe' loS; je jIH DichDaq Daq toDtaHghach Daq Zion vaD Israel wIj batlh.",
    },
    47: {
        1: "“ghoS bIng, je ba' Daq the dust, virgin puqbe' vo' Babylon; ba' Daq the yav Hutlh a quS'a', puqbe' vo' the Chaldeans: vaD SoH DIchDaq ghobe' latlh taH ja' tender je delicate.",
        2: "tlhap the millstones, je grind 'uQ; teq lIj veil, strip litHa' the train, uncover the leg, juS vegh the rivers.",
        3: "lIj nakedness DIchDaq taH uncovered, HIja', lIj tuH DIchDaq taH leghpu': jIH DichDaq tlhap vengeance, je DichDaq spare ghobe' loD.”",
        4: "maj Redeemer, joH'a' vo' Armies ghaH Daj pong, the le' wa' vo' Israel.",
        5: "“ba' Daq tammoH, je jaH Daq HurghtaHghach, puqbe' vo' the Chaldeans; vaD SoH DIchDaq ghobe' latlh taH ja' the mistress vo' kingdoms.",
        6: "jIH ghaHta' angry tlhej wIj ghotpu, jIH profaned wIj inheritance, je nobta' chaH Daq lIj ghop: SoH showed chaH ghobe' pung; Daq the aged SoH ghaj very heavily laid lIj yoke.",
        7: "SoH ja'ta', jIH DIchDaq taH mistress reH; vaj vetlh SoH ta'ta' ghobe' lay Dochvammey Dochmey Daq lIj tIq, ghobe' ta'ta' qaw the latter pItlh vo' 'oH.",
        8: "“DaH vaj Qoy vam, SoH 'Iv 'oH nobpu' Daq pleasures, 'Iv ba' securely, 'Iv jatlh Daq lIj tIq, jIH 'oH, je pa' ghaH pagh else je jIH; jIH DIchDaq ghobe' ba' as a Heghbe'nal, ghobe' DIchDaq jIH Sov the loss vo' puqpu':",
        9: "'ach Dochvammey cha' Dochmey DIchDaq ghoS Daq SoH Daq a moment Daq wa' jaj, the loss vo' puqpu', je widowhood; Daq chaj teblu'ta' juv DIchDaq chaH ghoS Daq SoH, Daq the qevmey vo' lIj sorceries, je the Dun abundance vo' lIj enchantments.",
        10: "vaD SoH ghaj trusted Daq lIj mIghtaHghach; SoH ghaj ja'ta', ghobe' wa' sees jIH; lIj valtaHghach je lIj Sov, 'oH ghajtaH perverted SoH, je SoH ghaj ja'ta' Daq lIj tIq, jIH 'oH, je pa' ghaH pagh else je jIH.",
        11: "vaj mIghtaHghach DichDaq ghoS Daq SoH; SoH won't Sov ghorgh 'oH dawns: je mischief wil pum Daq SoH; SoH DichDaq ghobe' taH laH Daq lan 'oH DoH: je desolation DIchDaq ghoS Daq SoH suddenly, nuq SoH yImev Sov.",
        12: "“Qam DaH tlhej lIj enchantments, je tlhej the qevmey vo' lIj sorceries, Daq nuq SoH ghaj labored vo' lIj youth; chugh vaj taH SoH DIchDaq taH laH Daq profit, chugh vaj taH SoH may prevail.",
        13: "SoH 'oH wearied Daq the qevmey vo' lIj counsels: chaw' DaH the astrologers, the stargazers, the monthly prognosticators, Qam Dung, je toD SoH vo' the Dochmey vetlh DIchDaq ghoS Daq SoH.",
        14: "yIlegh, chaH DIchDaq taH as stubble; the qul DIchDaq meQ chaH; chaH DIchDaq ghobe' toD themselves vo' the HoS vo' the flame: 'oH DIchDaq ghobe' taH a coal Daq warm Daq, ghobe' a qul Daq ba' qaSpa'.",
        15: "Thus DIchDaq the Dochmey taH Daq SoH Daq nuq SoH ghaj labored: chaH 'Iv ghaj trafficked tlhej SoH vo' lIj youth DIchDaq wander Hoch Daq Daj quarter; pa' DIchDaq taH pagh Daq toD SoH.",
    },
    48: {
        1: "“Qoy vam, tuq vo' Jacob, SoH 'Iv 'oH ja' Sum the pong vo' Israel, je ghaj ghoS vo' pa' vo' the bIQmey vo' Judah; 'Iv swear Sum the pong vo' joH'a', je chenmoH mention vo' the joH'a' vo' Israel, 'ach ghobe' Daq vIt, ghobe' Daq QaQtaHghach",
        2: "(vaD chaH ja' themselves vo' the le' veng, je stay themselves Daq the joH'a' vo' Israel; joH'a' vo' Armies ghaH Daj pong):",
        3: "jIH ghaj declared the former Dochmey vo' vo' qan; HIja', chaH mejta' vo' pa' vo' wIj nujDu', je jIH showed chaH: suddenly jIH ta'ta' chaH, je chaH qaSta'.",
        4: "Because jIH knew vetlh SoH 'oH obstinate, je lIj neck ghaH an iron sinew, je lIj brow brass;",
        5: "vaj jIH ghaj declared 'oH Daq SoH vo' vo' qan; qaSpa' 'oH ghoSta' Daq juS jIH showed 'oH Daq SoH; lest SoH should jatlh, ‘wIj idol ghajtaH ta'pu' chaH, je wIj engraved image, je wIj molten image, ghajtaH ra'ta' chaH.'",
        6: "SoH ghaj Qoyta' 'oH; legh Hoch vam; je SoH, DichDaq SoH ghobe' declare 'oH? “jIH ghaj shown SoH chu' Dochmey vo' vam poH, 'ach hidden Dochmey, nuq SoH ghaj ghobe' Sovta'.",
        7: "chaH 'oH created DaH, je ghobe' vo' vo' qan; je qaSpa' vam jaj SoH ta'be' Qoy chaH; lest SoH should jatlh, ‘yIlegh, jIH knew chaH.'",
        8: "HIja', SoH ta'be' Qoy; HIja', SoH ta'be' Sov; HIja', vo' vo' qan lIj qogh ghaHta' ghobe' poSmaHpu': vaD jIH knew vetlh SoH ta'ta' Da very treacherously, je ghaHta' ja' a transgressor vo' the womb.",
        9: "vaD wIj pong chIch DichDaq jIH defer wIj QeH, je vaD wIj naD DichDaq jIH refrain vaD SoH, vetlh jIH ghobe' pe' SoH litHa'.",
        10: "yIlegh, jIH ghaj refined SoH, 'ach ghobe' as baS chIS; jIH ghaj wIvpu' SoH Daq the furnace vo' affliction.",
        11: "vaD wIj ghaj chIch, vaD wIj ghaj chIch, DichDaq jIH ta' 'oH; vaD chay' should wIj pong taH profaned? je wIj batlh jIH DichDaq ghobe' nob Daq another.",
        12: "“'Ij Daq jIH, toH Jacob, je Israel wIj ja': jIH 'oH ghaH; jIH 'oH the wa'Dich, jIH je 'oH the last.",
        13: "HIja', wIj ghop ghajtaH laid the foundation vo' the tera', je wIj nIH ghop ghajtaH ngeH pa' the chal: ghorgh jIH ja' Daq chaH, chaH Qam Dung tay'.",
        14: "“Assemble tlhIH'egh, Hoch SoH, je Qoy; 'Iv among chaH ghajtaH declared Dochvammey Dochmey? ghaH 'Iv joH'a' muSHa'taH DIchDaq perform Daj pleasure Daq Babylon, je Daj arm DIchDaq taH Daq the Chaldeans.",
        15: "jIH, 'ach jIH, ghaj jatlhpu'; HIja', jIH ghaj ja' ghaH; jIH ghaj qempu' ghaH, je ghaH DIchDaq chenmoH Daj way mIp.",
        16: "“ghoS Sum Daq jIH je Qoy vam: “vo' the tagh jIH ghaj ghobe' jatlhpu' Daq pegh; vo' the poH vetlh 'oH ghaHta', pa' 'oH jIH.” DaH the joH joH'a' ghajtaH ngeHta' jIH, tlhej Daj qa'.",
        17: "Thus jatlhtaH joH'a', lIj Redeemer, the le' wa' vo' Israel: jIH 'oH joH'a' lIj joH'a', 'Iv teaches SoH Daq profit, 'Iv Dev SoH Sum the way vetlh SoH should jaH.",
        18: "Oh vetlh SoH ghajta' listened Daq wIj ra'ta'ghach mu'mey! vaj lIj roj would ghaj taH rur a bIQtIQ, je lIj QaQtaHghach rur the waves vo' the biQ'a':",
        19: "lIj tIr je ghajta' taH as the sand, je the offspring vo' lIj porgh rur its grains: Daj pong would ghobe' taH pe' litHa' ghobe' Qaw'ta' vo' qaSpa' jIH.",
        20: "jaH vo' vo' Babylon, Haw' vo' the Chaldeans; tlhej a ghogh vo' bomtaH declare, ja' vam, utter 'oH 'ach Daq the pItlh vo' the tera': jatlh, joH'a' ghajtaH toDta' Daj toy'wI' Jacob.",
        21: "chaH ta'be' thirst ghorgh ghaH led chaH vegh the deserts; ghaH caused the bIQmey Daq flow pa' vo' the nagh vaD chaH; ghaH split the nagh je, je the bIQmey gushed pa'.",
        22: "“pa' ghaH ghobe' roj,” jatlhtaH joH'a', “vaD the mIgh.”",
    },
    49: {
        1: "'Ij, islands, Daq jIH; je 'Ij, SoH ghotpu', vo' Hop: joH'a' ghajtaH ja' jIH vo' the womb; vo' the bowels vo' wIj SoS ghajtaH ghaH chenmoHta' mention vo' wIj pong:",
        2: "je ghaH ghajtaH chenmoHta' wIj nujDu' rur a sharp 'etlh; Daq the QIb vo' Daj ghop ghajtaH ghaH hid jIH: je ghaH ghajtaH chenmoHta' jIH a polished shaft; Daq Daj quiver ghajtaH ghaH polta' jIH close:",
        3: "je ghaH ja'ta' Daq jIH, “SoH 'oH wIj toy'wI'; Israel, Daq 'Iv jIH DichDaq taH glorified.”",
        4: "'ach jIH ja'ta', “jIH ghaj labored Daq lI'be', jIH ghaj spent wIj HoS vaD pagh je vanity; yet DIch the ruv due Daq jIH ghaH tlhej joH'a', je wIj pop tlhej wIj joH'a'.”",
        5: "DaH jatlhtaH joH'a' 'Iv formed jIH vo' the womb Daq taH Daj toy'wI', Daq qem Jacob again Daq ghaH, je vetlh Israel taH boSta' Daq ghaH (vaD jIH 'oH honorable Daq the mInDu' vo' joH'a', je wIj joH'a' ghaH moj wIj HoS);",
        6: "HIja', ghaH jatlhtaH, “'oH ghaH too wov a Doch vetlh SoH should taH wIj toy'wI' Daq raise Dung the tuqpu' vo' Jacob, je Daq nobHa' the polta' vo' Israel: jIH DichDaq je nob SoH vaD a wov Daq the tuqpu', vetlh SoH may taH wIj toDtaHghach Daq the pItlh vo' the tera'.”",
        7: "Thus jatlhtaH joH'a', the Redeemer vo' Israel, je Daj le' wa', Daq ghaH 'Iv loD despises, Daq ghaH 'Iv the Hatlh abhors, Daq a toy'wI' vo' DevwIpu': “joHpu' DIchDaq legh je Hu'; joHHom, je chaH DIchDaq lalDan toy'; because vo' joH'a' 'Iv ghaH voqmoH, 'ach the le' wa' vo' Israel, 'Iv ghajtaH wIvpu' SoH.”",
        8: "Thus jatlhtaH joH'a', “Daq an acceptable poH ghaj jIH jangta' SoH, je Daq a jaj vo' toDtaHghach ghaj jIH helped SoH; je jIH DichDaq pol SoH, je nob SoH vaD a lay' vo' the ghotpu, Daq raise Dung the puH, Daq chenmoH chaH inherit the moB heritage:",
        9: "ja'ta' Daq chaH 'Iv 'oH bagh, ‘ghoS pa'!'; Daq chaH 'Iv 'oH Daq HurghtaHghach, ‘cha' tlhIH'egh!' “chaH DIchDaq feed Daq the Hemey, je Daq Hoch bare heights DIchDaq taH chaj tI yotlh.",
        10: "chaH DIchDaq ghobe' hunger ghobe' thirst; ghobe' DIchDaq the heat ghobe' pemHov mup chaH: vaD ghaH 'Iv ghajtaH pung Daq chaH DichDaq Dev chaH, 'ach Sum springs vo' bIQ ghaH DichDaq guide chaH.",
        11: 'jIH DichDaq chenmoH Hoch wIj Hudmey a way, je wIj highways DIchDaq taH exalted.',
        12: "yIlegh, Dochvammey DIchDaq ghoS vo' Hop; je yIlegh, Dochvammey vo' the pemHov nIH je vo' the pemHov 'et; je Dochvammey vo' the puH vo' Sinim.”",
        13: "bom, chal; je taH joyful, tera'; je ghor vo' Daq bomtaH, Hudmey: vaD joH'a' ghajtaH comforted Daj ghotpu, je DichDaq ghaj compassion Daq Daj afflicted.",
        14: "'ach Zion ja'ta', “joH'a' ghajtaH lonta' jIH, je the joH ghajtaH forgotten jIH.”",
        15: "“laH a be' forget Daj sucking puq, vetlh ghaH should ghobe' ghaj compassion Daq the puqloD vo' Daj womb? HIja', Dochvammey may forget, yet jIH DichDaq ghobe' forget SoH!",
        16: "yIlegh, jIH ghaj engraved SoH Daq the palms vo' wIj ghopmey; lIj walls 'oH continually qaSpa' jIH.",
        17: "lIj puqpu' chenmoH haste; lIj destroyers je chaH 'Iv chenmoHta' SoH waste DIchDaq jaH vo' vo' SoH.",
        18: "Lift Dung lIj mInDu' Hoch around, je legh: Hoch Dochvammey tay'moH themselves tay', je ghoS Daq SoH. As jIH yIn,” jatlhtaH joH'a', “SoH DIchDaq DIch clothe SoH'egh tlhej chaH Hoch as tlhej an ornament, je gird SoH'egh tlhej chaH, rur a bride.",
        19: "“vaD, as vaD lIj waste je lIj moB Daqmey, je lIj puH vetlh ghajtaH taH Qaw'ta', DIch DaH SoH DIchDaq taH too mach vaD the nganpu', je chaH 'Iv swallowed SoH Dung DIchDaq taH Hop DoH.",
        20: "The puqpu' vo' lIj bereavement DIchDaq yet jatlh Daq lIj qoghDu', The Daq ghaH too mach vaD jIH; nob Daq Daq jIH vetlh jIH may yIn.",
        21: "vaj SoH DichDaq jatlh Daq lIj tIq, ‘'Iv ghajtaH conceived Dochvammey vaD jIH, leghtaH jIH ghaj taH bereaved vo' wIj puqpu', je 'oH solitary, an exile, je wandering DoH je vo'? 'Iv ghajtaH qempu' Dung Dochvammey? yIlegh, jIH ghaHta' poS mob; Dochvammey, nuqDaq were chaH?'”",
        22: "Thus jatlhtaH the joH joH'a', “yIlegh, jIH DichDaq lift Dung wIj ghop Daq the tuqpu', je cher Dung wIj banner Daq the ghotpu'; je chaH DIchDaq qem lIj puqloDpu' Daq chaj bosom, je lIj puqbe'pu' DIchDaq taH qengta' Daq chaj shoulders.",
        23: "joHpu' DIchDaq taH lIj nursing vavpu', je chaj queens lIj nursing mothers: chaH DIchDaq bow bIng Daq SoH tlhej chaj faces Daq the tera', je lick the dust vo' lIj qamDu'; je SoH DIchDaq Sov vetlh jIH 'oH joH'a'; je chaH 'Iv loS vaD jIH DIchDaq ghobe' taH disappointed.”",
        24: "DIchDaq the prey taH tlhappu' vo' the HoS, joq the lawful captives taH toDta'?",
        25: "'ach thus jatlhtaH joH'a', “'ach the captives vo' the HoS DIchDaq taH tlhappu' DoH, je the prey vo' the terrible DIchDaq taH toDta'; vaD jIH DichDaq contend tlhej ghaH 'Iv contends tlhej SoH, je jIH DichDaq toD lIj puqpu'.",
        26: "jIH DichDaq feed chaH 'Iv oppress SoH tlhej chaj ghaj ghab; je chaH DIchDaq taH drunken tlhej chaj ghaj 'Iw, as tlhej sweet HIq: je Hoch ghab DIchDaq Sov vetlh jIH, joH'a', 'oH lIj toDwI', je lIj Redeemer, the HoS wa' vo' Jacob.”",
    },
    50: {
        1: "Thus jatlhtaH joH'a', “nuqDaq ghaH the bill vo' lIj mother's divorce, tlhej nuq jIH ghaj lan Daj DoH? joq nuq vo' wIj creditors ghaH 'oH Daq 'Iv jIH ghaj sold SoH? yIlegh, vaD lIj iniquities were SoH sold, je vaD lIj transgressions ghaHta' lIj SoS lan DoH.",
        2: "qatlh, ghorgh jIH ghoSta', ghaHta' pa' ghobe' loD? ghorgh jIH ja', ghaHta' pa' pagh Daq jang? ghaH wIj ghop shortened Daq Hoch, vetlh 'oH ta'laHbe' redeem? joq ghaj jIH ghobe' HoS Daq toD? yIlegh, Daq wIj rebuke jIH dry Dung the biQ'a', jIH chenmoH the rivers a ngem: chaj fish stink, because pa' ghaH ghobe' bIQ, je Hegh vaD thirst.",
        3: 'jIH clothe the chal tlhej blackness, je jIH chenmoH sackcloth chaj covering.”',
        4: "The joH joH'a' ghajtaH nobpu' jIH the jat vo' chaH 'Iv 'oH taught, vetlh jIH may Sov chay' Daq sustain tlhej mu'mey ghaH 'Iv ghaH Doy': ghaH wakens po Sum po, ghaH wakens wIj qogh Daq Qoy as chaH 'Iv 'oH taught.",
        5: "The joH joH'a' ghajtaH poSmaHpu' wIj qogh, je jIH ghaHta' ghobe' lotlhqu', ghobe' tlhe'ta' DoH DoH.",
        6: "jIH nobta' wIj DoH Daq the strikers, je wIj cheeks Daq chaH 'Iv plucked litHa' the jIb; jIH ta'be' So' wIj qab vo' tuH je spitting.",
        7: "vaD the joH joH'a' DichDaq QaH jIH; vaj jIH ghaj ghobe' taH mISmoHpu': vaj ghaj jIH cher wIj qab rur a flint, je jIH Sov vetlh jIH DIchDaq ghobe' taH disappointed.",
        8: "ghaH ghaH Sum 'Iv justifies jIH; 'Iv DichDaq qem charges Daq jIH? chaw' maH Qam Dung tay': 'Iv ghaH wIj jagh? chaw' ghaH ghoS Sum Daq jIH.",
        9: "yIlegh, the joH joH'a' DichDaq QaH jIH; 'Iv ghaH ghaH 'Iv DIchDaq condemn jIH? yIlegh, Hoch chaH DIchDaq wax qan as a garment, the moth DIchDaq Sop chaH Dung.",
        10: "'Iv ghaH among SoH 'Iv fears joH'a', 'Iv obeys the ghogh vo' Daj toy'wI'? ghaH 'Iv yIttaH Daq HurghtaHghach, je ghajtaH ghobe' wov, chaw' ghaH voq Daq the pong vo' joH'a', je rely Daq Daj joH'a'.",
        11: "yIlegh, Hoch SoH 'Iv kindle a qul, 'Iv gird tlhIH'egh about tlhej torches; yIt SoH Daq the flame vo' lIj qul, je among the brands vetlh SoH ghaj kindled. SoH DIchDaq ghaj vam vo' wIj ghop; SoH DIchDaq Qot bIng Daq QoSqu'.",
    },
    51: {
        1: "“'Ij Daq jIH, SoH 'Iv tlha' after QaQtaHghach, SoH 'Iv nej joH'a': legh Daq the nagh whence SoH were pe', je Daq the 'uch vo' the pit whence SoH were dug.",
        2: "legh Daq Abraham lIj vav, je Daq Sarah 'Iv boghmoH SoH; vaD ghorgh ghaH ghaHta' 'ach wa' jIH ja' ghaH, je jIH ghurtaH ghaH, je chenmoHta' ghaH law'.",
        3: "vaD joH'a' ghajtaH comforted Zion; ghaH ghajtaH comforted Hoch Daj waste Daqmey, je ghajtaH chenmoHta' Daj ngem rur Eden, je Daj desert rur the wIjghachHom vo' joH'a'; Quch je Quchqu'taHghach DIchDaq taH tu'ta' therein, tlho'taHghach, je the ghogh vo' melody.",
        4: "“Attend Daq jIH, wIj ghotpu; je nob qogh Daq jIH, wIj Hatlh: vaD a chut DIchDaq jaH vo' vo' jIH, je jIH DichDaq establish wIj ruv vaD a wov vo' the ghotpu'.",
        5: "wIj QaQtaHghach ghaH Sum, wIj toDtaHghach ghaH ghoSta' vo', je wIj arms DIchDaq noH the ghotpu'; the islands DIchDaq loS vaD jIH, je Daq wIj arm DIchDaq chaH voq.",
        6: "Lift Dung lIj mInDu' Daq the chal, je legh Daq the tera' bIng; vaD the chal DIchDaq vanish DoH rur tlhIch, je the tera' DIchDaq wax qan rur a garment; je chaH 'Iv yIn therein DIchDaq Hegh Daq rur Da: 'ach wIj toDtaHghach DIchDaq taH reH, je wIj QaQtaHghach DIchDaq ghobe' taH abolished.",
        7: "“'Ij Daq jIH, SoH 'Iv Sov QaQtaHghach, the ghotpu Daq 'Iv tIq ghaH wIj chut; yImev taHvIp the reproach vo' loDpu', ghobe' taH dismayed Daq chaj insults.",
        8: "vaD the moth DIchDaq Sop chaH Dung rur a garment, je the worm DIchDaq Sop chaH rur wool; 'ach wIj QaQtaHghach DIchDaq taH reH, je wIj toDtaHghach Daq Hoch DISmey.”",
        9: "Awake, awake, lan Daq HoS, arm vo' joH'a'; awake, as Daq the jajmey vo' qan, the DISmey vo' ancient poHmey. 'oHbe' 'oH SoH 'Iv pe' Rahab Daq pieces, 'Iv pierced the monster?",
        10: "'oHbe' 'oH SoH 'Iv dried Dung the biQ'a', the bIQmey vo' the Dun deep; 'Iv chenmoHta' the depths vo' the biQ'a' a way vaD the toDta' Daq juS Dung?",
        11: "The ransomed vo' joH'a' DIchDaq chegh, je ghoS tlhej bomtaH Daq Zion; je everlasting Quch DIchDaq taH Daq chaj nachDu': chaH DIchDaq obtain Quchqu'taHghach je Quch; je QoSqu' je sighing DIchDaq Haw' DoH.",
        12: "“jIH, 'ach jIH, 'oH ghaH 'Iv comforts SoH: 'Iv 'oH SoH, vetlh SoH 'oH vIp vo' loD 'Iv DIchDaq Hegh, je vo' the puqloD vo' loD 'Iv DIchDaq taH chenmoHta' as grass;",
        13: "je ghaj forgotten joH'a' lIj Maker, 'Iv stretched vo' the chal, je laid the foundations vo' the tera'; je taHvIp continually Hoch the jaj because vo' the fury vo' the oppressor, ghorgh ghaH chen ready Daq Qaw'? je nuqDaq ghaH the fury vo' the oppressor?",
        14: "The captive exile DIchDaq speedily taH freed; je ghaH DIchDaq ghobe' Hegh je jaH bIng Daq the pit, ghobe' DIchDaq Daj tIr Soj fail.",
        15: "vaD jIH 'oH joH'a' lIj joH'a', 'Iv stirs Dung the biQ'a', vaj vetlh its waves roar: joH'a' vo' Armies ghaH Daj pong.",
        16: "jIH ghaj lan wIj mu'mey Daq lIj nujDu', je ghaj covered SoH Daq the QIb vo' wIj ghop, vetlh jIH may plant the chal, je lay the foundations vo' the tera', je ja' Zion, ‘SoH 'oH wIj ghotpu.'”",
        17: "Awake, awake, Qam Dung, Jerusalem, vetlh ghaj drunk Daq the ghop vo' joH'a' the HIvje' vo' Daj QeHpu'; SoH ghaj drunken the bowl vo' the HIvje' vo' staggering, je drained 'oH.",
        18: "pa' ghaH pagh Daq guide Daj among Hoch the puqloDpu' 'Iv ghaH ghajtaH qempu' vo'; ghobe' ghaH pa' vay' 'Iv takes Daj Sum the ghop among Hoch the puqloDpu' 'Iv ghaH ghajtaH qempu' Dung.",
        19: "Dochvammey cha' Dochmey ghaj qaSta' Daq SoH. 'Iv DichDaq bemoan SoH? Desolation je QIH, je the famine je the 'etlh; chay' DIchDaq jIH belmoH SoH?",
        20: "lIj puqloDpu' ghaj fainted, chaH Qot Daq the nach vo' Hoch the streets, as an antelope Daq a net; chaH 'oH teblu'ta' vo' the QeHpu' vo' joH'a', the rebuke vo' lIj joH'a'.",
        21: "vaj Qoy DaH vam, SoH afflicted, je drunken, 'ach DaH tlhej HIq:",
        22: "Thus jatlhtaH lIj joH joH'a', je lIj joH'a' 'Iv pleads the cause vo' Daj ghotpu, “yIlegh, jIH ghaj tlhappu' pa' vo' lIj ghop the HIvje' vo' staggering, 'ach the bowl vo' the HIvje' vo' wIj QeHpu'; SoH DIchDaq ghobe' latlh tlhutlh 'oH again:",
        23: "je jIH DichDaq lan 'oH Daq the ghop vo' chaH 'Iv afflict SoH, 'Iv ghaj ja'ta' Daq lIj qa', ‘Bow bIng, vetlh maH may yIt Dung SoH;' je SoH ghaj laid lIj DoH as the yav, je as the street, Daq chaH 'Iv yIt Dung.”",
    },
    52: {
        1: "Awake, awake, lan Daq lIj HoS, Zion; lan Daq lIj 'IH garments, Jerusalem, the le' veng: vaD henceforth pa' DIchDaq ghobe' latlh ghoS Daq SoH the uncircumcised je the Say'Ha'.",
        2: "Shake SoH'egh vo' the dust; Hu', ba' Daq lIj quS'a', Jerusalem: loose SoH'egh vo' the bonds vo' lIj neck, captive puqbe' vo' Zion.",
        3: "vaD thus jatlhtaH joH'a', “SoH were sold vaD pagh; je SoH DIchDaq taH toDta' Hutlh Huch.”",
        4: "vaD thus jatlhtaH the joH joH'a', “wIj ghotpu mejta' bIng Daq the wa'Dich Daq Egypt Daq sojourn pa': je the Assyrian ghajtaH Suvta' chaH Hutlh cause.",
        5: "“DaH vaj, nuq ta' jIH naDev,” jatlhtaH joH'a', “leghtaH vetlh wIj ghotpu 'oH tlhappu' DoH vaD pagh? chaH 'Iv rule Dung chaH mock,” jatlhtaH joH'a', “je wIj pong continually Hoch the jaj ghaH blasphemed.",
        6: "vaj wIj ghotpu DIchDaq Sov wIj pong: vaj chaH DIchDaq Sov Daq vetlh jaj vetlh jIH 'oH ghaH 'Iv ta'taH jatlh; yIlegh, 'oH ghaH jIH.”",
        7: "chay' 'IH Daq the Hudmey 'oH the qamDu' vo' ghaH 'Iv brings QaQ news, 'Iv publishes roj, 'Iv brings QaQ news vo' QaQ, 'Iv publishes toDtaHghach, 'Iv jatlhtaH Daq Zion, “lIj joH'a' reigns!”",
        8: "The ghogh vo' lIj watchmen! chaH lift Dung the ghogh, tay' ta' chaH bom; vaD chaH DIchDaq legh mIn Daq mIn, ghorgh joH'a' returns Daq Zion.",
        9: "ghor vo' Daq Quch, bom tay', SoH waste Daqmey vo' Jerusalem; vaD joH'a' ghajtaH comforted Daj ghotpu, ghaH ghajtaH toDta' Jerusalem.",
        10: "joH'a' ghajtaH chenmoHta' bare Daj le' arm Daq the mInDu' vo' Hoch the tuqpu'; je Hoch the ends vo' the tera' ghaj leghpu' the toDtaHghach vo' maj joH'a'.",
        11: "mej, mej, jaH pa' vo' pa', touch ghobe' Say'Ha' Doch! jaH pa' vo' the midst vo' Daj! Cleanse tlhIH'egh, SoH 'Iv SIQ the Dujmey vo' joH'a'.",
        12: "vaD SoH DIchDaq ghobe' jaH pa' Daq haste, ghobe' DIchDaq SoH jaH Sum flight: vaD joH'a' DichDaq jaH qaSpa' SoH; je the joH'a' vo' Israel DichDaq taH lIj rear guard.",
        13: "yIlegh, wIj toy'wI' DIchDaq Da wisely, ghaH DIchDaq taH exalted je qengta' Dung, je DIchDaq taH very jen.",
        14: "rur as law' were astonished Daq SoH (Daj appearance ghaHta' marred latlh than vay' loD, je Daj form latlh than the puqloDpu' vo' loDpu'),",
        15: "vaj DIchDaq ghaH sprinkle law' tuqpu'; joHpu' DIchDaq shut chaj mouths Daq ghaH: vaD vetlh nuq ghajta' ghobe' taH ja'ta' chaH DIchDaq chaH legh; je vetlh nuq chaH ghajta' ghobe' Qoyta' DIchDaq chaH understand.",
    },
    53: {
        1: "'Iv ghajtaH Harta' maj message? Daq 'Iv ghajtaH the arm vo' joH'a' taH 'angta'?",
        2: "vaD ghaH grew Dung qaSpa' ghaH as a tender plant, je as a root pa' vo' dry yav. ghaH ghajtaH ghobe' form ghobe' comeliness. ghorgh maH legh ghaH, pa' ghaH ghobe' 'IhtaHghach vetlh maH should neH ghaH.",
        3: "ghaH ghaHta' muSqu', je rejected Sum loDpu'; a loD vo' suffering, je acquainted tlhej disease. ghaH ghaHta' muSqu' as wa' vo' 'Iv loDpu' So' chaj qab; je maH ta'be' respect ghaH.",
        4: "DIch ghaH ghajtaH borne maj sickness, je qengta' maj suffering; yet maH considered ghaH plagued, struck Sum joH'a', je afflicted.",
        5: "'ach ghaH ghaHta' pierced vaD maj transgressions. ghaH ghaHta' crushed vaD maj iniquities. The punishment vetlh qempu' maj roj ghaHta' Daq ghaH; je Sum Daj QIDpu'ghachmey maH 'oH healed.",
        6: "Hoch maH rur Suy' ghaj ghoSta' astray. Hoch ghajtaH tlhe'ta' Daq Daj ghaj way; je joH'a' ghajtaH laid Daq ghaH the He'taHghach vo' maH Hoch.",
        7: "ghaH ghaHta' Suvta', yet ghorgh ghaH ghaHta' afflicted ghaH ta'be' poSmoH Daj nujDu'. As a lamb vetlh ghaH led Daq the HoHqu', je as a Suy' vetlh qaSpa' its shearers ghaH mute, vaj ghaH ta'be' poSmoH Daj nujDu'.",
        8: "ghaH ghaHta' tlhappu' DoH Sum oppression je yoj; je as vaD Daj generation, 'Iv considered vetlh ghaH ghaHta' pe' litHa' pa' vo' the puH vo' the yIntaH je mup vaD the disobedience vo' wIj ghotpu?",
        9: "chaH chenmoHta' Daj grave tlhej the mIgh, je tlhej a rich loD Daq Daj Hegh; although ghaH ghajta' ta'pu' ghobe' violence, ghobe' ghaHta' vay' deceit Daq Daj nujDu'.",
        10: "Yet 'oH pleased joH'a' Daq bruise ghaH. ghaH ghajtaH caused ghaH Daq suffer. ghorgh SoH chenmoH Daj qa' an cha'nob vaD yem, ghaH DIchDaq legh Daj tIr. ghaH DIchDaq prolong Daj jajmey, je the pleasure vo' joH'a' DIchDaq chep Daq Daj ghop.",
        11: "After the suffering vo' Daj qa', ghaH DichDaq legh the wov { Note: vaj read the Heghpu' biQ'a' Scrolls je Septuagint. Masoretic Text omits “the wov”. } je taH satisfied. wIj QaQtaHghach toy'wI' DichDaq justify law' Sum the Sov vo' himself; je ghaH DichDaq SIQ chaj iniquities.",
        12: "vaj DichDaq jIH divide ghaH a portion tlhej the Dun, je ghaH DIchDaq divide the non tlhej the HoS; because ghaH poured pa' Daj qa' Daq Hegh, je ghaHta' toghta' tlhej the yemwI'pu'; yet ghaH boghmoH the yem vo' law', je chenmoHta' intercession vaD the yemwI'pu'.",
    },
    54: {
        1: "“bom, barren, SoH 'Iv ta'be' SIQ; ghor vo' Daq bomtaH, je SaQ QoymoHlaHbogh, SoH 'Iv ta'ta' ghobe' travail tlhej puq: vaD latlh 'oH the puqpu' vo' the moB than the puqpu' vo' the married be'nal,” jatlhtaH joH'a'.",
        2: "“Enlarge the Daq vo' lIj juHHom, je chaw' chaH stretch vo' the curtains vo' lIj habitations; yImev spare: lengthen lIj cords, je strengthen lIj stakes.",
        3: "vaD SoH DIchDaq ngeH pa' Daq the nIH ghop je Daq the poS; je lIj tIr DIchDaq ghaj the tuqpu', je chenmoH the moB vengmey Daq taH inhabited.",
        4: "“yImev taH vIp; vaD SoH DIchDaq ghobe' taH tuH: ghobe' taH mISmoHpu'; vaD SoH DIchDaq ghobe' taH disappointed: vaD SoH DIchDaq forget the tuH vo' lIj youth; je the reproach vo' lIj widowhood SoH DIchDaq qaw ghobe' latlh.",
        5: "vaD lIj Maker ghaH lIj loDnal; joH'a' vo' Armies ghaH Daj pong: je the le' wa' vo' Israel ghaH lIj Redeemer; the joH'a' vo' the Hoch tera' DIchDaq ghaH taH ja'.",
        6: "vaD joH'a' ghajtaH ja' SoH as a be'nal lonta' je grieved Daq qa', 'ach a be'nal vo' youth, ghorgh ghaH ghaH chuH litHa',” jatlhtaH lIj joH'a'.",
        7: "“vaD a mach moment ghaj jIH lonta' SoH; 'ach tlhej Dun mercies DichDaq jIH tay'moH SoH.",
        8: "Daq overflowing QeHpu' jIH hid wIj qab vo' SoH vaD a moment; 'ach tlhej everlasting muSHa'taH pung DichDaq jIH ghaj pung Daq SoH,” jatlhtaH joH'a' lIj Redeemer.",
        9: "“vaD vam ghaH rur the bIQmey vo' Noah Daq jIH; vaD as jIH ghaj sworn vetlh the bIQmey vo' Noah DIchDaq ghobe' latlh jaH Dung the tera', vaj ghaj jIH sworn vetlh jIH DichDaq ghobe' taH angry tlhej SoH, ghobe' rebuke SoH.",
        10: "vaD the Hudmey may mej, je the hills taH teqta'; 'ach wIj muSHa'taH pung DIchDaq ghobe' mej vo' SoH, ghobe' DIchDaq wIj lay' vo' roj taH teqta',” jatlhtaH joH'a' 'Iv ghajtaH pung Daq SoH.",
        11: "“SoH afflicted, tossed tlhej storms, je ghobe' comforted, yIlegh, jIH DichDaq cher lIj naghmey Daq 'IH colors, je lay lIj foundations tlhej sapphires.",
        12: "jIH DichDaq chenmoH lIj pinnacles vo' rubies, je lIj lojmItmey vo' sparkling jewels, je Hoch lIj walls vo' precious naghmey.",
        13: "Hoch lIj puqpu' DIchDaq taH taught vo' joH'a'; je Dun DIchDaq taH the roj vo' lIj puqpu'.",
        14: "Daq QaQtaHghach SoH DIchDaq taH established: SoH DIchDaq taH Hop vo' oppression, vaD SoH DIchDaq ghobe' taH vIp; je vo' ghIjvIptaH, vaD 'oH DIchDaq ghobe' ghoS Sum SoH.",
        15: "yIlegh, chaH may tay'moH tay', 'ach ghobe' Sum jIH: 'Iv DIchDaq tay'moH tay' Daq SoH DIchDaq pum because vo' SoH.",
        16: "“yIlegh, jIH ghaj created the smith 'Iv blows the qul vo' coals, je brings vo' a weapon vaD Daj vum; je jIH ghaj created the waster Daq Qaw'.",
        17: "ghobe' weapon vetlh ghaH formed Daq SoH DichDaq prevail; je SoH DichDaq condemn Hoch jat vetlh rises Daq SoH Daq yoj. vam ghaH the heritage vo' the toy'wI'pu' vo' joH'a', je chaj QaQtaHghach nuq ghaH vo' jIH,” jatlhtaH joH'a'.",
    },
    55: {
        1: "“ghoS, Hoch 'Iv thirsts, Daq the bIQmey! ghoS, ghaH 'Iv ghajtaH ghobe' Huch, buy, je Sop! HIja', ghoS, buy HIq je milk Hutlh Huch je Hutlh price.",
        2: "qatlh ta' SoH spend Huch vaD vetlh nuq ghaH ghobe' tIr Soj? je lIj labor vaD vetlh nuq ta'be' yonmoH? 'Ij diligently Daq jIH, je Sop SoH vetlh nuq ghaH QaQ, je chaw' lIj qa' tIv itself Daq fatness.",
        3: "tlhe' lIj qogh, je ghoS Daq jIH; Qoy, je lIj qa' DIchDaq yIn: je jIH DichDaq chenmoH an everlasting lay' tlhej SoH, 'ach the sure mercies vo' David.",
        4: "yIlegh, jIH ghaj nobpu' ghaH vaD a witness Daq the ghotpu', a leader je commander Daq the ghotpu'.",
        5: "yIlegh, SoH DIchDaq ja' a Hatlh vetlh SoH yImev Sov; je a Hatlh vetlh ta'be' Sov SoH DIchDaq run Daq SoH, because vo' joH'a' lIj joH'a', je vaD the le' wa' vo' Israel; vaD ghaH ghajtaH glorified SoH.”",
        6: "nej joH'a' qaStaHvIS ghaH may taH tu'ta'; ja' SoH Daq ghaH qaStaHvIS ghaH ghaH Sum:",
        7: "chaw' the mIgh lon Daj way, je the unrighteous loD Daj thoughts; je chaw' ghaH chegh Daq joH'a', je ghaH DichDaq ghaj pung Daq ghaH; je Daq maj joH'a', vaD ghaH DichDaq abundantly pardon.",
        8: "“vaD wIj thoughts 'oH ghobe' lIj thoughts, ghobe' 'oH lIj Hemey wIj Hemey,” jatlhtaH joH'a'.",
        9: "“vaD as the chal 'oH higher than the tera', vaj 'oH wIj Hemey higher than lIj Hemey, je wIj thoughts than lIj thoughts.",
        10: "vaD as the rain choltaH bIng je the chuchHommey vo' the sky, je ta'be' chegh pa', 'ach bIQmey the tera', je chen 'oH qem vo' je bud, je nob tIr Daq the sower je tIr Soj Daq the eater;",
        11: "vaj DIchDaq wIj mu' taH vetlh goes vo' pa' vo' wIj nujDu': 'oH DIchDaq ghobe' chegh Daq jIH void, 'ach 'oH DIchDaq accomplish vetlh nuq jIH please, je 'oH DIchDaq chep Daq the Doch jIH ngeHta' 'oH Daq ta'.",
        12: "vaD SoH DIchDaq jaH pa' tlhej Quch, je taH led vo' tlhej roj: the Hudmey je the hills DIchDaq ghor vo' qaSpa' SoH Daq bomtaH; je Hoch the Sormey vo' the fields DIchDaq clap chaj ghopmey.",
        13: "Instead vo' the thorn DIchDaq ghoS Dung the fir Sor; je instead vo' the brier DIchDaq ghoS Dung the myrtle Sor: je 'oH DIchDaq taH Daq joH'a' vaD a pong, vaD an everlasting sign vetlh DIchDaq ghobe' taH pe' litHa'.”",
    },
    56: {
        1: "Thus jatlhtaH joH'a', “pol ruv, je ta' QaQtaHghach; vaD wIj toDtaHghach ghaH Sum Daq ghoS, je wIj QaQtaHghach Daq taH 'angta'.",
        2: "ghurtaH ghaH the loD 'Iv ta'taH vam, je the puqloD vo' loD 'Iv holds 'oH fast; 'Iv keeps the jaj SochDIch vo' profaning 'oH, je keeps Daj ghop vo' doing vay' mIghtaHghach.”",
        3: "ghobe' chaw' the foreigner, 'Iv ghajtaH joined himself Daq joH'a', jatlh, ja'ta', “joH'a' DichDaq DIch separate jIH vo' Daj ghotpu;” ghobe' chaw' the eunuch jatlh, “yIlegh, jIH 'oH a dry Sor.”",
        4: "vaD thus jatlhtaH joH'a', “Daq the eunuchs 'Iv pol wIj Sabbaths, je choose the Dochmey vetlh please jIH, je 'uch fast wIj lay':",
        5: "Daq chaH jIH DichDaq nob Daq wIj tuq je within wIj walls a memorial je a pong better than vo' puqloDpu' je vo' puqbe'pu'; jIH DichDaq nob chaH an everlasting pong, vetlh DIchDaq ghobe' taH pe' litHa'.",
        6: "je the foreigners 'Iv join themselves Daq joH'a', Daq minister Daq ghaH, je Daq muSHa' the pong vo' joH'a', Daq taH Daj toy'wI'pu', Hoch 'Iv keeps the jaj SochDIch vo' profaning 'oH, je holds fast wIj lay';",
        7: "'ach chaH DichDaq jIH qem Daq wIj le' HuD, je chenmoH chaH joyful Daq wIj tuq vo' tlhobtaHghach: chaj meQqu'pu' nobmey je chaj nobmey DIchDaq taH accepted Daq wIj lalDanta' Daq; vaD wIj tuq DIchDaq taH ja' a tuq vo' tlhobtaHghach vaD Hoch ghotpu'.”",
        8: "The joH joH'a', 'Iv gathers the outcasts vo' Israel, jatlhtaH, “Yet DichDaq jIH tay'moH others Daq ghaH, je Daj ghaj 'Iv 'oH boSta'.”",
        9: "Hoch SoH Ha'DIbaH vo' the yotlh, ghoS Daq Sop, HIja', Hoch SoH Ha'DIbaH Daq the forest.",
        10: "Daj watchmen 'oH blind, chaH 'oH Hoch Hutlh Sov; chaH 'oH Hoch mute dogs, chaH ta'laHbe' bark; dreaming, lying bIng, muSHa'taH Daq slumber.",
        11: "HIja', the dogs 'oH greedy, chaH laH never ghaj yap; je Dochvammey 'oH shepherds 'Iv ta'laHbe' understand: chaH ghaj Hoch tlhe'ta' Daq chaj ghaj way, each wa' Daq Daj gain, vo' Hoch quarter.",
        12: "“ghoS,” jatlh chaH, “jIH DichDaq tlhap HIq, je maH DichDaq fill ourselves tlhej HoS tlhutlh; je wa'leS DIchDaq taH as vam jaj, a jaj Dun beyond juv.”",
    },
    57: {
        1: "The QaQtaHghach perishes, je ghobe' loD lays 'oH Daq tIq; je merciful loDpu' 'oH tlhappu' DoH, pagh considering vetlh the QaQtaHghach ghaH tlhappu' DoH vo' the mIghtaHghach Daq ghoS.",
        2: "ghaH enters Daq roj; chaH leS Daq chaj beds, each wa' 'Iv yIttaH Daq Daj uprightness.",
        3: "“'ach draw Sum naDev, SoH puqloDpu' vo' the sorceress, the tIr vo' the voqHa'moHwI' je the naybe'wI'.",
        4: "Daq 'Iv ta' SoH sport tlhIH'egh? Daq 'Iv ta' SoH chenmoH a wide nujDu', je stick pa' lIj jat? Aren't SoH puqpu' vo' disobedience, a tIr vo' falsehood,",
        5: "SoH 'Iv inflame tlhIH'egh among the Sor'a'mey, bIng Hoch SuD Sor; 'Iv HoH the puqpu' Daq the valleys, bIng the clefts vo' the rocks?",
        6: "Among the smooth naghmey vo' the ngech ghaH lIj portion; chaH, chaH 'oH lIj lot; SoH ghaj 'ach poured a tlhutlh cha'nob Daq chaH. SoH ghaj nobta' an cha'nob. DIchDaq jIH taH appeased vaD Dochvammey Dochmey?",
        7: "Daq a jen je lofty HuD SoH ghaj cher lIj bed; pa' je SoH mejta' Dung Daq nob sacrifice.",
        8: "Behind the doors je the posts SoH ghaj cher Dung lIj memorial: vaD SoH ghaj uncovered Daq someone je jIH, je ghaj ghoSta' Dung; SoH ghaj enlarged lIj bed, je chenmoHta' SoH a lay' tlhej chaH: SoH loved chaj bed nuqDaq SoH leghta' 'oH.",
        9: "SoH mejta' Daq the joH tlhej Hergh, je ta'ta' increase lIj perfumes, je ta'ta' ngeH lIj ambassadors Hop litHa', je debased SoH'egh 'ach Daq Sheol { Note: Sheol ghaH the Daq vo' the Heghpu'. }.",
        10: "SoH were wearied tlhej the length vo' lIj way; yet SoH ta'be' jatlh, ‘'oH ghaH Daq lI'be'.' SoH tu'ta' a reviving vo' lIj HoS; vaj SoH weren't puj.",
        11: "“vo' 'Iv ghaj SoH taH vIp je Daq taHvIp, vetlh SoH Qot, je ghaj ghobe' remembered jIH, ghobe' laid 'oH Daq lIj tIq? ghajbe' jIH held wIj roj 'ach vo' tIq poH, je SoH yImev taHvIp jIH?",
        12: "jIH DichDaq declare lIj QaQtaHghach; je as vaD lIj vum, chaH DIchDaq ghobe' profit SoH.",
        13: "ghorgh SoH SaQ, chaw' chaH 'Iv SoH ghaj boSta' toD SoH; 'ach the SuS DIchDaq tlhap chaH, a breath DIchDaq carry chaH Hoch DoH: 'ach ghaH 'Iv takes lulIgh Daq jIH DIchDaq ghaj the puH, je DIchDaq inherit wIj le' HuD.”",
        14: "ghaH DichDaq jatlh, “chuH Dung, chuH Dung, ghuH the way, tlhap Dung the stumbling-block pa' vo' the way vo' wIj ghotpu.”",
        15: "vaD thus jatlhtaH the jen je lofty wa' 'Iv inhabits eternity, 'Iv pong ghaH le': “jIH yIn Daq the jen je le' Daq, tlhej ghaH je 'Iv ghaH vo' a contrite je humble qa', Daq revive the qa' vo' the humble, je Daq revive the tIq vo' the contrite.",
        16: "vaD jIH DichDaq ghobe' contend reH, ghobe' DichDaq jIH taH always angry; vaD the qa' would puj qaSpa' jIH, je the qa'pu' 'Iv jIH ghaj chenmoHta'.",
        17: "vaD the He'taHghach vo' Daj covetousness ghaHta' jIH angry, je struck ghaH; jIH hid wIj qab je ghaHta' angry; je ghaH mejta' Daq 'ur Daq the way vo' Daj tIq.",
        18: "jIH ghaj leghpu' Daj Hemey, je DichDaq heal ghaH: jIH DichDaq Dev ghaH je, je nobHa' comforts Daq ghaH je Daq Daj mourners.",
        19: "jIH create the baQ vo' the wuSDu': roj, roj, Daq ghaH 'Iv ghaH Hop litHa' je Daq ghaH 'Iv ghaH Sum,” jatlhtaH joH'a'; “je jIH DichDaq heal chaH.”",
        20: "'ach the mIgh 'oH rur the troubled biQ'a'; vaD 'oH ta'laHbe' leS, je its bIQmey chuH Dung mire je dirt.",
        21: "“pa' ghaH ghobe' roj,” jatlhtaH wIj joH'a', “vaD the mIgh.”",
    },
    58: {
        1: "“SaQ QoymoHlaHbogh, yImev spare, lift Dung lIj ghogh rur a trumpet, je declare Daq wIj ghotpu chaj disobedience, je Daq the tuq vo' Jacob chaj yemmey.",
        2: "Yet chaH nej jIH daily, je tIv Daq Sov wIj Hemey: as a Hatlh vetlh ta'ta' QaQtaHghach, je ta'be' lon the ordinance vo' chaj joH'a', chaH tlhob vo' jIH QaQtaHghach judgments; chaH tIv Daq draw Sum Daq joH'a'.",
        3: "‘qatlh ghaj maH fasted,' jatlh chaH, ‘je SoH yImev legh? qatlh ghaj maH afflicted maj qa', je SoH tlhap ghobe' Sov?' “yIlegh, Daq the jaj vo' lIj fast SoH tu' pleasure, je exact Hoch lIj labors.",
        4: "yIlegh, SoH fast vaD strife je contention, je Daq mup tlhej the fist vo' mIghtaHghach: SoH yImev fast vam jaj vaj as Daq chenmoH lIj ghogh Daq taH Qoyta' Daq jen.",
        5: "ghaH such the fast vetlh jIH ghaj wIvpu'? the jaj vaD a loD Daq afflict Daj qa'? ghaH 'oH Daq bow bIng Daj nach as a rush, je Daq ngeH sackcloth je ashes bIng ghaH? DichDaq SoH ja' vam a fast, je an acceptable jaj Daq joH'a'?",
        6: "“'oHbe' vam the fast vetlh jIH ghaj wIvpu': Daq loose the bonds vo' mIghtaHghach, Daq undo the baghmoHwI' vo' the yoke, je Daq chaw' the Suvta' jaH free, je vetlh SoH ghor Hoch yoke?",
        7: "'oHbe' 'oH Daq distribute lIj tIr Soj Daq the hungry, je vetlh SoH qem the mIpHa' 'Iv 'oH chuH pa' Daq lIj tuq? ghorgh SoH legh the naked, vetlh SoH So' ghaH; je vetlh SoH ghobe' So' SoH'egh vo' lIj ghaj ghab?",
        8: "vaj lIj wov DIchDaq ghor vo' as the po, je lIj healing DIchDaq spring vo' speedily; je lIj QaQtaHghach DIchDaq jaH qaSpa' SoH; the batlh vo' joH'a' DIchDaq taH lIj rear guard.",
        9: "vaj SoH DIchDaq ja', je joH'a' DichDaq jang; SoH DIchDaq SaQ, je ghaH DichDaq jatlh, ‘naDev jIH 'oH.' “chugh SoH tlhap DoH vo' the midst vo' SoH the yoke, the putting vo' vo' the finger, je speaking wickedly;",
        10: "je chugh SoH draw pa' lIj qa' Daq the hungry, je yonmoH the afflicted qa': vaj lIj wov DIchDaq Hu' Daq HurghtaHghach, je lIj obscurity taH as the DungluQ;",
        11: "je joH'a' DichDaq guide SoH continually, je yonmoH lIj qa' Daq dry Daqmey, je chenmoH HoS lIj HomDu'; je SoH DIchDaq taH rur a watered wIjghachHom, je rur a spring vo' bIQ, 'Iv bIQmey yImev fail.",
        12: "chaH 'Iv DIchDaq taH vo' SoH DIchDaq chen the qan waste Daqmey; SoH DIchDaq raise Dung the foundations vo' law' DISmey; je SoH DIchDaq taH ja' The repairer vo' the breach, The restorer vo' Hemey Daq yIn Daq.",
        13: "“chugh SoH tlhe' DoH lIj qam vo' the jaj SochDIch, vo' doing lIj pleasure Daq wIj le' jaj; je ja' the jaj SochDIch a tIv, je the le' vo' joH'a' honorable; je DIchDaq quv 'oH, ghobe' doing lIj ghaj Hemey, ghobe' finding lIj ghaj pleasure, ghobe' speaking lIj ghaj mu'mey:",
        14: "vaj SoH DIchDaq tIv SoH'egh Daq joH'a'; je jIH DichDaq chenmoH SoH Daq ride Daq the jen Daqmey vo' the tera'; je jIH DichDaq feed SoH tlhej the heritage vo' Jacob lIj vav:” vaD the nujDu' vo' joH'a' ghajtaH jatlhpu' 'oH.",
    },
    59: {
        1: "yIlegh, joH'a' ghop ghaH ghobe' shortened, vetlh 'oH ta'laHbe' toD; ghobe' Daj qogh 'ugh, vetlh 'oH ta'laHbe' Qoy:",
        2: "'ach lIj iniquities ghaj separated joj SoH je lIj joH'a', je lIj yemmey ghaj hidden Daj qab vo' SoH, vaj vetlh ghaH DichDaq ghobe' Qoy.",
        3: "vaD lIj ghopmey 'oH defiled tlhej 'Iw, je lIj fingers tlhej He'taHghach; lIj wuSDu' ghaj jatlhpu' lies, lIj jat mutters mIghtaHghach.",
        4: "pagh sues Daq QaQtaHghach, je pagh pleads Daq vIt: chaH voq Daq vanity, je jatlh lies; chaH conceive mischief, je qem vo' He'taHghach.",
        5: "chaH hatch adders' eggs, je weave the spider's web: ghaH 'Iv eats vo' chaj eggs dies; je vetlh nuq ghaH crushed breaks pa' Daq a viper.",
        6: "chaj webs DIchDaq ghobe' moj garments, ghobe' DIchDaq chaH So' themselves tlhej chaj vum: chaj vum 'oH vum vo' He'taHghach, je the vang vo' violence ghaH Daq chaj ghopmey.",
        7: "chaj qamDu' run Daq mIghtaHghach, je chaH chenmoH haste Daq shed innocent 'Iw: chaj thoughts 'oH thoughts vo' He'taHghach; desolation je QIH 'oH Daq chaj Hemey.",
        8: "The way vo' roj chaH yImev Sov; je pa' ghaH ghobe' ruv Daq chaj goings: chaH ghaj chenmoHta' chaH crooked Hemey; 'Iv goes therein ta'taH ghobe' Sov roj.",
        9: "vaj ghaH ruv Hop vo' maH, ghobe' ta'taH QaQtaHghach overtake maH: maH legh vaD wov, 'ach, yIlegh, HurghtaHghach; vaD brightness, 'ach maH yIt Daq obscurity.",
        10: "maH grope vaD the reD rur the blind; HIja', maH grope as chaH 'Iv ghaj ghobe' mInDu': maH stumble Daq DungluQ as Daq the twilight; among chaH 'Iv 'oH lusty maH 'oH as Heghpu' loDpu'.",
        11: "maH roar Hoch rur bears, je moan 'oy' rur doves: maH legh vaD ruv, 'ach pa' ghaH pagh; vaD toDtaHghach, 'ach 'oH ghaH Hop litHa' vo' maH.",
        12: "vaD maj transgressions 'oH multiplied qaSpa' SoH, je maj yemmey testify Daq maH; vaD maj transgressions 'oH tlhej maH, je as vaD maj iniquities, maH Sov chaH:",
        13: "transgressing je denying joH'a', je turning DoH vo' following maj joH'a', speaking oppression je Daw', conceiving je uttering vo' the tIq mu'mey vo' falsehood.",
        14: "ruv ghaH tlhe'ta' DoH DoH, je QaQtaHghach stands afar litHa'; vaD vIt ghaH fallen Daq the street, je uprightness ta'laHbe' 'el.",
        15: "HIja', vIt ghaH lacking; je ghaH 'Iv departs vo' mIghtaHghach chen himself a prey. joH'a' leghta' 'oH, je 'oH displeased ghaH vetlh pa' ghaHta' ghobe' ruv.",
        16: "ghaH leghta' vetlh pa' ghaHta' ghobe' loD, je wondered vetlh pa' ghaHta' ghobe' intercessor: vaj Daj ghaj arm qempu' toDtaHghach Daq ghaH; je Daj QaQtaHghach, 'oH upheld ghaH.",
        17: "ghaH lan Daq QaQtaHghach as a breastplate, je a helmet vo' toDtaHghach Daq Daj nach; je ghaH lan Daq garments vo' vengeance vaD Sut, je ghaHta' clad tlhej zeal as a mantle.",
        18: "According Daq chaj deeds, accordingly ghaH DichDaq repay, QeHpu' Daq Daj jaghpu', recompense Daq Daj jaghpu'; Daq the islands ghaH DichDaq repay recompense.",
        19: "vaj DIchDaq chaH taHvIp the pong vo' joH'a' vo' the pemHov 'et, je Daj batlh vo' the rising vo' the pemHov; vaD ghaH DichDaq ghoS as a rushing stream, nuq the breath vo' joH'a' drives.",
        20: "“A Redeemer DichDaq ghoS Daq Zion, je Daq chaH 'Iv tlhe' vo' disobedience Daq Jacob,” jatlhtaH joH'a'.",
        21: "“As vaD jIH, vam ghaH wIj lay' tlhej chaH,” jatlhtaH joH'a'. “wIj qa' 'Iv ghaH Daq SoH, je wIj mu'mey nuq jIH ghaj lan Daq lIj nujDu', DIchDaq ghobe' mej pa' vo' lIj nujDu', ghobe' pa' vo' the nujDu' vo' lIj tIr, ghobe' pa' vo' the nujDu' vo' lIj tIr's seed,” jatlhtaH joH'a', “vo' henceforth je reH.”",
    },
    60: {
        1: "“Hu', shine; vaD lIj wov ghaH ghoS, je the batlh vo' joH'a' ghaH risen Daq SoH.",
        2: "vaD, yIlegh, HurghtaHghach DIchDaq So' the tera', je gross HurghtaHghach the ghotpu'; 'ach joH'a' DichDaq Hu' Daq SoH, je Daj batlh DIchDaq taH leghpu' Daq SoH.",
        3: "tuqpu' DIchDaq ghoS Daq lIj wov, je joHpu' Daq the brightness vo' lIj rising.",
        4: "“Lift Dung lIj mInDu' Hoch around, je legh: chaH Hoch tay'moH themselves tay', chaH ghoS Daq SoH; lIj puqloDpu' DIchDaq ghoS vo' Hop, je lIj puqbe'pu' DIchDaq taH qengta' Daq the arms.",
        5: "vaj SoH DIchDaq legh je taH radiant, je lIj tIq DIchDaq thrill je taH enlarged; because the abundance vo' the biQ'a' DIchDaq taH tlhe'ta' Daq SoH, the wealth vo' the tuqpu' DIchDaq ghoS Daq SoH.",
        6: "The qevmey vo' camels DIchDaq So' SoH, the dromedaries vo' Midian je Ephah; Hoch chaH vo' Sheba DIchDaq ghoS; chaH DIchDaq qem SuD baS je frankincense, je DIchDaq proclaim the praises vo' joH'a'.",
        7: "Hoch the flocks vo' Kedar DIchDaq taH boSta' tay' Daq SoH, the 'ermey vo' Nebaioth DIchDaq minister Daq SoH; chaH DIchDaq ghoS Dung tlhej acceptance Daq wIj lalDanta' Daq; je jIH DichDaq glorify the tuq vo' wIj batlh.",
        8: "“'Iv 'oH Dochvammey 'Iv puv as a cloud, je as the doves Daq chaj windows?",
        9: "DIch the islands DIchDaq loS vaD jIH, je the ships vo' Tarshish wa'Dich, Daq qem lIj puqloDpu' vo' Hop, chaj baS chIS je chaj SuD baS tlhej chaH, vaD the pong vo' joH'a' lIj joH'a', je vaD the le' wa' vo' Israel, because ghaH ghajtaH glorified SoH.",
        10: "“Foreigners DIchDaq chen Dung lIj walls, je chaj joHpu' DIchDaq minister Daq SoH: vaD Daq wIj QeHpu' jIH struck SoH, 'ach Daq wIj favor ghaj jIH ghajta' pung Daq SoH.",
        11: "lIj lojmItmey je DIchDaq taH poSmoH continually; chaH DIchDaq ghobe' taH shut jaj ghobe' ram; vetlh loDpu' may qem Daq SoH the wealth vo' the tuqpu', je chaj joHpu' led captive.",
        12: "vaD vetlh Hatlh je kingdom vetlh DichDaq ghobe' toy' SoH DIchDaq chIlqu'; HIja', chaH tuqpu' DIchDaq taH utterly wasted.",
        13: "“The batlh vo' Lebanon DIchDaq ghoS Daq SoH, the fir Sor, the pine, je the box Sor tay', Daq 'IhchoHmoH the Daq vo' wIj Daq QaD; je jIH DichDaq chenmoH the Daq vo' wIj qamDu' glorious.",
        14: "The puqloDpu' vo' chaH 'Iv afflicted SoH DIchDaq ghoS bending Daq SoH; je Hoch chaH 'Iv muSqu' SoH DIchDaq bow themselves bIng Daq the soles vo' lIj qamDu'; je chaH DIchDaq ja' SoH The veng vo' joH'a', The Zion vo' the le' wa' vo' Israel.",
        15: "“Whereas SoH ghaj taH lonta' je hated, vaj vetlh ghobe' loD juSta' vegh SoH, jIH DichDaq chenmoH SoH an eternal excellency, a Quch vo' law' DISmey.",
        16: "SoH DIchDaq je suck the milk vo' the tuqpu', je DIchDaq nurse vo' royal breasts; je SoH DIchDaq Sov vetlh jIH, joH'a', 'oH lIj toDwI', je lIj Redeemer, the HoS wa' vo' Jacob.",
        17: 'vaD brass jIH DichDaq qem SuD baS, je vaD iron jIH DichDaq qem baS chIS, je vaD wood brass, je vaD naghmey iron. jIH DichDaq je chenmoH lIj officers roj, je QaQtaHghach lIj ruler.',
        18: "Violence DIchDaq ghobe' latlh taH Qoyta' Daq lIj puH, desolation ghobe' QIH within lIj veHmey; 'ach SoH DIchDaq ja' lIj walls toDtaHghach, je lIj lojmItmey naD.",
        19: "The pemHov DIchDaq taH ghobe' latlh lIj wov Sum jaj; ghobe' vaD brightness DIchDaq the maS nob wov Daq SoH: 'ach joH'a' DichDaq taH Daq SoH an everlasting wov, je lIj joH'a' lIj batlh.",
        20: "lIj pemHov DIchDaq ghobe' latlh jaH bIng, ghobe' DIchDaq lIj maS withdraw itself; vaD joH'a' DichDaq taH lIj everlasting wov, je the jajmey vo' lIj mourning DIchDaq taH ended.",
        21: "lIj ghotpu je DIchDaq taH Hoch QaQtaHghach; chaH DIchDaq inherit the puH reH, the branch vo' wIj planting, the vum vo' wIj ghopmey, vetlh jIH may taH glorified.",
        22: "The mach wa' DIchDaq moj a SaD, je the mach wa' a HoS Hatlh; jIH, joH'a', DichDaq hasten 'oH Daq its poH.”",
    },
    61: {
        1: "The qa' vo' the joH joH'a' ghaH Daq jIH; because joH'a' ghajtaH ngoHta' jIH Daq preach QaQ news Daq the humble. ghaH ghajtaH ngeHta' jIH Daq bind Dung the brokenhearted, Daq proclaim liberty Daq the captives, je release Daq chaH 'Iv 'oH bagh;",
        2: "Daq proclaim the DIS vo' joH'a' favor, je the jaj vo' vengeance vo' maj joH'a'; Daq belmoH Hoch 'Iv mourn;",
        3: "Daq appoint Daq chaH 'Iv mourn Daq Zion, Daq nob Daq chaH a garland vaD ashes, the Hergh vo' Quch vaD mourning, the garment vo' naD vaD the qa' vo' heaviness; vetlh chaH may taH ja' Sormey vo' QaQtaHghach, the planting vo' joH'a', vetlh ghaH may taH glorified.",
        4: "chaH DIchDaq chen the qan woDtaH, chaH DIchDaq raise Dung the former desolations, je chaH DIchDaq repair the waste vengmey, the desolations vo' law' DISmey.",
        5: "novpu' DIchDaq Qam je feed lIj flocks, je foreigners DIchDaq taH lIj plowmen je lIj vinedressers.",
        6: "'ach SoH DIchDaq taH named the lalDan vumwI'pu' vo' joH'a'; loDpu' DichDaq ja' SoH the ministers vo' maj joH'a': SoH DichDaq Sop the wealth vo' the tuqpu', je SoH DichDaq boast Daq chaj batlh.",
        7: "Instead vo' lIj tuH SoH DIchDaq ghaj double; je instead vo' dishonor chaH DIchDaq yItIv Daq chaj portion: vaj Daq chaj puH chaH DIchDaq ghaj double; everlasting Quch DIchDaq taH Daq chaH.",
        8: "“vaD jIH, joH'a', muSHa' ruv, jIH hate robbery tlhej He'taHghach; je jIH DichDaq nob chaH chaj recompense Daq vIt, je jIH DichDaq chenmoH an everlasting lay' tlhej chaH.",
        9: "chaj tIr DIchDaq taH Sovta' among the tuqpu', je chaj offspring among the ghotpu'; Hoch 'Iv legh chaH DIchDaq acknowledge chaH, vetlh chaH 'oH the tIr nuq joH'a' ghajtaH ghurtaH.”",
        10: "jIH DichDaq greatly yItIv Daq joH'a', wIj qa' DIchDaq taH joyful Daq wIj joH'a'; vaD ghaH ghajtaH clothed jIH tlhej the garments vo' toDtaHghach, ghaH ghajtaH covered jIH tlhej the robe vo' QaQtaHghach, as a bridegroom decks himself tlhej a garland, je as a bride adorns herself tlhej Daj jewels.",
        11: "vaD as the tera' brings vo' its bud, je as the wIjghachHom causes the Dochmey vetlh 'oH sown Daq 'oH Daq spring vo'; vaj the joH joH'a' DichDaq cause QaQtaHghach je naD Daq spring vo' qaSpa' Hoch the tuqpu'.",
    },
    62: {
        1: "vaD Zion's chIch DichDaq jIH ghobe' 'uch wIj roj, je vaD Jerusalem's chIch jIH DichDaq ghobe' leS, until Daj QaQtaHghach jaH vo' as brightness, je Daj toDtaHghach as a lamp vetlh burns.",
        2: "The tuqpu' DIchDaq legh lIj QaQtaHghach, je Hoch joHpu' lIj batlh, je SoH DIchDaq taH ja' Sum a chu' pong, nuq the nujDu' vo' joH'a' DIchDaq pong.",
        3: "SoH DIchDaq je taH a crown vo' 'IhtaHghach Daq the ghop vo' joH'a', je a royal diadem Daq the ghop vo' lIj joH'a'.",
        4: "SoH DIchDaq ghobe' latlh taH termed lonta'; ghobe' DIchDaq lIj puH vay' latlh taH termed moB: 'ach SoH DIchDaq taH ja' Hephzibah, je lIj puH Beulah; vaD joH'a' delights Daq SoH, je lIj puH DIchDaq taH married.",
        5: "vaD as a Qup loD marries a virgin, vaj lIj puqloDpu' DIchDaq marry SoH; je as the bridegroom rejoices Dung the bride, vaj lIj joH'a' DichDaq yItIv Dung SoH.",
        6: "jIH ghaj cher watchmen Daq lIj walls, Jerusalem; chaH DIchDaq never 'uch chaj roj jaj ghobe' ram: SoH 'Iv ja' Daq joH'a', tlhap ghobe' leS,",
        7: "je nob ghaH ghobe' leS, until ghaH establishes, je until ghaH chen Jerusalem a naD Daq the tera'.",
        8: "joH'a' ghajtaH sworn Sum Daj nIH ghop, je Sum the arm vo' Daj HoS, “DIch jIH DichDaq ghobe' latlh nob lIj grain Daq taH Soj vaD lIj jaghpu'; je foreigners DIchDaq ghobe' tlhutlh lIj chu' HIq, vaD nuq SoH ghaj labored:",
        9: "'ach chaH 'Iv ghaj garnered 'oH DIchDaq Sop 'oH, je naD joH'a'; je chaH 'Iv ghaj boSta' 'oH DIchDaq tlhutlh 'oH Daq the bo'DIjmey vo' wIj Daq QaD.”",
        10: "jaH vegh, jaH vegh the lojmItmey! ghuH the way vo' the ghotpu! chuH Dung, chuH Dung the highway! tay'moH pa' the naghmey! Lift Dung a banner vaD the ghotpu'.",
        11: "yIlegh, joH'a' ghajtaH proclaimed Daq the pItlh vo' the tera', “jatlh Daq the puqbe' vo' Zion, ‘yIlegh, lIj toDtaHghach choltaH. yIlegh, Daj pop ghaH tlhej ghaH, je Daj recompense qaSpa' ghaH.'”",
        12: "chaH DIchDaq ja' chaH The le' ghotpu, The toDta' vo' joH'a': je SoH DIchDaq taH ja' nejta' pa', A veng ghobe' lonta'.",
    },
    63: {
        1: "'Iv ghaH vam 'Iv choltaH vo' Edom, tlhej dyed garments vo' Bozrah? vam 'Iv ghaH glorious Daq Daj Sut, marching Daq the greatness vo' Daj HoS? “'oH ghaH jIH 'Iv jatlh Daq QaQtaHghach, HoS Daq toD.”",
        2: "qatlh 'oH SoH Doq Daq lIj Sut, je lIj garments rur ghaH 'Iv treads Daq the HIq vat?",
        3: "“jIH ghaj trodden the winepress mob; je vo' the ghotpu' pa' ghaHta' ghobe' loD tlhej jIH: HIja', jIH trod chaH Daq wIj QeH, je trampled chaH Daq wIj QeHpu'; je chaj lifeblood ghaH sprinkled Daq wIj garments, je jIH ghaj stained Hoch wIj Sut.",
        4: "vaD the jaj vo' vengeance ghaHta' Daq wIj tIq, je the DIS vo' wIj toDta' ghaH ghoS.",
        5: "jIH nejta', je pa' ghaHta' pagh Daq QaH; je jIH wondered vetlh pa' ghaHta' pagh Daq uphold: vaj wIj ghaj arm qempu' toDtaHghach Daq jIH; je wIj QeHpu', 'oH upheld jIH.",
        6: "jIH trod bIng the ghotpu' Daq wIj QeH, je chenmoHta' chaH drunk Daq wIj QeHpu', je jIH poured pa' chaj lifeblood Daq the tera'.”",
        7: "jIH DichDaq chenmoH mention vo' the muSHa'taH kindnesses vo' joH'a', je the praises vo' joH'a', according Daq Hoch vetlh joH'a' ghajtaH bestowed Daq maH, je the Dun QaQ toward the tuq vo' Israel, nuq ghaH ghajtaH bestowed Daq chaH according Daq Daj mercies, je according Daq the qevmey vo' Daj muSHa'taH kindnesses.",
        8: "vaD ghaH ja'ta', “DIch, chaH 'oH wIj ghotpu, puqpu' 'Iv DichDaq ghobe' Da falsely:” vaj ghaH ghaHta' chaj toDwI'.",
        9: "Daq Hoch chaj affliction ghaH ghaHta' afflicted, je the Duy vo' Daj Daq toDpu' chaH: Daq Daj muSHa' je Daq Daj pity ghaH toDta' chaH; je ghaH boghmoH chaH, je qengta' chaH Hoch the jajmey vo' qan.",
        10: "'ach chaH lotlhpu', je grieved Daj le' qa': vaj ghaH ghaHta' tlhe'ta' Daq taH chaj jagh, je himself Suvta' Daq chaH.",
        11: "vaj ghaH remembered the jajmey vo' qan, Moses je Daj ghotpu, ja'ta', nuqDaq ghaH ghaH 'Iv qempu' chaH Dung pa' vo' the biQ'a' tlhej the shepherds vo' Daj flock? nuqDaq ghaH ghaH 'Iv lan Daj le' qa' Daq the midst vo' chaH?",
        12: "'Iv caused Daj glorious arm Daq jaH Daq the nIH ghop vo' Moses? 'Iv divided the bIQmey qaSpa' chaH, Daq chenmoH himself an everlasting pong?",
        13: "'Iv led chaH vegh the depths, as a horse Daq the ngem, vaj vetlh chaH ta'be' stumble?",
        14: "As the livestock vetlh jaH bIng Daq the ngech, the qa' vo' joH'a' caused chaH Daq leS; vaj SoH led lIj ghotpu, Daq chenmoH SoH'egh a glorious pong.",
        15: "legh bIng vo' chal, je legh vo' the juH vo' lIj holiness je vo' lIj batlh: nuqDaq 'oH lIj zeal je lIj HoS ta'mey? the yearning vo' lIj tIq je lIj compassion ghaH restrained toward jIH.",
        16: "vaD SoH 'oH maj vav, 'a' Abraham ta'be' Sov maH, je Israel ta'taH ghobe' acknowledge maH: SoH, joH'a', 'oH maj vav; maj Redeemer vo' everlasting ghaH lIj pong.",
        17: "toH joH'a', qatlh ta' SoH chenmoH maH Daq err vo' lIj Hemey, je harden maj tIq vo' lIj taHvIp? chegh vaD lIj servants' chIch, the tuqpu' vo' lIj inheritance.",
        18: "lIj le' ghotpu possessed 'oH 'ach a mach qaStaHvIS: maj jaghpu' ghaj trodden bIng lIj Daq QaD.",
        19: "maH ghaj moj as chaH Dung 'Iv SoH never SIQ rule, as chaH 'Iv were ghobe' ja' Sum lIj pong.",
    },
    64: {
        1: 'Oh vetlh SoH would tear the chal, vetlh SoH would ghoS bIng, vetlh the Hudmey might quake Daq lIj Daq,',
        2: "as ghorgh qul kindles the brushwood, je the qul causes the bIQmey Daq boil; Daq chenmoH lIj pong Sovta' Daq lIj jaghpu', vetlh the tuqpu' may tremble Daq lIj Daq!",
        3: "ghorgh SoH ta'ta' awesome Dochmey nuq maH ta'be' legh vaD, SoH ghoSta' bIng, the Hudmey quaked Daq lIj Daq.",
        4: "vaD vo' vo' qan loDpu' ghaj ghobe' Qoyta', ghobe' perceived Sum the qogh, ghobe' ghajtaH the mIn leghpu' a joH'a' je SoH, 'Iv vum vaD ghaH 'Iv waits vaD ghaH.",
        5: "SoH ghom ghaH 'Iv rejoices je vum QaQtaHghach, chaH 'Iv qaw SoH Daq lIj Hemey. yIlegh, SoH were angry, je maH yempu'. maH ghaj taH Daq yem vaD a tIq poH; je DIchDaq maH taH toDpu'?",
        6: "vaD maH ghaj Hoch moj as wa' 'Iv ghaH Say'Ha', je Hoch maj QaQtaHghach ghaH as a polluted garment: je maH Hoch fade as a Sornav; je maj iniquities, rur the SuS, tlhap maH DoH.",
        7: "pa' ghaH pagh 'Iv calls Daq lIj pong, 'Iv stirs Dung himself Daq tlhap 'uch vo' SoH; vaD SoH ghaj hid lIj qab vo' maH, je ghaj Soppu' maH Sum means vo' maj iniquities.",
        8: "'ach DaH, joH'a', SoH 'oH maj vav; maH 'oH the clay, je SoH maj potter; je maH Hoch 'oH the vum vo' lIj ghop.",
        9: "yImev taH furious, joH'a', ghobe' qaw He'taHghach reH: legh, legh, maH beg SoH, maH 'oH Hoch lIj ghotpu.",
        10: "lIj le' vengmey 'oH moj a ngem, Zion ghaH moj a ngem, Jerusalem a desolation.",
        11: "maj le' je maj 'IH tuq, nuqDaq maj vavpu' praised SoH, ghaH meQpu' tlhej qul; je Hoch maj bel Daqmey 'oH laid waste.",
        12: "DichDaq SoH refrain SoH'egh vaD Dochvammey Dochmey, joH'a'? DichDaq SoH 'uch lIj roj, je afflict maH very 'oy'?",
    },
    65: {
        1: "“jIH 'oH inquired vo' Sum chaH 'Iv ta'be' tlhob; jIH 'oH tu'ta' Sum chaH 'Iv ta'be' nej jIH: jIH ja'ta', legh jIH, legh jIH, Daq a Hatlh vetlh ghaHta' ghobe' ja' Sum wIj pong.",
        2: "jIH ghaj ngeH pa' wIj ghopmey Hoch the jaj Daq a lotlhqu' ghotpu, 'Iv yIt Daq a way vetlh ghaH ghobe' QaQ, after chaj ghaj thoughts;",
        3: "a ghotpu 'Iv provoke jIH Daq wIj qab continually, sacrificing Daq wIjghachHommey, je burning He' Daq bricks;",
        4: "'Iv ba' among the graves, je juH Daq the pegh Daqmey; 'Iv Sop pig's ghab, je broth vo' abominable Dochmey ghaH Daq chaj Dujmey;",
        5: "'Iv jatlh, Qam Sum SoH'egh, yImev ghoS Sum Daq jIH, vaD jIH 'oH holier than SoH. Dochvammey 'oH a tlhIch Daq wIj nose, a qul vetlh burns Hoch the jaj.",
        6: "“yIlegh, 'oH ghaH ghItlhta' qaSpa' jIH: jIH DichDaq ghobe' pol tammoH, 'ach DichDaq recompense, HIja', jIH DichDaq recompense Daq chaj bosom,",
        7: "lIj ghaj iniquities, je the iniquities vo' lIj vavpu' tay',” jatlhtaH joH'a', “'Iv ghaj meQpu' He' Daq the Hudmey, je blasphemed jIH Daq the hills; vaj DichDaq jIH wa'Dich juv chaj vum Daq chaj bosom.”",
        8: "Thus jatlhtaH joH'a', “As the chu' HIq ghaH tu'ta' Daq the cluster, je wa' jatlhtaH, ‘yImev Qaw' 'oH, vaD a blessing ghaH Daq 'oH:' vaj DichDaq jIH ta' vaD wIj servants' chIch, vetlh jIH may ghobe' Qaw' chaH Hoch.",
        9: "jIH DichDaq qem vo' a tIr pa' vo' Jacob, je pa' vo' Judah an inheritor vo' wIj Hudmey; je wIj wIvpu' DIchDaq inherit 'oH, je wIj toy'wI'pu' DIchDaq yIn pa'.",
        10: "Sharon DIchDaq taH a fold vo' flocks, je the ngech vo' Achor a Daq vaD herds Daq Qot bIng Daq, vaD wIj ghotpu 'Iv ghaj nejta' jIH.",
        11: "“'ach SoH 'Iv lon joH'a', 'Iv forget wIj le' HuD, 'Iv ghuH a SopDaq vaD Fortune, je 'Iv fill Dung DuD HIq Daq Destiny;",
        12: "jIH DichDaq destine SoH Daq the 'etlh, je SoH DIchDaq Hoch bow bIng Daq the HoHqu'; because ghorgh jIH ja', SoH ta'ta' ghobe' jang; ghorgh jIH jatlhta', SoH ta'ta' ghobe' Qoy; 'ach SoH ta'ta' vetlh nuq ghaHta' mIghtaHghach Daq wIj mInDu', je chose vetlh Daq nuq jIH ta'be' tIv.”",
        13: "vaj thus jatlhtaH the joH joH'a', “yIlegh, wIj toy'wI'pu' DIchDaq Sop, 'ach SoH DIchDaq taH hungry; yIlegh, wIj toy'wI'pu' DIchDaq tlhutlh, 'ach SoH DIchDaq taH thirsty; yIlegh, wIj toy'wI'pu' DIchDaq yItIv, 'ach SoH DIchDaq taH disappointed;",
        14: "yIlegh, wIj toy'wI'pu' DIchDaq bom vaD Quch vo' tIq, 'ach SoH DIchDaq SaQ vaD QoSqu' vo' tIq, je DIchDaq wail vaD anguish vo' qa'.",
        15: "SoH DIchDaq mej lIj pong vaD a mu'qaD Daq wIj wIvpu'; je the joH joH'a' DichDaq HoH SoH; je ghaH DichDaq ja' Daj toy'wI'pu' Sum another pong:",
        16: "vaj vetlh ghaH 'Iv ghurmoHtaH himself Daq the tera' DIchDaq ghurmoH himself Daq the joH'a' vo' vIt; je ghaH 'Iv swears Daq the tera' DIchDaq swear Sum the joH'a' vo' vIt; because the former troubles 'oH forgotten, je because chaH 'oH hid vo' wIj mInDu'.",
        17: "“vaD, yIlegh, jIH create chu' chal je a chu' tera'; je the former Dochmey DIchDaq ghobe' taH remembered, ghobe' ghoS Daq yab.",
        18: "'ach taH SoH Quchqu' je yItIv reH Daq vetlh nuq jIH create; vaD, yIlegh, jIH create Jerusalem a rejoicing, je Daj ghotpu a Quch.",
        19: "jIH DichDaq yItIv Daq Jerusalem, je Quch Daq wIj ghotpu; je pa' DIchDaq taH Qoyta' Daq Daj ghobe' latlh the ghogh vo' weeping je the ghogh vo' crying.",
        20: "“pa' DIchDaq taH ghobe' latlh pa' an infant vo' jajmey, ghobe' an qan loD 'Iv ghajtaH ghobe' tebta' Daj jajmey; vaD the puq DIchDaq Hegh wa' vatlh DISmey qan, je the yemwI' taH wa' vatlh DISmey qan DIchDaq taH accursed.",
        21: "chaH DIchDaq chen juHmey, je inhabit chaH; je chaH DIchDaq plant vineyards, je Sop the baQ vo' chaH.",
        22: "chaH DIchDaq ghobe' chen, je another inhabit; chaH DIchDaq ghobe' plant, je another Sop: vaD as the jajmey vo' a Sor DIchDaq taH the jajmey vo' wIj ghotpu, je wIj wIvpu' DIchDaq tIq enjoy the vum vo' chaj ghopmey.",
        23: "chaH DIchDaq ghobe' labor Daq lI'be', ghobe' qem vo' vaD calamity; vaD chaH 'oH the tIr vo' the ghurtaH vo' joH'a', je chaj offspring tlhej chaH.",
        24: "'oH DIchDaq qaS vetlh, qaSpa' chaH ja', jIH DichDaq jang; je qaStaHvIS chaH 'oH yet speaking, jIH DichDaq Qoy.",
        25: "The wolf je the lamb DIchDaq feed tay', je the HaDI'baH DIchDaq Sop straw rur the Qa'; je dust DIchDaq taH the serpent's Soj. chaH DIchDaq ghobe' hurt ghobe' Qaw' Daq Hoch wIj le' HuD,” jatlhtaH joH'a'.",
    },
    66: {
        1: "Thus jatlhtaH joH'a', “chal ghaH wIj quS'a', je the tera' ghaH wIj footstool: nuq Da vo' tuq DichDaq SoH chen Daq jIH? je nuq Daq DIchDaq taH wIj leS?",
        2: "vaD Hoch Dochvammey Dochmey ghajtaH wIj ghop chenmoHta', je vaj Hoch Dochvammey Dochmey ghoSta' Daq taH,” jatlhtaH joH'a': “'ach Daq vam loD DichDaq jIH legh, 'ach Daq ghaH 'Iv ghaH mIpHa' je vo' a contrite qa', je 'Iv trembles Daq wIj mu'.",
        3: "ghaH 'Iv kills an Qa' ghaH as ghaH 'Iv kills a loD; ghaH 'Iv nobmey a lamb, as ghaH 'Iv breaks a dog's neck; ghaH 'Iv offers an cha'nob, as ghaH 'Iv offers pig's 'Iw; ghaH 'Iv burns frankincense, as ghaH 'Iv ghurmoHtaH an idol. HIja', chaH ghaj wIvpu' chaj ghaj Hemey, je chaj qa' delights Daq chaj qabqu'boghghachmey:",
        4: "jIH je DichDaq choose chaj delusions, je DichDaq qem chaj fears Daq chaH; because ghorgh jIH ja', pagh ta'ta' jang; ghorgh jIH jatlhta', chaH ta'ta' ghobe' Qoy: 'ach chaH ta'ta' vetlh nuq ghaHta' mIghtaHghach Daq wIj mInDu', je chose vetlh Daq nuq jIH ta'be' tIv.”",
        5: "Qoy the mu' vo' joH'a', SoH 'Iv tremble Daq Daj mu': “lIj loDnI'pu' 'Iv hate SoH, 'Iv chuH SoH pa' vaD wIj pong chIch, ghaj ja'ta', ‘chaw' joH'a' taH glorified, vetlh maH may legh lIj Quch;' 'ach 'oH ghaH chaH 'Iv DIchDaq taH disappointed.",
        6: "A ghogh vo' tumult vo' the veng, a ghogh vo' the lalDan qach, a ghogh vo' joH'a' vetlh renders recompense Daq Daj jaghpu'.",
        7: "“qaSpa' ghaH travailed, ghaH qempu' vo'; qaSpa' Daj pain ghoSta', ghaH toDta' a puqloD.",
        8: "'Iv ghajtaH Qoyta' such a Doch? 'Iv ghajtaH leghpu' such Dochmey? DIchDaq a puH taH bogh Daq wa' jaj? DIchDaq a Hatlh taH qempu' vo' Daq once? vaD as soon as Zion travailed, ghaH qempu' vo' Daj puqpu'.",
        9: "DIchDaq jIH qem Daq the birth, je ghobe' cause Daq qem vo'?” jatlhtaH joH'a': “DIchDaq jIH 'Iv cause Daq qem vo' shut the womb?” jatlhtaH lIj joH'a'.",
        10: "“yItIv tlhej Jerusalem, je taH Quchqu' vaD Daj, Hoch SoH 'Iv muSHa' Daj: yItIv vaD Quch tlhej Daj, Hoch SoH 'Iv mourn Dung Daj;",
        11: "vetlh SoH may nurse je taH satisfied Daq the comforting breasts; vetlh SoH may tlhutlh deeply, je taH delighted tlhej the abundance vo' Daj batlh.”",
        12: "vaD thus jatlhtaH joH'a', “yIlegh, jIH DichDaq extend roj Daq Daj rur a bIQtIQ, je the batlh vo' the tuqpu' rur an overflowing stream: je SoH DichDaq nurse. SoH DichDaq taH qengta' Daq Daj retlh, je DichDaq taH dandled Daq Daj knees.",
        13: "As wa' 'Iv Daj SoS comforts, vaj DichDaq jIH belmoH SoH; je SoH DichDaq taH comforted Daq Jerusalem.”",
        14: "SoH DichDaq legh 'oH, je lIj tIq DIchDaq yItIv, je lIj HomDu' DIchDaq flourish rur the tender grass: je the ghop vo' joH'a' DIchDaq taH Sovta' toward Daj toy'wI'pu'; je ghaH DichDaq ghaj indignation Daq Daj jaghpu'.",
        15: "vaD, yIlegh, joH'a' DichDaq ghoS tlhej qul, je Daj Dujmey DIchDaq taH rur the whirlwind; Daq render Daj QeH tlhej fierceness, je Daj rebuke tlhej flames vo' qul.",
        16: "vaD Sum qul DichDaq joH'a' execute yoj, je Sum Daj 'etlh, Daq Hoch ghab; je the Heghta' vo' joH'a' DIchDaq taH law'.",
        17: "“chaH 'Iv sanctify themselves je purify themselves Daq jaH Daq the wIjghachHommey, behind wa' Daq the midst, eating pig's ghab, je the qabqu'boghghach, je the mouse, chaH DIchDaq ghoS Daq an pItlh tay',” jatlhtaH joH'a'.",
        18: "“vaD jIH Sov chaj vum je chaj thoughts: the poH choltaH, vetlh jIH DichDaq tay'moH Hoch tuqpu' je languages; je chaH DIchDaq ghoS, je DIchDaq legh wIj batlh.",
        19: "“jIH DichDaq cher a sign among chaH, je jIH DichDaq ngeH such as escape vo' chaH Daq the tuqpu', Daq Tarshish, Pul, je Lud, 'Iv draw the bow, Daq Tubal je Javan, Daq the islands afar litHa', 'Iv ghaj ghobe' Qoyta' wIj fame, ghobe' ghaj leghpu' wIj batlh; je chaH DIchDaq declare wIj batlh among the tuqpu'.",
        20: "chaH DIchDaq qem Hoch lIj loDnI'pu' pa' vo' Hoch the tuqpu' vaD an cha'nob Daq joH'a', Daq horses, je Daq Dujmey, je Daq litters, je Daq mules, je Daq dromedaries, Daq wIj le' HuD Jerusalem, jatlhtaH joH'a', as the puqpu' vo' Israel qem chaj cha'nob Daq a Say vessel Daq the tuq vo' joH'a'.",
        21: "vo' chaH je DichDaq jIH tlhap vaD lalDan vumwI'pu' je vaD Levites,” jatlhtaH joH'a'.",
        22: "“vaD as the chu' chal je the chu' tera', nuq jIH DichDaq chenmoH, DIchDaq remain qaSpa' jIH,” jatlhtaH joH'a', “vaj lIj tIr je lIj pong DIchDaq remain.",
        23: "'oH DIchDaq qaS, vetlh vo' wa' chu' maS Daq another, je vo' wa' jaj SochDIch Daq another, DIchDaq Hoch ghab ghoS Daq lalDan toy' qaSpa' jIH,” jatlhtaH joH'a'.",
        24: "“chaH DIchDaq jaH vo', je legh Daq the Heghpu' porghmey vo' the loDpu' 'Iv ghaj transgressed Daq jIH: vaD chaj worm DIchDaq ghobe' Hegh, ghobe' DIchDaq chaj qul taH quenched; je chaH DichDaq taH loathsome Daq Hoch mankind.”",
    },
}
